const int N = 123;

const ll mod = 1e9 + 7;

int n;

struct mtx {

  ll a[N][N], len = n;

  mtx() { memset(a, 0, sizeof(a)); }

  void operator*=(mtx b) {

    int res[N][N];

    memset(res, 0, sizeof(res));

    for (int i = 1; i <= len; i++) {

      for (int j = 1; j <= len; j++) {

        for (int k = 1; k <= len; k++) {

          res[i][j] = (res[i][j] + a[i][k] * b.a[k][j]) % mod;
        }
      }
    }

    for (int i = 1; i <= len; i++) {

      for (int j = 1; j <= len; j++) {

        a[i][j] = res[i][j];
      }
    }
  }
};

mtx bin_pow(mtx x, ll y) {

  mtx res;

  for (int i = 1; i <= n; i++) {

    res.a[i][i] = 1;
  }

  while (y) {

    if (y & 1LL)

      res *= x;

    x *= x;

    y >>= 1LL;
  }

  return res;
}

