class Z {

public:
  struct Line {

    ll k, m;

    mutable ll p;

    bool operator<(const Line &o) const { return k < o.k; }

    bool operator<(const ll &x) const { return p < x; }
  };

  struct LineContainer : multiset<Line, less<>> {

    const ll inf = numeric_limits<ll>::max();

    ll div(ll a, ll b) { return a / b - ((a ^ b) < 0 && a % b); }

    bool isect(iterator x, iterator y) {

      if (y == end()) {
        x->p = inf;
        return false;
      }

      if (x->k == y->k)
        x->p = x->m > y->m ? inf : -inf;

      else
        x->p = div(y->m - x->m, x->k - y->k);

      return x->p >= y->p;
    }

    void add(ll k, ll m) {

      auto z = insert({k, m, 0}), y = z++, x = y;

      while (isect(y, z))
        z = erase(z);

      if (x != begin() && isect(--x, y))
        isect(x, y = erase(y));

      while ((y = x) != begin() && (--x)->p >= y->p)

        isect(x, erase(y));
    }

    ll query(ll x) {

      assert(!empty());

      auto l = *lower_bound(x);

      return l.k * x + l.m;
    }
  };

  void solve() {

    ll c, a[200005] = {};

    int n;

    cin >> n >> c;

    for (int i = 0; i < n; i++)
      cin >> a[i];

    LineContainer lc;

    lc.add(0, 0);

    ll f = 0;

    for (int i = 0; i < n; i++) {

      f = lc.query(a[i]);

      f -= a[i] * a[i] + c;

      if (!i)
        f = 0;

      lc.add(a[i] + a[i], -a[i] * a[i] + f);
    }

    cout << -f;
  }
};

