  void build(int l, int r, int n) {

    if (l == r) {

      tree[n] = (l == 0 ? S[l] : S[l] - S[l - 1]);

      return;
    }

    int m = (l + r) >> 1;

    build(l, m, 2 * n);

    build(m + 1, r, 2 * n + 1);

    tree[n] = min(tree[2 * n], tree[2 * n + 1]);
  }

  ll quer(int a, int b, int l, int r, int n) {

    if (b < l || r < a)
      return 1e18;

    if (a <= l && r <= b)
      return tree[n];

    int m = (l + r) >> 1;

    ll L = quer(a, b, l, m, 2 * n);

    ll R = quer(a, b, m + 1, r, 2 * n + 1);

    return min(L, R);
  }

} bit;

int cc[100010];

int dp(int idx) {

  int &ret = cc[idx];

  if (ret != -1)
    return ret;

  if (idx == N)
    return ret = 1;

  ret = 0;

  if (idx == 0 || S[idx] - S[idx - 1] >= B) {

    ret += dp(idx + 1);

    ret %= mod;
  }

