void YYCH() {
  for (int i = 1; i <= n; ++i)
    fa[i] = i, siz[i] = 1;
}

int find(int x) { return x == fa[x] ? fa[x] : fa[x] = find(fa[x]); }

void he(int x, int y)

{

  x = find(x);
  y = find(y);
  if (x == y)
    return;

  fa[x] = y;
  siz[y] += siz[x];
}

