class MaxFlow {

public:
  struct edge {
    ll to, cap, rev;
  };

  vector<edge> G[MAX_FLOW_MAX_V];

  bool used[MAX_FLOW_MAX_V];

  ll level[MAX_FLOW_MAX_V];

  ll iter[MAX_FLOW_MAX_V];

  void init() {

    for (ll i = 0; i < MAX_FLOW_MAX_V; i++) {

      G[i].clear();
    }
  }

  void add_edge(ll from, ll to, ll cap) {

    G[from].push_back((edge){to, cap, (ll)G[to].size()});

    G[to].push_back((edge){from, 0, (ll)G[from].size() - 1});
  }

  void add_undirected_edge(ll e1, ll e2, ll cap) {

    G[e1].push_back((edge){e2, cap, (ll)G[e2].size()});

    G[e2].push_back((edge){e1, cap, (ll)G[e1].size() - 1});
  }

  ll dfs(ll v, ll t, ll f) {

    if (v == t)
      return f;

    used[v] = true;

    for (ll i = 0; i < (ll)G[v].size(); i++) {

      edge &e = G[v][i];

      if (!used[e.to] && e.cap > 0) {

        ll d = dfs(e.to, t, min(f, e.cap));

        if (d > 0) {

          e.cap -= d;

          G[e.to][e.rev].cap += d;

          return d;
        }
      }
    }

    return 0;
  }

  ll max_flow(ll s, ll t) {

    ll flow = 0;

    while (1) {

      memset(used, 0, sizeof(used));

      ll f = dfs(s, t, INF);

      if (f == 0)
        return flow;

      flow += f;
    }
  }

  void bfs(ll s) {

    memset(level, -1, sizeof(level));

    queue<ll> que;

    level[s] = 0;

    que.push(s);

    while (!que.empty()) {

      ll v = que.front();
      que.pop();

      for (ll i = 0; i < (ll)G[v].size(); i++) {

        edge &e = G[v][i];

        if (e.cap > 0 && level[e.to] < 0) {

          level[e.to] = level[v] + 1;

          que.push(e.to);
        }
      }
    }
  }

  ll dinic_dfs(ll v, ll t, ll f) {

    if (v == t)
      return f;

    for (ll &i = iter[v]; i < (ll)G[v].size(); i++) {

      edge &e = G[v][i];

      if (e.cap > 0 && level[v] < level[e.to]) {

        ll d = dinic_dfs(e.to, t, min(f, e.cap));

        if (d > 0) {

          e.cap -= d;

          G[e.to][e.rev].cap += d;

          return d;
        }
      }
    }

    return 0;
  }

  ll dinic(ll s, ll t) {

    ll flow = 0;

    while (1) {

      bfs(s);

      if (level[t] < 0)
        return flow;

      memset(iter, 0, sizeof(iter));

      ll f;

      while ((f = dinic_dfs(s, t, INF)) > 0) {

        flow += f;
      }
    }
  }
};

class BipartiteMatching {

  vector<ll> pre, root;

  vector<vector<ll>> to;

  vector<ll> p, q;

  ll n, m;

public:
  BipartiteMatching(ll n, ll m)
      : pre(n, -1), root(n, -1), to(n), p(n, -1), q(m, -1), n(n), m(m) {}

  void add(ll a, ll b) { to[a].push_back(b); }

  ll solve() {

    ll res = 0;

    bool upd = true;

    while (upd) {

      upd = false;

      queue<ll> s;

      for (ll i = 0; i < n; ++i) {

        if (!~p[i]) {

          root[i] = i;

          s.push(i);
        }
      }

      while (!s.empty()) {

        ll v = s.front();
        s.pop();

        if (~p[root[v]])
          continue;

        for (ll i = 0; i < (ll)to[v].size(); ++i) {

          ll u = to[v][i];

          if (!~q[u]) {

            while (~u) {

              q[u] = v;

              swap(p[v], u);

              v = pre[v];
            }

            upd = true;

            ++res;

            break;
          }

          u = q[u];

          if (~pre[u])
            continue;

          pre[u] = v;
          root[u] = root[v];

          s.push(u);
        }
      }

      if (upd)
        fill(pre.begin(), pre.end(), -1), fill(root.begin(), root.end(), -1);
    }

    return res;
  }
};

class MinCostFlow {

public:
  struct edge {
    ll to, cap, cost, rev;
  };

