  scanf("%lld", &n);

  for (int i = 0; ++i <= n;)
    for (int j = 0; ++j <= n; i == j ?: scanf("%lld", &a[i][j]))
      ;
}

long long gg(int k, int lx, int ly, int rx, int ry) {

  return g[k][rx][ry] - g[k][lx - 1][ry] - g[k][rx][ly - 1] +
         g[k][lx - 1][ly - 1];
}

void work() {

  for (int i = 0; ++i <= n;) {

    for (int j = 0; ++j <= n;
         i >= j ?: g[0][i][j] = a[i][j], g[0][i][j] += g[0][i][j - 1])
      ;

    for (int j = 0; ++j <= n; g[0][i][j] += g[0][i - 1][j])
      ;
  }

  for (int i = 0; ++i <= n;) {

    for (int j = 0; ++j <= n;
