#include <set>

using namespace std;

#define TOP 2

#define RIGHT 1

typedef pair<int, int> P;

map<P, P> graph;

set<P> isLeg;

set<P> isHead;

int dx[] = {0, 1, 0, -1};

int dy[] = {-1, 0, 1, 0};

bool dfs(P leg, P head) {

  isLeg.insert(leg);

  isHead.insert(head);

  for (int i = 0; i < 4; i++) {

    P nleg(leg.first + dx[i], leg.second + dy[i]);

    if (nleg == head)
      continue;

    if (isHead.find(nleg) != isHead.end())
      return false;

    if (isLeg.find(nleg) != isLeg.end())
      continue;

    if (graph.find(nleg) == graph.end())
      continue;

    P nhead = graph[nleg];

    if (!dfs(nleg, nhead))
      return false;
  }

  for (int i = 0; i < 4; i++) {

    P nhead(head.first + dx[i], head.second + dy[i]);

    if (nhead == leg)
      continue;

    if (isHead.find(nhead) != isHead.end())
      continue;

    if (isLeg.find(nhead) != isLeg.end())
      return false;

    if (graph.find(nhead) == graph.end())
      continue;

    P nleg = graph[nhead];

    if (!dfs(nleg, nhead))
      return false;
  }

  return true;
}

bool solve() {

  isHead.clear();

  isLeg.clear();

  map<P, P>::iterator iter = graph.begin();

  for (; iter != graph.end(); iter++) {

    P head = iter->first;

    P leg = iter->second;

    if (isLeg.find(head) != isLeg.end())
      continue;

    if (isHead.find(head) != isHead.end())
      continue;

    if (!dfs(leg, head))
      return false;
  }

  return true;
}

int main() {

  int n;

  while (cin >> n, n) {

    graph.clear();

    for (int i = 0; i < n; i++) {

      int x, y;

      char dir;

      cin >> x >> y >> dir;

      if (dir == 'x') {

        int nx = x + dx[RIGHT];

        int ny = y + dy[RIGHT];

        graph[P(x, y)] = P(nx, ny);

        graph[P(nx, ny)] = P(x, y);

      }

      else {

        int nx = x + dx[TOP];

        int ny = y + dy[TOP];

        graph[P(x, y)] = P(nx, ny);

        graph[P(nx, ny)] = P(x, y);
      }
    }

    cout << (solve() ? "Yes" : "No") << endl;
  }
}
