long long K;

int main() {

  scanf("%d %lld", &N, &K);

  for (int i = 0; i < N; i++)

    scanf("%d", &A[i]);

  memset(prv, -1, sizeof prv);

  for (int i = 0; i < 2 * N; i++) {

    if (prv[A[i % N]] != -1) {

      nxt[prv[A[i % N]]] = i % N;
    }

    prv[A[i % N]] = i % N;
  }

  vector<int> ans;

  memset(vis, -1, sizeof vis);

  int j = 0, k = 0;

  while (k < K) {

    if (nxt[j] > j) {

      j = nxt[j] + 1;

      if (j >= N) {

        j -= N;

        k++;
      }

    } else {

      if (k + 1 < K) {

        j = nxt[j] + 1;

        k++;

        if (j >= N) {

          j -= N;

          k++;
        }

      } else {

        ans.push_back(A[j]);

        j = j + 1;

        if (j >= N)
          break;
      }
    }

    if (vis[j] != -1) {

      int d = k - vis[j];

      K = k + (K - k) % d;
    }

    vis[j] = k;
  }

  for (int i = 0; i < (int)ans.size(); i++) {

    if (i > 0)
      printf(" ");

    printf("%d", ans[i]);
  }

  printf("\n");

  return 0;
}

