    n = 0;                                                                     \
    char ch;                                                                   \
    int f = 0;                                                                 \
    do {                                                                       \
      ch = getchar();                                                          \
      if (ch == '-') {                                                         \
        f = 1;                                                                 \
      }                                                                        \
    } while (ch < '0' || ch > '9');                                            \
    while ('0' <= ch && ch <= '9') {                                           \
      n = (n << 1) + (n << 3) + ch - 48;                                       \
      ch = getchar();                                                          \
    }                                                                          \
    if (f)                                                                     \
      n = -n;                                                                  \
