  memset(f, 0, sizeof(f));

  int now = 0;

  for (int i = 0; i <= n; i++) {

    f[now][i] = 1;
  }

  for (int i = 1; i <= m; i++) {

    now ^= 1;

    for (int j = 0; j <= n; j++) {

      f[now][j] = 0;
    }

    for (int j = 0; j <= n; j++) {

