        f[now][j] = (f[now][j] + f[now ^ 1][j]) % mod;
      }

      if (j < n) {

        f[now][j + 1] = (f[now][j + 1] + f[now ^ 1][j]) % mod;

        f[now][j] = (f[now][j] + f[now ^ 1][j]) % mod;
      }
    }
  }

  int ans = 0;

  for (int i = 0; i <= n; i++) {

    ans = (ans + f[now][i]) % mod;
  }

  return ans;
}

