  A[x] = std::min(A[x << 1], A[x << 1 | 1]);

  B[x] = std::min(B[x << 1], B[x << 1 | 1]);
}

void Insert(int n, int l, int r, int x, long long v) {

  if (l == r) {

    A[n] = std::min(A[n], v - x);
    B[n] = std::min(B[n], v + x);
    return;
  }

  pushDown(n);
  int mid = (l + r) >> 1;

  if (x <= mid)
    Insert(n << 1, l, mid, x, v);

  else
    Insert(n << 1 | 1, mid + 1, r, x, v);

  pushUp(n);
}

void Insert(int n, int l, int r, int L, int R, long long v) {

  if (l == L && r == R) {

    A[n] += v;
    B[n] += v;
    T[n] += v;
    return;
  }

  pushDown(n);
  int mid = (l + r) >> 1;

  if (R <= mid)
    Insert(n << 1, l, mid, L, R, v);

  else if (L > mid)
    Insert(n << 1 | 1, mid + 1, r, L, R, v);

  else
    Insert(n << 1, l, mid, L, mid, v),
        Insert(n << 1 | 1, mid + 1, r, mid + 1, R, v);

  pushUp(n);
}

