  if (l == L && r == R)
    return A[n];

  pushDown(n);
  int mid = (l + r) >> 1;

  if (R <= mid)
    return a(n << 1, l, mid, L, R);

  else if (L > mid)
    return a(n << 1 | 1, mid + 1, r, L, R);

