    x += cor;

    vec[x].first += w;

    while (1) {

      x /= 2;

      if (x == 0)
        break;

      if (vec[2 * x].first <= vec[2 * x + 1].first)
        vec[x] = vec[2 * x];

      else
        vec[x] = vec[2 * x + 1];
    }
  }

