const int mod = 924844033, g = 5;

const unsigned long long bigmod = 20ull * mod * mod;

inline void add(int &x, int y) { (x += y) >= mod ? x -= mod : 0; }

inline int pl(int x, int y) { return (x += y) >= mod ? x - mod : x; }

int kpow(int a, int b)

{

  int s = 1;

  for (; b; b >>= 1, a = 1ll * a * a % mod)

    if (b & 1)
      s = 1ll * s * a % mod;

  return s;
}

namespace poly

{

int w[524288];

void init()

{

  for (int len = 1; len < 524288; len <<= 1)

  {

    int tmp = kpow(g, (mod - 1) / len / 2);

    w[len] = 1;

    for (int j = 1; j < len; ++j)
      w[len + j] = 1ll * w[len + j - 1] * tmp % mod;
  }
}

void ntt(int f[], int opt, int lim)

{

  static int r[524288], now;

  if (now != lim)

  {

    now = lim;

    for (int i = 1; i < lim; ++i)
      r[i] = (r[i >> 1] >> 1) | (i & 1 ? lim >> 1 : 0);
  }

  static unsigned long long t[524288];

  for (int i = 0; i < lim; ++i)
    t[i] = f[r[i]];

  for (int len = 1; len < lim; len <<= 1)

  {

    if (len == 65536)
      for (int i = 0; i < lim; ++i)
        t[i] %= mod;

    for (int j = 0; j < lim; j += len << 1)

      for (int k = 0; k < len; ++k)

      {

        const unsigned long long x = t[j + k + len] * w[len + k] % mod;

        t[j + k + len] = t[j + k] + mod - x, t[j + k] += x;
      }
  }

  for (int i = 0; i < lim; ++i)
    f[i] = t[i] % mod;

  if (opt == -1)

  {

    reverse(f + 1, f + lim);

    int c = kpow(lim, mod - 2);

    for (int i = 0; i < lim; ++i)
      f[i] = 1ll * f[i] * c % mod;
  }
}

void mulT(int a[], int b[], int c[], int na, int nb, int nc)

{

  if (na <= 200)

  {

    static unsigned long long C[210];

    memset(C, 0, nc << 3);

    for (int i = 0; i < na; ++i)

      for (int j = 0; j <= i && j < nb; ++j)

        (C[i - j] += 1ull * a[i] * b[j]) >= bigmod ? C[i - j] -= bigmod : 0;

    for (int i = 0; i < nc; ++i)
      c[i] = C[i] % mod;

    return;
  }

  static int X[524288], Y[524288], lim;

  lim = 1;

  while (lim < na || lim < nb + nc - 1)
    lim <<= 1;

  memcpy(X, a, na << 2);
  memcpy(Y, b, nb << 2);

  reverse(X, X + na);

  ntt(X, 1, lim), ntt(Y, 1, lim);

  for (int i = 0; i < lim; ++i)
    X[i] = 1ll * X[i] * Y[i] % mod;

  ntt(X, -1, lim);

  reverse(X, X + na);

  memcpy(c, X, nc << 2);

  memset(X, 0, lim << 2);
  memset(Y, 0, lim << 2);
}

