inline void addedge(int from, int to) {
  e[++num] = edge{head[from], to};
  head[from] = num;
}

void dfs(int v, int fa)

{

  siz[v] = 1;

  for (int i = head[v], u; i; i = e[i].nxt)

  {

    u = e[i].to;

    if (u == fa)
      continue;

    dfs(u, v);

    siz[v] += siz[u];

    ++a[siz[u]];
  }

  ++a[n - siz[v]];
}

