  for (int i = 0; i < M; i++) {

    int a, b;

    cin >> a >> b;

    edge et = {a, b};

    G[b].push_back(et);

    edge es = {b, a};

    G[a].push_back(es);
  }

  int ans = 0;

  tracePath(1, 0, ans);

  cout << ans << "\n";

  return 0;
}

