template <typename _T, int len>

struct BIT {

  _T dt[len];

  inline void add(int a, _T x) {
    while (a < len) {
      dt[a] += x;
      a += a & -a;
    }
  }

  inline void add(int l, int r, _T x) {
    add(l, x);
    add(r + 1, -x);
  }

  inline _T get(int a) {
    _T ans = 0;
    while (a) {
      ans += dt[a];
      a -= a & -a;
    }
    return ans;
  }

  inline _T get(int l, int r) { return get(r) - get(l - 1); }
};

template <typename _T, int len>

struct segbit {

  _T dt[2][len];

  inline void add(int a, _T x) {
    int b = a;
    while (a < len) {
      dt[0][a] += x;
      dt[1][a] += x * b;
      a += a & -a;
    }
  }

  inline void add(int l, int r, _T x) {
    add(l, x);
    add(r + 1, -x);
  }

  inline _T sum(int a) {
    _T ans = 0;
    int b = a;
    while (a) {
      ans += (b + 1) * dt[0][a] - dt[1][a];
      a -= a & -a;
    }
    return ans;
  }

  inline _T sum(int l, int r) { return sum(r) - sum(l - 1); }
};

