struct Edge {
  int to, capa, flow, next;
} e[4000000];

int h[20010], sum = -1, n, m, S, T;

int mp[110][110], tot = 0;

bool vis[20010];

int d[20010], cur[20010];

void AddEdge(int u, int v, int w)

{

  e[++sum].to = v;

  e[sum].capa = w;

  e[sum].flow = 0;

  e[sum].next = h[u];

  h[u] = sum;
}

void add_edge(int u, int v, int w)

{

  AddEdge(u, v, w);

  AddEdge(v, u, 0);
}

bool BFS()

{

  memset(vis, 0, sizeof(vis));

  queue<int> q;

  vis[S] = 1;
  d[S] = 0;

  q.push(S);

  while (!q.empty())

  {

    int u = q.front();

    for (int tmp = h[u]; ~tmp; tmp = e[tmp].next)

      if (!vis[e[tmp].to] && e[tmp].capa > e[tmp].flow)

      {

        d[e[tmp].to] = d[u] + 1;

        vis[e[tmp].to] = 1;

        q.push(e[tmp].to);
      }

    q.pop();
  }

  return vis[T + tot];
}

int DFS(int u, int a)

{

  if (u == T + tot || a == 0)
    return a;

  int flow = 0, f;

  for (int &tmp = cur[u]; ~tmp; tmp = e[tmp].next)

    if (d[e[tmp].to] == d[u] + 1)

    {

      f = DFS(e[tmp].to, min(a, e[tmp].capa - e[tmp].flow));

      if (f > 0)

      {

        flow += f;
        a -= f;

        e[tmp].flow += f;

        e[tmp ^ 1].flow -= f;

        if (a == 0)
          break;
      }
    }

  return flow;
}

int Dinic()

{

  int flow = 0;

  while (BFS())

  {

    for (int i = 1; i <= 2 * tot; i++)
      cur[i] = h[i];

    flow += DFS(S, INF);
  }

  return flow == INF ? -1 : flow;
}

int main()

{

