using namespace std;

inline int read()

{

  int x = 0, f = 1;
  char ch = getchar();

  while (ch < '0' || ch > '9') {
    if (ch == '-')
      f = -1;
    ch = getchar();
  }

  while (ch >= '0' && ch <= '9') {
    x = x * 10 + ch - '0';
    ch = getchar();
  }

  return x * f;
}

int m;

int main()

{

  m = read();

  while (m--)

  {

    int a = read(), b = read(), lt = read(), rt = read();

    int len = (a + b) / (min(a, b) + 1);

    int l = 1, r = a, mid, res = 0;

    while (l <= r)

    {

      mid = l + r >> 1;

      int cnt = (mid + len - 1) / len;

      int lefta = a - mid, leftb = b - cnt + 1 - len;

      if (1LL * lefta * len < leftb)
        r = mid - 1;

      else
        res = mid, l = mid + 1;
    }

    int cnt = (res + len - 1) / len, prelen = cnt ? cnt - 1 + res : 0;

    int lefta = a - res, leftb = b - max(0, cnt - 1),
        first = leftb - (lefta * len);

    for (int j = lt; j <= rt; ++j)

    {

      if (j <= (cnt - 1) * (len + 1))
        putchar(j % (len + 1) ? 'A' : 'B');

      else if (j <= prelen)
        putchar('A');

      else if (j <= prelen + first)
        putchar('B');

      else
        putchar((j - prelen - first) % (len + 1) == 1 ? 'A' : 'B');
    }

    puts("");
  }

  return 0;
}
