    if (par[u] == u)
      return u;

    return par[u] = find(par[u]);
  }

  void merge(int u, int v) {

    u = find(u), v = find(v);

    if (u != v) {

      par[u] = v;

      sz[v] += sz[u];
    }
  }

  int get(int u) { return sz[find(u)]; }
