const int N = 200005;

int n;

int a[N], tot = 0, h[N];

int dfn[N], low[N], sta[N], dfs_num = 0, top = 0;

vector<int> e[N];

int f[N];

bool vis[N], vis2[N];

void tarjan(int u) {

  dfn[u] = low[u] = ++dfs_num;

  sta[++top] = u;

  for (int i = 0; i < e[u].size(); i++) {

    int v = e[u][i];

    if (!dfn[v]) {

      tarjan(v);

      low[u] = min(low[v], low[u]);

    } else if (!vis2[v])
      low[u] = min(dfn[v], low[u]);
  }

  if (dfn[u] == low[u]) {

    vis2[u] = 1;

    if (sta[top] == u) {

      top--;

      return;
    }

    do {

      vis2[sta[top]] = 1;

      a[++tot] = sta[top];

      h[sta[top]] = 1;

    } while (sta[top--] != u);
  }
}

