  for (int i = 0; i < e[u].size(); i++) {

    int v = e[u][i];

    if (!h[v])
      dfs(v);
  }

  for (int i = 0; i < e[u].size(); i++) {

    int v = e[u][i];

    if (!h[v])
      vis[f[v]] = 1;
  }

  while (vis[f[u]])
    f[u]++;

  for (int i = 0; i < e[u].size(); i++) {

    int v = e[u][i];

    if (!h[v])
      vis[f[v]] = 0;
  }
}

