  ll res = 1ll;

  while (y) {

    if (y & 1)
      res = res * x % Mod;

    x = x * x % Mod;

    y >>= 1;
  }

  return res;
}

ll Com(ll n, ll m) {

  ll res = 1ll;

  for (ll i = n; i >= n - m + 1; i--)
    res = res * i % Mod;

  return res * inv[m] % Mod;
}

