  fac[0] = inv[0] = 1;

  for (int i = 1; i <= maxx; i++)
    fac[i] = fac[i - 1] * i % Mod;

  inv[maxx] = qwe(fac[maxx], Mod - 2);

  for (int i = maxx - 1; i >= 1; i--)
    inv[i] = inv[i + 1] * (i + 1) % Mod;

  scanf("%lld %d %d", &n, &a, &b);

  ll ans = qwe(2, n) - 1;

  ans = (ans - Com(n, a) + Mod) % Mod;

  ans = (ans - Com(n, b) + Mod) % Mod;

  printf("%lld\n", ans);

