  if (vis[v][d])
    return;

  if (color[v] == 0)
    color[v] = c;

  if (d <= 0)
    return;

  for (int i = 0; i < G[v].size(); i++)

  {

    solve(G[v][i], d - 1, c);
  }

  vis[v][d] = 1;
}

