    G[a].push_back(b);

    G[b].push_back(a);
  }

  scanf("%d", &Q);

  for (int i = 0; i < Q; i++)

  {

    scanf("%d %d %d", &q[i].v, &q[i].d, &q[i].c);
  }

  for (int i = Q - 1; i >= 0; i--)

