  double x, y;

  point() { x = y = 0.0; }

  point(double x, double y) : x(x), y(y) {}
};

double dist(point p1, point p2) {

  return hypot(fabs(p1.x - p2.x), fabs(p1.y - p2.y));
}

int main() {

  while (true) {

    int x1, y1, x2, y2, x3, y3;

