    if (x1 == 0 && x2 == 0 && x3 == 0 && y1 == 0 && y2 == 0 && y3 == 0)
      break;

    point ap = point(x1, y1);

    point bp = point(x2, y2);

    point cp = point(x3, y3);

    double a = dist(bp, cp);

    double b = dist(ap, cp);

    double c = dist(ap, bp);

    double s = (a + b + c) / 2;

    double triangleArea = sqrt(s * (s - a) * (s - b) * (s - c));

    double r = triangleArea / s;

    point ip = point((a * ap.x + b * bp.x + c * cp.x) / (a + b + c),
                     (a * ap.y + b * bp.y + c * cp.y) / (a + b + c));

    double d = dist(ip, ap);

    double e = dist(ip, bp);

    double f = dist(ip, cp);

    double r1 = r / (2 * (s - a)) * (s + d - r - e - f);

    double r2 = r / (2 * (s - b)) * (s + e - r - d - f);

    double r3 = r / (2 * (s - c)) * (s + f - r - d - e);

