int sum[N * 4];

void add(int now, int l, int r, int pos) {

  sum[now]++;

  if (l == r)
    return;

  int mid = l + r >> 1;

  if (pos <= mid)
    add(now * 2, l, mid, pos);

  else
    add(now * 2 + 1, mid + 1, r, pos);
}

bool ask(int now, int l, int r, int L, int R) {

  if (l > R || L > r)
    return false;

  if (L <= l && r <= R)
    return (sum[now] != 0);

  int mid = l + r >> 1;

  return ask(now * 2, l, mid, L, R) | ask(now * 2 + 1, mid + 1, r, L, R);
}

bool ask(int pos) { return ask(1, 1, n, 1, pos); }

void add(int pos) { add(1, 1, n, pos); }

bool find(int x, int right) {

  int l = 1, r = n;

  for (int mid = l + r >> 1; l < r; mid = l + r >> 1) {

    if (ls[mid] < x)
      l = mid + 1;

    else
      r = mid;
  }

