using namespace std;

const int maxn = 2e5 + 10;

typedef long long ll;

int raw[maxn];

int main() {

  int n;

  ll ans = 0;

  scanf("%d", &n);

  for (int i = 1; i <= n; i++)
    scanf("%d", &raw[i]);

  sort(&raw[1], &raw[n + 1]);

  for (int i = 1; i <= n; i++)

    for (int j = i; j <= n; j++)

      if (i != j) {

        int a = raw[i], b = raw[j];

        int L = max(a - b, b - a), R = a + b;

        int x = upper_bound(&raw[1], &raw[n + 1], L) - raw;

        int y = lower_bound(&raw[1], &raw[n + 1], R) - raw;

        ans += (y - x) > 0 ? y - x : 0;

        if (x <= i and i <= y)
          ans--;

        if (x <= j and j <= y)
          ans--;
      }

  printf("%lld\n", ans / 3);
}
