  int from, to, next;

} edges[maxm];

char c[maxn];

bool sz[maxn];

inline bool check(int p) {

  char hd;

  if (head[p] < 0)
    return false;

  register int j;

  for (j = head[p]; !sz[edges[j].to]; j = edges[j].next)
    ;

  if (j >= 0)
    hd = c[edges[j].to];

  for (; j >= 0; j = edges[j].next)
    if (sz[edges[j].to]) {

      if (c[edges[j].to] != hd)
        return true;
    }

  return false;
}

inline void dfs(int p) {

  sz[p] = false;

  for (register int j = head[p]; j >= 0; j = edges[j].next)
    if (sz[edges[j].to] && (!check(edges[j].to)))
      dfs(edges[j].to);
}

int main() {

  scanf("%d%d", &n, &m);
  getchar();

  scanf("%s", c + 1);
  int xx, yy;
  memset(head, -1, sizeof(head));

  for (register int i = 1; i <= m; i++) {

    scanf("%d%d", &xx, &yy);

    edges[cnt] = (edge){xx, yy, head[xx]};

    head[xx] = cnt++;

    edges[cnt] = (edge){yy, xx, head[yy]};

    head[yy] = cnt++;
  }

  bool flag;
  memset(sz, 1, sizeof(sz));

  while (true) {

    flag = true;

    for (register int i = 1; i <= n; i++)
      if (sz[i] && (!check(i))) {

        flag = false;
        dfs(i);
      }

    if (flag)
      break;
  }

  for (register int i = 1; i <= n; i++)
    if (sz[i]) {

      printf("Yes\n");
      return 0;
    }

  printf("No\n");

  return 0;
}
