  long long ret = 1;

  while (k) {

    if (k & 1)
      ret = ret * val % mod;

    k >>= 1;
    val = val * val % mod;
  }

  return ret;
}

int n, k;

long long pw[100005], pu[100005], inv[100005];

inline long long C(int n, int m) {
  if (m < 0 || m > n)
    return 0;
  return (pu[n] * inv[m] % mod) * inv[n - m] % mod;
}

long long getans(int val) {

  if (val & 1) {

    long long ans = 0;

    int gro = min(k - val / 2, val / 2);

    int p = k - gro * 2;

    for (int i = (p == 0) ? 1 : 0; i <= gro; i++) {
      ans += (C(n + p - 1, i + p - 1) * pw[i] % mod) * C(gro, i) % mod;
      ans %= mod;
    }

    return ans;

  }

  else {

    long long ans = 0;

    int gro = min(k - val / 2 + 1, val / 2);

    int p = k - gro * 2 + 1;

    for (int i = (p == 0) ? 1 : 0; i < gro; i++) {
      ans += (C(n + p - 1, i + p - 1) * pw[i] % mod) * C(gro - 1, i) % mod;
      ans %= mod;
    }

    for (int i = (p == 0) ? 1 : 0; i < gro; i++) {
      ans += (C(n + p - 2, i + p - 1) * pw[i] % mod) * C(gro - 1, i) % mod;
      ans %= mod;
    }

    return ans;
  }
}

