  if (d > c1.r + c2.r + EPS)
    return 4;

  if (eq(d, c1.r + c2.r))
    return 3;

  if (eq(d, abs(c1.r - c2.r)))
    return 1;

  if (d < abs(c1.r - c2.r) - EPS)
    return 0;

