  for (int i = 0; i < n; i++) {

    if (abs(it[i].x - x) >= d)
      continue;

    for (int j = 0; j < v.size(); j++) {

      DD dy = it[i].y - v[v.size() - 1 - j].y;

      if (dy >= d)
