public:
  SegTree() {}

  SegTree(int n, T unit, T (*func)(T, T), T (*_update)(T, T))
      : N{1}, unit{unit}, func{func}, _update{_update}

  {

    while (N < n)

    {

      N *= 2;
    }

    dat = vector<T>(2 * N - 1, unit);
  }

  void update(int k, T a)

  {

    k += N - 1;

    dat[k] = _update(dat[k], a);

    while (k > 0)

