  {

    for (auto j{i + 1}; j < N; ++j)

    {

      int b{L[i]};

      int c{L[j]};

      ll t{tree.find(abs(b - c) + 1, b + c)};

      if (abs(b - c) < b && b < b + c)

      {

        --t;
      }

      if (abs(b - c) < c && c < b + c)

      {

        --t;
      }

      ans += t;
    }
  }

