        poz++;
      }

      if (poz == length)

      {

        return 1;

        i = n + 1;
      }
    }

    if (i == 0)

    {

      return 0;
    }
  }

  sort(goodSlimes.begin(), goodSlimes.end(), descrescator);

  return 1;
