{

  int q;

  scanf("%d", &q);

  while (q--)

  {

    scanf("%s %s", x + 1, y + 1);

    memset(dp, 0, sizeof(dp));

    int m = strlen(x + 1);

    int n = strlen(y + 1);

    for (int i = 1; i <= m; i++)

      for (int j = 1; j <= n; j++)

      {

        if (x[i] == y[j])

          dp[i][j] = dp[i - 1][j - 1] + 1;

        else

          dp[i][j] = max(dp[i - 1][j], dp[i][j - 1]);
      }

    printf("%d\n", dp[m][n]);
  }

  return 0;
}

