ll power(ll base, ll n)

{

  ll r = 1;

  while (n)

  {

    if (n & 1)
      r = r * base % mod;

    base = base * base % mod;

    n /= 2;
  }

  return r;
}

void init()

{

  fac[0] = 1;

  for (int i = 1; i <= 2e5; i++)

  {

    fac[i] = fac[i - 1] * i % mod;
  }

