  {

    if (q.top() < a[i])

    {

      sum1 -= q.top();

      sum1 += a[i];

      q.pop();

      q.push(a[i]);
    }

    dp1[i] = sum1;
  }

  for (int i = 3 * n; i > 2 * n; i--)

  {

    q2.push(a[i]);

    sum2 += a[i];
