  if (dp[s][v] >= 0)
    return dp[s][v];

  if (s == (1 << n) - 1 && v == 0)
    return dp[s][v] = 0;

  int res = INF;

  for (int u = 0; u < n; u++)

    if (!(s >> u & 1))

      res = min(res, rec(s | 1 << u, u) + d[v][u]);

  return dp[s][v] = res;
}

