  memset(dp, -1, sizeof(dp));

  r(i, MAX) r(j, MAX) d[i][j] = INF;

  int m;

  cin >> n >> m;

  while (m--) {

    int s, t, dd;

    cin >> s >> t >> dd;

    d[s][t] = dd;
  }

  int p = rec(0, 0);

  if (p == INF)
    p = -1;

  cout << p << endl;
}
