  inv[1] = 1;

  for (LL i = 2; i < N; i++)

  {

    fa[i] = fa[i - 1] * i % mod;

    inv[i] = (mod - mod / i) * inv[mod % i] % mod;
  }

  inv[0] = 1;

  for (int i = 1; i < N; i++)

    (inv[i] *= inv[i - 1]) %= mod;
}

LL C(LL n, LL k)

{

  LL ans = 0;

  if (k > n)

    return ans;

  ans = ((fa[n] * inv[k] % mod) * inv[n - k]) % mod;

  return ans;
}

