      T[v] = x;

      return;
    }

    int tm = (tl + tr) / 2;

    if (p <= tm)
      upd(v + v, tl, tm, p, x);

    else
      upd(v + v + 1, tm + 1, tr, p, x);

    T[v] = max(T[v + v], T[v + v + 1]);
