      return -INF;

    if (l == tl && r == tr)
      return T[v];

    int tm = tl + tr >> 1;

    return max(get(v + v, tl, tm, l, min(r, tm)),

               get(v + v + 1, tm + 1, tr, max(tm + 1, l), r));
