  char ch = getchar();

  while (ch < '0' || ch > '9') {
    if (ch == '-')
      f = -f;
    ch = getchar();
  }

  while (ch >= '0' && ch <= '9') {
    ret = ret * 10 + ch - '0';
    ch = getchar();
  }

  return ret * f;
}

struct SegmentTree

{

  int Tree[maxn * 4];

  inline void PushUp(int rt) {
    Tree[rt] = (P[Tree[rt * 2]] < P[Tree[rt * 2 + 1]] ? Tree[rt * 2 + 1]
                                                      : Tree[rt * 2]);
  }

  inline void Build(int L = 1, int R = n, int rt = 1)

  {

    if (L == R) {
      Tree[rt] = L;
      return;
    }

    int M = (L + R) >> 1;

    Build(L, M, rt * 2);

    Build(M + 1, R, rt * 2 + 1);

    PushUp(rt);
  }

  inline void Update(int P, int L = 1, int R = n, int rt = 1)

  {

    if (L == R)
      return;

    int M = (L + R) >> 1;

    if (P <= M)
      Update(P, L, M, rt * 2);

    if (M < P)
      Update(P, M + 1, R, rt * 2 + 1);

    PushUp(rt);
  }

