#define gc()                                                                   \
  (iS == iT ? (iT = (iS = ibuf) + fread(ibuf, 1, SIZE, stdin),                 \
               (iS == iT ? EOF : *iS++))                                       \
            : *iS++)

inline void flush() {

  fwrite(obuf, 1, oS - obuf, stdout);

  oS = obuf;
}

inline void putc(char x) {

  *oS++ = x;

  if (oS == oT)
    flush();
}

template <class I>

inline void gi(I &x) {

  for (f = 1, c = gc(); c < '0' || c > '9'; c = gc())
    if (c == '-')
      f = -1;

  for (x = 0; c <= '9' && c >= '0'; c = gc())
    x = (x << 1) + (x << 3) + (c & 15);
  x *= f;
}

template <class I>

inline void print(I x) {

  if (!x)
    putc('0');
  if (x < 0)
    putc('-'), x = -x;

  while (x)
    qu[++qr] = x % 10 + '0', x /= 10;

  while (qr)
    putc(qu[qr--]);
}

