struct abcd {

  int l, r;

  abcd(int l = -1, int r = -1) : l(l), r(r) {}

  bool operator==(const abcd &B) const { return l == B.l && r == B.r; }

} T[N << 2];

bool Jud(abcd L, abcd R) { return L.r + 1 == R.l; }

inline void Push(int x, abcd u) {

  if (T[x] == abcd(-1, -1)) {
    T[x] = u;
    return;
  }

  if (T[x] == abcd(-2, -2))
    return;

  if (u == abcd(-2, -2)) {
    T[x] = u;
    return;
  }

  if (Jud(T[x], u) || T[x] == abcd(-1, -1))
    T[x].r = u.r;

  else
    T[x] = abcd(-2, -2);
}

inline void Modify(int x, int l, int r, int ql, int qr, abcd u) {

  int mid = (l + r) >> 1;

  if (!(T[x] == abcd(-1, -1)) && l != r)
    Push(x << 1, T[x]), Push(x << 1 | 1, T[x]), T[x] = abcd(-1, -1);

  if (ql <= l && r <= qr) {

    Push(x, u);

    return;
  }

  if (ql <= mid)
    Modify(x << 1, l, mid, ql, qr, u);

  if (mid < qr)
    Modify(x << 1 | 1, mid + 1, r, ql, qr, u);
}

