  vector<long long> S(N);

  for (int i = 0; i < N; ++i) {

    cin >> S[i];
  }

  vector<int> sub(N, 1);

  function<void(int, int)> dfs = [&](int pos, int pre) {
    for (int i : G[pos]) {

      if (i != pre) {

        dfs(i, pos);

        sub[pos] += sub[i];
      }
    }
  };

