    left.push_back(v);

  else
    right.push_back(v);

  for (int i = 0; i < G[v].size(); ++i) {

    if (color[G[v][i]] == c)
      return false;

    if (color[G[v][i]] == 0) {

      if (!bidfs(G, G[v][i], -c, left, right))
        return false;
    }
  }

  return true;
}

bool Isbipartite(Graph &G, vector<int> &left, vector<int> &right) {

  memset(color, 0, sizeof(color));

  left.clear();
  right.clear();

  for (int i = 0; i < G.V; ++i) {

