class UnionFind {

public:
  vector<int> Parent;

  UnionFind(int N) { Parent = vector<int>(N + 1, -1); }

  int root(int A) {

    if (Parent[A] < 0)
      return A;

    return Parent[A] = root(Parent[A]);
  }

  int size(int A) { return -Parent[root(A)]; }

  bool connect(int A, int B) {

    A = root(A);

    B = root(B);

    if (A == B) {

      return false;
    }

    if (size(A) < size(B))
      swap(A, B);

    Parent[A] += Parent[B];

    Parent[B] = A;

    return true;
  }
};

int main(void) {

  int N, M;

  cin >> N >> M;

  vector<int> A(M), B(M);

  for (int i = 0; i < M; i++) {

    cin >> A[i] >> B[i];
  }

  vector<long long int> ans(M);

  ans[M - 1] = (long long int)N * (N - 1) / 2;

  UnionFind Uni(N);

  for (int i = M - 1; i >= 1; i--) {

    ans[i - 1] = ans[i];

    if (Uni.root(A[i]) != Uni.root(B[i])) {

      ans[i - 1] -= (long long int)Uni.size(A[i]) * Uni.size(B[i]);

      Uni.connect(A[i], B[i]);
    }
  }

  for (int i = 0; i < M; i++)
