  edges[cnt].to = to;

  edges[cnt].weight = weight;

  edges[cnt].next = head[from];

  head[from] = cnt++;
}

bool dfs(int u) {

  for (int i = head[u]; i != -1; i = edges[i].next) {

    int v = edges[i].to;

    if (!check[v]) {

      check[v] = true;

      if (matchingy[v] == -1 || dfs(matchingy[v])) {

        matchingy[v] = u;

        matchingx[u] = v;

        return true;
      }
    }
  }

  return false;
}

