  for (int i = 1; i < n; i++) {

    int u, v;
    scanf("%d%d", &u, &v);

    adj[u].pb(v);

    adj[v].pb(u);
  }

  memset(memo, -1, sizeof memo);

  printf("%lld\n", add(dp(1, 0, 1), dp(1, 1, 1)));
}

