    for (int j = 0; j < w; j++) {

      if (s[j] == '#') {

        a[i][j + 1] = 1;

        Q.push((Node){i, j + 1});

        vis[i][j + 1] = 1;

      } else
        a[i][j + 1] = 0;
    }
  }

  int cnt = 0;

  while (!Q.empty()) {

    Node p = Q.front();

    Q.pop();

    if (p.x > 1 && !vis[p.x - 1][p.y]) {

      d[p.x - 1][p.y] = d[p.x][p.y] + 1;

      Q.push((Node){p.x - 1, p.y});

      vis[p.x - 1][p.y] = 1;
    }

    if (p.y > 1 && !vis[p.x][p.y - 1]) {

      d[p.x][p.y - 1] = d[p.x][p.y] + 1;

      Q.push((Node){p.x, p.y - 1});

      vis[p.x][p.y - 1] = 1;
    }

    if (p.x < h && !vis[p.x + 1][p.y]) {

      d[p.x + 1][p.y] = d[p.x][p.y] + 1;

      Q.push((Node){p.x + 1, p.y});

      vis[p.x + 1][p.y] = 1;
