      d[p.x][p.y + 1] = d[p.x][p.y] + 1;

      Q.push((Node){p.x, p.y + 1});

      vis[p.x][p.y + 1] = 1;
    }
  }

  int ans = 0;

  for (int i = 1; i <= h; i++)

    for (int j = 1; j <= w; j++)
      ans = max(ans, d[i][j]);

  cout << ans;
}
