#define REP(i, stop) FOR(i, 0, stop)

#define FOR(i, start, stop)                                                    \
  for (int i = start, i##_len = stop; i < i##_len; ++i)

#define RREP(i, n) for (int i = n; i-- > 0;)

const i32 M = 998244353;

i32 dp[90310];

i32 dq[90310];

signed main() {

  i32 n;

  scanf("%d", &n);

  i32 sum = 0;

  i32 ans = 1;

  dp[0] = 1;

  dq[0] = 1;

  REP(i, n) {

    i32 a;

    scanf("%d", &a);

    RREP(t, sum + 1) {

      (dp[t + a] += dp[t]) %= M;

      (dp[t] *= 2) %= M;

      (dq[t + a] += dq[t]) %= M;
    }

    sum += a;

    ans = (ans * 3) % M;
  }

  i32 lim = (sum - 1) / 2;

  FOR(t, lim + 1, sum + 1) { ans = (ans - dp[t] * 3) % M; }

  if (sum % 2 == 0) {

    ans = (ans + dq[sum / 2] * 3) % M;
  }

  ans = (ans + M) % M;

  printf("%d\n", ans);
}
