    num[i].a = x;

    num[i].b = i;
  }

  sort(num, num + n, compare);

  int max = 0;

  for (int i = 1; i < n; i++)

  {

    if (num[i].b > num[i - 1].b)

      dp[i] = dp[i - 1] + 1;

    if (dp[i] > max)

      max = dp[i];
  }

  cout << n - max << endl;

