struct unionfind {

  vector<ll> par;

  vector<ll> siz;

  vector<ll> es;

  ll n, trees;

  unionfind(ll n) : n(n), trees(n) {
    par.resize(n);
    siz.resize(n);
    es.resize(n);
    for (ll i = 0; i < n; i++) {
      par[i] = i;
      siz[i] = 1;
    }
  }

  ll root(ll x) {
    if (par[x] == x) {
      return x;
    } else {
      return par[x] = root(par[x]);
    }
  }

  bool unite(ll x, ll y) {

    x = root(x);

    y = root(y);

    es[x]++;

    if (x == y)
      return false;

    if (siz[x] > siz[y])
      swap(x, y);

    trees--;

    par[x] = y;

    siz[y] += siz[x];

    es[y] += es[x];

    return true;
  }

  bool same(ll x, ll y) { return root(x) == root(y); }

  ll size(ll x) { return siz[root(x)]; }

  ll esize(ll x) { return es[root(x)]; }

  vi sizes() {
    vi cou(n);
    vi ret;
    ret.reserve(n);
    rep(i, n) { cou[root(i)]++; }
    rep(i, n) {
      if (cou[i])
        ret.push_back(cou[i]);
    }
    return ret;
  }

  bool close(ll x) { return esize(x) >= size(x); }

  vec<vi> sets() {
    vi ind(n, -1);
    ll i = 0;
    vvi(res, trees);
    rep(j, n) {
      ll r = root(j);
      if (ind[r] == -1)
        ind[r] = i++;
      res[ind[r]].push_back(j);
    }
    rep(i, trees) {
      ll r = root(res[i][0]);
      if (res[i][0] == r)
        continue;
      rep(j, 1, sz(res[i])) {
        if (res[i][j] == r) {
          swap(res[i][0], res[i][j]);
          break;
        }
      }
    }
    return res;
  }
};

