constexpr bool bget(ll m, ll keta) { return (m >> keta) & 1; }

ll bget(ll m, ll keta, ll sinsuu) {
  m /= (ll)pow(sinsuu, keta);
  return m % sinsuu;
}

ll bit(ll n) { return (1LL << (n)); }

ll bit(ll n, ll sinsuu) { return (ll)pow(sinsuu, n); }

