#define bcou __builtin_popcountll

ll lbit(ll n) { return n & -n; }

ll hbit(ll n) {
  n |= (n >> 1);
  n |= (n >> 2);
  n |= (n >> 4);
  n |= (n >> 8);
  n |= (n >> 16);
  n |= (n >> 32);
  return n - (n >> 1);
}

ll hbitk(ll n) {
  ll k = 0;
  rer(i, 5) {
    ll a = k + (1ll << i);
    ll b = 1ll << a;
    if (b <= n)
      k += 1ll << i;
  }
  return k;
}

ll nextComb(ll &mask, ll n, ll r) {
  if (!mask)
    return mask = (1LL << r) - 1;
  ll x = mask & -mask;
  ll y = mask + x;
  ll res = ((mask & ~y) / x >> 1) | y;
  if (bget(res, n))
    return mask = 0;
  else
    return mask = res;
}

vi bitCombList(ll n, ll r) {
  vi res;
  ll m = 0;
  while (nextComb(m, n, r)) {
    res.push_back(m);
  }
  return res;
}

