    this->resize(n);
    rep(i, m) {
      int f, t, c, ty;
      cin >> f >> t >> c >> ty;
      f -= minus;
      t -= minus;
      ty -= minus;
      add(f, t, c, ty);
    }
  }

  void ingtc(int n, int m, int minus = 1) {
    this->resize(n);
    rep(i, m) {
      int f, t, c, ty;
      cin >> f >> t >> ty >> c;
      f -= minus;
      t -= minus;
      ty -= minus;
      add(f, t, c, ty);
    }
  }
  bool used(edge<T> &e) { return usedv[e.id]; }

  bool used(int id) { return usedv[id]; }

  void del(edge<T> &e) { usedv[e.id] = 1; }

  void del(int id) { usedv[id] = 1; }

  void set_edges() {
    if (sz(edges))
      return;
    rep(i, n) fora(e, g[i]) edges.push_back(e);
  }
};

template <typename T> struct radixheap {
  vector<pair<u64, T>> v[65];
  u64 size, last;
  radixheap() : size(0), last(0) {}
  bool empty() const { return size == 0; }
  int getbit(int a) { return a ? 64 - __builtin_clzll(a) : 0; }
  void push(u64 key, const T &value) {
    ++size;
    v[getbit(key ^ last)].emplace_back(key, value);
  }
  pair<u64, T> pop() {
    if (v[0].empty()) {
      int idx = 1;
      while (v[idx].empty())
        ++idx;
      last = min_element(begin(v[idx]), end(v[idx]))->first;
      for (auto &p : v[idx])
        v[getbit(p.first ^ last)].emplace_back(p);
      v[idx].clear();
    }
    --size;
    auto ret = v[0].back();
    v[0].pop_back();
    return ret;
  }
};

vi dijkstra2(const graph<int> &g, int s, int init_value = -1) {
  if (!(0 <= s && s < g.n)) {
    debugline("dijkstra");
    deb(s, g.n);
    ole();
  }
  int initValue = MAX(int);
  vi dis(g.n, initValue);
  radixheap<int> q;
  dis[s] = 0;
  q.push(0, s);
  while (!q.empty()) {
    int nowc, i;
    tie(nowc, i) = q.pop();
    if (dis[i] != nowc)
      continue;
    for (auto &&e : g.g[i]) {
      int to = e.t;
      int c = nowc + e.c;
      if (dis[to] > c) {
        dis[to] = c;
        q.push(dis[to], to);
      }
    }
  }
  for (auto &&d : dis)
    if (d == initValue)
      d = init_value;
  return dis;
}

template <class T>
vector<T> dijkstra(const graph<T> &g, int s, int init_value = -1) {
  if (!(0 <= s && s < g.n)) {
    debugline("dijkstra");
    deb(s, g.n);
    ole();
  }
  T initValue = MAX(T);
  vector<T> dis(g.n, initValue);
  priority_queue<pair<T, int>, vector<pair<T, int>>, greater<pair<T, int>>> q;
  dis[s] = 0;
  q.emplace(0, s);
  while (q.size()) {
    T nowc = q.top().fi;
    int i = q.top().se;
    q.pop();
    if (dis[i] != nowc)
      continue;
    for (auto &&e : g.g[i]) {
      int to = e.t;
      T c = nowc + e.c;
      if (dis[to] > c) {
        dis[to] = c;
        q.emplace(dis[to], to);
      }
    }
  }
  for (auto &&d : dis)
    if (d == initValue)
      d = init_value;
  return dis;
}

template <class T>
vector<vector<T>> dijkstra_all(const graph<T> &g, int init_value = -1) {
  vector<vector<T>> dis(g.n);
  rep(i, g.n) { dis[i] = dijkstra(g, i, init_value); }
