void replace(str &a) {
  int dec = 0;
  if ('a' <= a[0] && a[0] <= 'z')
    dec = 'a';
  if ('A' <= a[0] && a[0] <= 'Z')
    dec = 'A';
  fora(v, a) { v -= dec; }
}

void replace(str &a, str key, str v) {
  stringstream t;
  ll kn = sz(key);
  std::string::size_type Pos(a.find(key));
  ll l = 0;
  while (Pos != std::string::npos) {
    t << a.substr(l, Pos - l);
    t << v;
    l = Pos + kn;
    Pos = a.find(key, Pos + kn);
  }
  t << a.substr(l, sz(a) - l);
  a = t.str();
}

