  if ((int)(A).size() == 1)
    return true;
  if ((int)(A).size() == 2)
    return A[0] != A[1];
  if ((int)(A).size() == 3)
    return (A[0] != A[1] && A[1] != A[2] && A[0] != A[2]);
  auto B = A;
  sort(B);
  int N = (B.size());
  unique(B);
  return N == (int)(B.size());
}

