  auto lim = milliseconds(time - 20);
  ll mini = 0, minv = MAX<ll>();
  rep(k, 1, inf) {
    auto s = system_clock::now();
    ll haba = (r - l + k) / k;
    ll nl = l;
    ll nr = l + haba;
    rep(i, k) {
