  P null_p = mp(linf, linf);
  if (b == 0) {
    if (a >= 0) {
      return mp(-linf, linf + 1);
    } else {
      return null_p;
    }
  } else {
    if (a >= 0) {
      if (b > 0) {
        return mp(-linf, a / b + 1);
      } else {
        return mp(-(a / -b), linf + 1);
      }
    } else {
      if (b > 0) {
