  int f = ve[gi].f, t = ve[gi].t, c = ve[gi].c;                                \
  if (t == p)                                                                  \
    continue;                                                                  \
  ci++;

#define fore(gi, ve)                                                           \
  for (ll gi = 0, forglim = ve.size(), f, t, c;                                \
       gi < forglim && (f = ve[gi].f, t = ve[gi].t, c = ve[gi].c, true); ++gi)

