template <class T, class U, class I>
vector<T> dijkstra_mitu(graph<T> &g, const U &S_, I init_value) {
  vi S = to_vi(S_);
  int n = g.n;
  T initValue = MAX<T>();
  vector<T> dis(n, initValue);
  fora(s, S) {
    if (!(0 <= s && s < g.n)) {
      debugline("dijkstra_mitu");
      deb(s, g.n);
      ole();
    }
    dis[s] = 0;
  }
  vb used(n);
  while (true) {
    int v = -1;
    rep(u, n) {
      if (!used[u] && (v == -1 || dis[u] < dis[v]))
        v = u;
    }
    if (v == -1)
      break;
    if (dis[v] == initValue)
      break;
    used[v] = true;
    rep(u, sz(g[v])) {
      auto e = g[v][u];
      dis[e.t] = min(dis[e.t], dis[v] + e.c);
    }
  }
  for (auto &&d : dis) {
    if (d == initValue) {
      d = init_value;
    }
  }
  return dis;
}

template <class T, class U, class I>
vector<T> dijkstra_01(graph<T> &g, const U &S_, I init_value) {
  int N = g.n;
  vi S = to_vi(S_);
  T tinf = INF<T>();
  vector<T> dis(N, tinf);
  deque<int> q;
  fora(s, S) {
    dis[s] = 0;
    q.push_back(s);
  }
  vb was(N);
  while (!q.empty()) {
    int f = q.front();
    q.pop_front();
    if (was[f])
      continue;
    was[f] = true;
    fora(e, g[f]) {
      if (dis[e.t] > dis[f] + e.c) {
        if (e.c) {
          dis[e.t] = dis[f] + 1;
          q.push_back(e.t);
        } else {
          dis[e.t] = dis[f];
          q.push_front(e.t);
        }
      }
    }
  }
  rep(i, N) if (dis[i] == tinf) dis[i] = init_value;
  return dis;
}

template <typename T> struct radixheap {
  vector<pair<u64, T>> v[65];
  u64 size_, last;
  radixheap() : size_(0), last(0) {}
  bool empty() const { return size_ == 0; }
  int getbit(int a) { return a ? 64 - __builtin_clzll(a) : 0; }
  void emplace(u64 key, const T &value) {
    ++size_;
    v[getbit(key ^ last)].emplace_back(key, value);
  }
  void push(u64 key, const T &value) { emplace(key, value); }
  pair<u64, T> top() {
    if (v[0].empty()) {
      int idx = 1;
      while (v[idx].empty())
        ++idx;
      last = min_element(begin(v[idx]), end(v[idx]))->first;
      for (auto &p : v[idx])
        v[getbit(p.first ^ last)].emplace_back(p);
      v[idx].clear();
    }
    --size_;
    auto ret = v[0].back();
    v[0].pop_back();
    return ret;
  }
  void pop() { ; }
  int size() { return size_; }
};

template <class Q, class T, class U, class I>
vector<T> private_dijkstra(graph<T> &g, U &S_, I init_value) {
  vi S = to_vi(S_);
  fora(s, S) {
    if (!(0 <= s && s < g.n)) {
      debugline("dijkstra");
      deb(s, g.n);
      ole();
    }
  }
  bool cost01 = true;
  rep(i, g.n) {
    forg(gi, g[i]) {
      forg_init(g[i]);
      cost01 &= (c == 0 || c == 1);
    }
  }
  if (cost01)
    return dijkstra_01(g, S_, init_value);
  else if ((g.n + sz(g.edges)) * log2(g.n) > g.n * g.n) {
    return dijkstra_mitu(g, S, init_value);
  }
  T initValue = MAX<T>();
  vector<T> dis(g.n, initValue);
  Q q;
  fora(s, S) {
    dis[s] = 0;
    q.emplace(0, s);
  }
  while (q.size()) {
    T nowc;
    int i;
    tie(nowc, i) = q.top();
    q.pop();
    if (dis[i] != nowc)
      continue;
    for (auto &&e : g.g[i]) {
      int to = e.t;
      T c = nowc + e.c;
      if (dis[to] > c) {
        dis[to] = c;
        q.emplace(dis[to], to);
      }
    }
  }
  for (auto &&d : dis)
    if (d == initValue)
      d = init_value;
  return dis;
}

template <class T, class U, class I>
vector<T> dijkstra(graph<T> &g, U S_, I init_value) {
  if (typeid(T) == typeid(int)) {
    return private_dijkstra<radixheap<int>>(g, S_, init_value);
  } else {
    return private_dijkstra<priority_queue<pair<T, int>, vector<pair<T, int>>,
                                           greater<pair<T, int>>>>(g, S_,
                                                                   init_value);
  }
}

template <class COU, class T = int, class I>
auto dijkstra_cou(const graph<T> &g, int s, I init_value) {
  if (!(0 <= s && s < g.n)) {
    debugline("dijkstra");
    deb(s, g.n);
    ole();
  }
  err("count by type COU ");
  err("int or mint");
  T initValue = MAX<T>();
  vector<T> dis(g.n, initValue);
  vector<COU> cou(g.n);
  cou[s] = 1;
  priority_queue<pair<T, int>, vector<pair<T, int>>, greater<pair<T, int>>> q;
  dis[s] = 0;
  q.emplace(0, s);
  while (q.size()) {
    T nowc = q.top().fi;
    int i = q.top().se;
    q.pop();
    if (dis[i] != nowc)
      continue;
    for (auto &&e : g.g[i]) {
      int to = e.t;
      T c = nowc + e.c;
      if (dis[to] > c) {
        dis[to] = c;
        cou[to] = cou[e.f];
        q.emplace(dis[to], to);
      } else if (dis[to] == c) {
        cou[to] += cou[e.f];
      }
    }
  }
  for (auto &&d : dis)
    if (d == initValue)
      d = init_value;
  return vtop(dis, cou);
}

template <class T> vector<T> bell(graph<T> &g, int s) {
  if (g.n >= 1e4) {
    cout << "bell size too big" << endl;
    exit(0);
  }
  vector<T> res(g.n, linf);
  res[s] = 0;
  vb can(g.n);
  fix([&](auto ds, int p, int i) -> void {
    if (can[i])
      return;
    can[i] = true;
    forg(gi, g[i]) {
      forg_init(g[i]);
      if (t != p)
        ds(i, t);
    }
  })(-1, 0);
  vector<edge_<T>> es;
  fora(e, g.edges) {
    if (can[e.f])
      es += e;
  }
  rep(i, g.n) {
    bool upd = false;
    fora(e, es) {
      if (res[e.f] != linf && res[e.t] > res[e.f] + e.c) {
        upd = true;
        res[e.t] = res[e.f] + e.c;
      }
    }
    if (!upd)
      break;
  }
  rep(i, g.n * 2) {
    bool upd = 0;
    fora(e, g.edges) {
      if (res[e.f] != linf && res[e.t] != -linf && res[e.t] > res[e.f] + e.c) {
        upd = 1;
        res[e.t] = -linf;
      }
    }
    if (!upd)
      break;
  }
  return res;
}

template <class T> vector<T> bell_far(graph<T> &g, int s) {
  if (g.n >= 1e4) {
    cout << "bell_far size too big" << endl;
    exit(0);
  }
  vector<T> res(g.n, linf);
  res[s] = 0;
  vb can(g.n);
  fix([&](auto ds, int p, int i) -> void {
    if (can[i])
      return;
    can[i] = true;
    forg(gi, g[i]) {
      forg_init(g[i]);
      if (t != p)
        ds(i, t);
    }
  })(-1, 0);
  vector<edge_<T>> es;
  fora(e, g.edges) {
    if (can[e.f])
      es += e;
  }
  rep(i, g.n) {
    bool upd = false;
    fora(e, es) {
      if (res[e.f] != linf && res[e.t] > res[e.f] - e.c) {
        upd = true;
        res[e.t] = res[e.f] - e.c;
      }
    }
    if (!upd)
      break;
  }
  rep(i, g.n * 2) {
    bool upd = 0;
    fora(e, g.edges) {
      if (res[e.f] != linf && res[e.t] != -linf && res[e.t] > res[e.f] - e.c) {
        upd = 1;
        res[e.t] = -linf;
      }
    }
    if (!upd)
      break;
  }
  rep(i, g.n) res[i] *= -1;
  return res;
}

template <class T, class I>
vector<vector<T>> warshall(graph<T> &g, I init_value) {
  int n = g.n;
  assert(n < 1e4);
  vector<vector<T>> dis(n, vector<T>(n, INF<T>()));
  rep(i, n) fora(e, g.g[i]) {
    if (dis[e.f][e.t] > e.c) {
      dis[e.f][e.t] = e.c;
    }
  }
  rep(i, n) dis[i][i] = 0;
  rep(k, n) rep(i, n) rep(j, n) {
    if (dis[i][j] > dis[i][k] + dis[k][j]) {
      dis[i][j] = dis[i][k] + dis[k][j];
    }
  }
  rep(i, n) rep(j, n) if (dis[i][j] == linf) dis[i][j] = init_value;
  return dis;
}

template <class T, class I>
vector<vector<T>> dijkstra_all(graph<T> &g, I init_value) {
  int n = g.n;
  assert(n < 1e4);
  if (n * n < (n + sz(g.edges)) * 14) {
    return warshall(g, init_value);
  }
  vector<vector<T>> dis(n);
  rep(i, n) { dis[i] = dijkstra(g, i, init_value); }
  return dis;
}

template <class T> class MinOp {
public:
  T operator()(T a, T b) { return min(a, b); }
};

template <typename OpFunc> struct SparseTable {
  OpFunc op;
  signed size;
  vector<signed> lg;
  vector<vector<pair<signed, signed>>> table;
  void init(vector<pair<signed, signed>> &array, OpFunc opfunc) {
    signed n = array.size();
    op = opfunc;
    lg.assign(n + 1, 0);
    for (signed i = 1; i <= n; i++) {
      lg[i] = 31 - __builtin_clz(i);
    }
    table.assign(lg[n] + 1, array);
    for (signed i = 1; i <= lg[n]; i++) {
      for (signed j = 0; j < n; j++) {
        if (j + (1 << (i - 1)) < n) {
          table[i][j] = op(table[i - 1][j], table[i - 1][j + (1 << (i - 1))]);
        } else {
          table[i][j] = table[i - 1][j];
        }
      }
    }
  }
  pair<signed, signed> query(signed l, signed r) {
    assert(l < r);
    return op(table[lg[r - l]][l], table[lg[r - l]][r - (1 << lg[r - l])]);
  }
};

struct PMORMQ {
  vector<signed> a;
  SparseTable<MinOp<pair<signed, signed>>> sparse_table;
  vector<vector<vector<signed>>> lookup_table;
  vector<signed> block_type;
  signed block_size, n_block;
  void init(vector<signed> &array) {
    a = array;
    signed n = a.size();
    block_size = std::max(1, (31 - __builtin_clz(n)) / 2);
    while (n % block_size != 0) {
      a.push_back(a.back() + 1);
      n++;
    }
    n_block = n / block_size;
    vector<pair<signed, signed>> b(n_block, make_pair(INT_MAX, INT_MAX));
    for (signed i = 0; i < n; i++) {
      b[i / block_size] = min(b[i / block_size], make_pair(a[i], i));
    }
    sparse_table.init(b, MinOp<pair<signed, signed>>());
    block_type.assign(n_block, 0);
    for (signed i = 0; i < n_block; i++) {
      signed cur = 0;
      for (signed j = 0; j < block_size - 1; j++) {
        signed ind = i * block_size + j;
        if (a[ind] < a[ind + 1]) {
          cur |= 1 << j;
        }
      }
      block_type[i] = cur;
    }
    lookup_table.assign(
        1 << (block_size - 1),
        vector<vector<signed>>(block_size, vector<signed>(block_size + 1)));
    for (signed i = 0; i < (1 << (block_size - 1)); i++) {
      for (signed j = 0; j < block_size; j++) {
        signed res = 0;
        signed cur = 0;
        signed pos = j;
        for (signed k = j + 1; k <= block_size; k++) {
          lookup_table[i][j][k] = pos;
          if (i & (1 << (k - 1))) {
            cur++;
          } else {
            cur--;
          }
          if (res > cur) {
            pos = k;
            res = cur;
          }
        }
      }
    }
  }
  signed query(signed l, signed r) {
    assert(l < r);
    signed lb = l / block_size;
    signed rb = r / block_size;
    if (lb == rb) {
      return lb * block_size +
             lookup_table[block_type[lb]][l % block_size][r % block_size];
    }
    signed pl = lb * block_size +
                lookup_table[block_type[lb]][l % block_size][block_size];
    signed pr =
        rb * block_size + lookup_table[block_type[rb]][0][r % block_size];
    signed pos = pl;
    if (r % block_size > 0 && a[pl] > a[pr]) {
      pos = pr;
    }
    if (lb + 1 == rb) {
      return pos;
    }
    signed spv = sparse_table.query(lb + 1, rb).second;
    if (a[pos] > a[spv]) {
      return spv;
    }
    return pos;
  }
};

template <class T = int> class tree : public undigraph<T> {

  PMORMQ rmq;
  int cnt;
  vector<signed> id_, in;
  bool never = true;
  bool never_hld = true;

  void dfs(int x, int p, int d, int dis = 0) {
    id_[cnt] = x;
    par_[x] = p;
    rmq_dep.push_back(d);
    disv[x] = dis;
    in[x] = cnt++;
    forg(gi, g[x]) {
      forg_init(g[x]);
      if (t == p) {
        continue;
      }
      dfs(t, x, d + 1, dis + c);
      id_[cnt] = x;
      rmq_dep.push_back(d);
      cnt++;
    }
  }
  void precalc() {
    never = false;
    cnt = 0;
    rmq_dep.clear();
    disv.assign(n, 0);
    in.assign(n, -1);
    id_.assign(2 * n - 1, -1);
    par_.assign(n, -1);
    dfs(root, -1, 0);
    rmq.init(rmq_dep);

#ifdef _DEBUG

    if (n >= 100)
      return;
    cerr << "---tree---" << endl;
    rep(i, n) {
      if (!(i == root || sz(g[i]) > 1))
        continue;
      cerr << i << " -> ";
      vi ts;
      forg(gi, g[i]) {
        forg_init(g[i]);
        if (t != par_[i])
          ts.push_back(t);
      }
      rep(i, sz(ts) - 1) cerr << ts[i] << ", ";
      if (sz(ts))
        cerr << ts.back() << endl;
    }
    cerr << endl;

#endif
  }
  int pos;
  void hld_build() {
    never_hld = false;
    if (never)
      precalc();
    g.resize(n);
    vid.resize(n, -1);
    head.resize(n);
    heavy.resize(n, -1);
    depth.resize(n);
    inv.resize(n);
    subl.resize(n);
    subr.resize(n);
    dfs(root, -1);
    t = 0;
    dfs_hld(root);

#ifdef _DEBUG

    if (n >= 100)
      return;
    cerr << "---hld_index---" << endl;
    vi inds;
    rep(i, n) if (sz(g[i])) inds.push_back(i);
    rep(i, sz(inds)) {
      str s = tos(bel(inds[i]));
      cerr << std::right << std::setw(sz(s) + (i ? 1 : 0)) << inds[i];
    }
    cerr << endl;
    rep(i, sz(inds)) { cerr << bel(inds[i]) << " "; }
    cerr << endl << endl;
    cerr << "---hld_edge_index---" << endl;
    fora(e, edges) {
      if (e.f <= e.t)
        cerr << e.f << "-" << e.t << " " << bel(e) << endl;
    }
    cerr << endl << endl;
    cerr << "!!query!! edge or not edge carefull!!" << endl;

#endif
  }
  int dfs(int curr, int prev) {
    int sub = 1, max_sub = 0;
    heavy[curr] = -1;

    forg(gi, g[curr]) {
      forg_init(g[curr]);
      int next = t;
      if (next != prev) {
        depth[next] = depth[curr] + 1;
        int sub_next = dfs(next, curr);
        sub += sub_next;
        if (max_sub < sub_next)
          max_sub = sub_next, heavy[curr] = next;
      }
    }
    return sub;
  }
  int t = 0;

#ifndef __CLION_IDE__

  void dfs_hld(int v = 0) {
    vid[v] = subl[v] = t;
    t++;
    inv[subl[v]] = v;
    if (0 <= heavy[v]) {
      head[heavy[v]] = head[v];
      dfs_hld(heavy[v]);
    }

    forg(gi, g[v]) {
      forg_init(g[v]);
      if (depth[v] < depth[t])
        if (t != heavy[v]) {
          head[t] = t;
          dfs_hld(t);
        }
      subr[v] = t;
    }
  }

#endif

  vector<signed> rmq_dep;

  vi par_, depth, disv;

  vi childs;

  vi par_id_;

  vvi(ids_);

public:
  using undigraph<T>::g;
  using undigraph<T>::n;
  using undigraph<T>::edges;

  int root;

  vector<int> vid, head, heavy, inv, subl, subr;

  tree(int n_, int root = 0) : undigraph<T>(n_), root(root) { n = n_; }

  tree(int n_, int root, const vector<edge_<T>> &E)
      : undigraph<T>(n_), root(root) {
    n = n_;
    fora(e, E) { add(e.f, e.t, e.c); }
  }

  void add(int f, int t, T c = 1) {

#ifdef _DEBUG

    if ((n % k5) == 0) {
      re("tree must resize");
    }

#endif

    if (!(0 <= f && f < n && 0 <= t && t < n)) {
      debugline("tree add");
      deb(f, t, c);
      ole();
    }

    g[f].emplace_back(f, t, c);

    g[t].emplace_back(t, f, c);

    edges.emplace_back(f, t, c);

    edges.emplace_back(t, f, c);
  }

  void add_di(int f, int t, T c = 1) {

#ifdef _DEBUG

    if ((n % k5) == 0) {
      re("tree must resize");
    }

#endif

    if (!(0 <= f && f < n && 0 <= t && t < n)) {
      debugline("tree add");
      deb(f, t, c);
      ole();
    }
    g[f].emplace_back(f, t, c);
    edges.emplace_back(f, t, c);
  }

  void root_change(int roo) {
    root = roo;
    precalc();
  }

  void root_change_mid() {

#ifdef _DEBUG

    message += "N>2 (mid)\n";

#endif

    assert(n > 2);
    rep(i, n) {
      if (sz(g[i]) > 1) {
        root_change(i);
        return;
      }
    }
  }

  int lca(int a, int b) {
    if (never)
      precalc();
    int x = in[a];
    int y = in[b];
    if (x > y) {
      swap(x, y);
    }
    int pos = rmq.query(x, y + 1);
    return id_[pos];
  }

  int dis(int a, int b) {
    if (never)
      precalc();
    int x = in[a];
    int y = in[b];
    if (x > y) {
      swap(x, y);
    }
    int pos = rmq.query(x, y + 1);
    int p = id_[pos];
    return disv[a] + disv[b] - disv[p] * 2;
  }

  int dep(int a) {
    if (never)
      precalc();
    return disv[a];
  }

  int par(int a) {
    if (never)
      precalc();
    return par_[a];
  }

  bool isleaf(int i) {
    if (never)
      precalc();
    return (sz(g[i]) == 1 && i != root);
  }

  bool leaf(int i) { return isleaf(i); }

  vi child(int r) {
    vi res;
    res.push_back(r);
    queue<int> q;
    q.push(r);
    while (!q.empty()) {
      int i = q.front();
      res.push_back(i);
      q.pop();
      forg(gi, g[i]) {
        forg_init(g[i]);
        if (t != par(i))
          q.push(t);
      }
    }
    return res;
  }

  vb child_ex(int r) {
    vb res(n);
    res[r] = true;
    queue<int> q;
    q.push(r);
    while (!q.empty()) {
      int i = q.front();
      res[i] = true;
      q.pop();
      forg(gi, g[i]) {
        forg_init(g[i]);
        if (t != par(i))
          q.push(t);
      }
    }
    return res;
  }

  int dfs_count_subtree(int p, int i) {
    childs[i] = 1;
    fort(ci, g[i]) {
      fort_init(gi, g[i]);
      childs[i] += dfs_count_subtree(i, t);
    }
    return childs[i];
  }

#define count_child count_subtree

  int count_subtree(int f) {
    if (sz(childs) == 0) {
      if (never)
        precalc();
      childs.resize(n);
      dfs_count_subtree(-1, root);
    }
    return childs[f];
  }

  int count_subtree(int f, int t) {
    if (par(f) == t) {
      return n - count_subtree(f);
    } else {
      return count_subtree(t);
    }
  }

  int size(int f, int t) { return count_subtree(f, t); }

  int size() { return n; }

  vi path(int a, int b) {
    vi res;
    for_each_l(a, b, [&](int i) { res.push_back(i); });
    return res;
  }

  vi pathe(int a, int b) {

#ifdef _DEBUG

    static bool was = 0;
    if (!was)
      message += "can't edges[id]. must edge(id)\n";
    was = 1;

#endif

    if (sz(par_id_) == 0) {
      ids_.resize(n);
      par_id_.resize(n);
      rep(i, 0, sz(edges), 2) {
        ids_[edges[i].f].emplace_back(i >> 1);
        ids_[edges[i].t].emplace_back(i >> 1);
      }
      if (never)
        precalc();
      rep(i, n) {
        int pa = par_[i];
        forg(gi, g[i]) {
          forg_init(g[i]);
          if (t == pa) {
            par_id_[i] = ids_[i][gi];
          }
        }
      }
    }
    int u = lca(a, b);
    vi res;
    if (a != u) {
      do {
        res.emplace_back(par_id_[a]);
        a = par_[a];
      } while (a != u);
    }
    vi rev;
    if (b != u) {
      do {
        rev.emplace_back(par_id_[b]);
        b = par_[b];
      } while (b != u);
    }
    rer(i, sz(rev) - 1) { res.emplace_back(rev[i]); }
    return res;
  }

  int par_id(int i) {
    if (sz(par_id_) == 0) {
      pathe(0, 0);
    }
    return par_id_[i];
  }

  int ids(int f, int i) {
    if (sz(ids_) == 0) {
      pathe(0, 0);
    }
    return ids_[f][i];
  }

  edge_<T> edge(int id) { return edges[id << 1]; }

  void for_each_l(int u, int v, function<void(int)> fnode) {
    int r = lca(u, v);
    while (u != r) {
      fnode(u);
      u = par_[u];
    }
    fnode(r);
    vi a;
    while (v != r) {
      a.push_back(v);
      v = par_[v];
    }
    while (sz(a)) {
      fnode(a.back());
      a.pop_back();
    }
  }

  void for_each_edge_l(int u, int v, function<void(edge_<int> &)> fedge) {
    int r = lca(u, v);
    while (u != r) {
      forg(gi, g[u]) {
        forg_init(g[u]);
        if (t == par_[u]) {
          fedge(g[u][gi]);
          u = par_[u];
          break;
        }
      }
    }
    vector<edge_<int>> qs;
    while (v != r) {
      forg(gi, g[v]) {
        forg_init(g[v]);
        if (t == par_[v]) {
          qs.push_back(g[v][gi]);
          v = par_[v];
          break;
        }
      }
    }
    while (sz(qs)) {
      fedge(qs.back());
      qs.pop_back();
    }
  }

  void for_each_(int u, int v, const function<void(int, int)> &f) {
    if (never_hld)
      hld_build();
    while (1) {
      if (vid[u] > vid[v])
        swap(u, v);
      int l = max(vid[head[v]], vid[u]);
      int r = vid[v] + 1;
      f(l, r);
      if (head[u] != head[v])
        v = par_[head[v]];
      else
        break;
    }
  }

  void for_each_edge(int u, int v, const function<void(int, int)> &f) {
    if (never_hld)
      hld_build();
    while (1) {
      if (vid[u] > vid[v])
        swap(u, v);
      if (head[u] != head[v]) {
        int l = vid[head[v]];
        int r = vid[v] + 1;
        f(l, r);
        v = par_[head[v]];
      } else {
        if (u != v) {
          int l = vid[u] + 1;
          int r = vid[v] + 1;
          f(l, r);
        }
        break;
      }
    }
  }

  int bel(int v) {
    if (never_hld)
      hld_build();
    return vid[v];
  }

  int bel(int f, int t) {
    if (never_hld)
      hld_build();
    return depth[f] > depth[t] ? vid[f] : vid[t];
  }

  int bel(edge_<T> &e) {
    if (never_hld)
      hld_build();
    return depth[e.f] > depth[e.t] ? vid[e.f] : vid[e.t];
  }

  template <class... U> int operator()(U... args) { return bel(args...); }

  template <class S> void seg_add(S &seg, int lhei, int rhei, int v) {
    for_each_(lhei, rhei, [&](int l, int r) { seg.add(l, r, v); });
  }

  template <class S> void seg_update(S &seg, int lhei, int rhei, int v) {
    for_each_(lhei, rhei, [&](int l, int r) { seg.update(l, r, v); });
  }

  template <class S> T seg_get(S &seg, int lhei, int rhei) {
    T res = seg.e;
    for_each_(lhei, rhei,
              [&](int l, int r) { res = seg.f(res, seg.get(l, r)); });
    return res;
  }

  template <class S> void seg_add_edge(S &seg, int lhei, int rhei, int v) {
    for_each_edge(lhei, rhei, [&](int l, int r) { seg.add(l, r, v); });
  }

  template <class S> void seg_update_edge(S &seg, int lhei, int rhei, int v) {
    for_each_edge(lhei, rhei, [&](int l, int r) { seg.update(l, r, v); });
  }

  template <class S> T seg_get_edge(S &seg, int lhei, int rhei) {
    T res = seg.e;
    for_each_edge(lhei, rhei,
                  [&](int l, int r) { res = seg.f(res, seg.get(l, r)); });
    return res;
  }

  template <class S> void seg_add(S &seg, int i, int v) { seg.add(bel(i), v); }

  template <class S> void seg_update(S &seg, int i, int v) {
    seg.update(bel(i), v);
  }

  template <class S> T seg_get(S &seg, int i) { return seg[i]; }

  template <class S> void seg_del(S &seg, int i) { seg.del(bel(i)); }

  template <class S> void seg_add_sub(S &seg, int i, int v) {
    if (never_hld)
      hld_build();
    seg.add(subl[i], subr[i], v);
  }

  template <class S> void seg_update_sub(S &seg, int i, int v) {
    if (never_hld)
      hld_build();
    seg.update(subl[i], subr[i], v);
  }

  template <class S> T seg_get_sub(S &seg, int i, int v) {
    if (never_hld)
      hld_build();
    return seg.get(subl[i], subr[i], v);
  }

  template <class S> void seg_add_sub_edge(S &seg, int i, int v) {
    if (never_hld)
      hld_build();
    seg.add(subl[i] + 1, subr[i], v);
  }

  template <class S> void seg_update_sub_edge(S &seg, int i, int v) {
    if (never_hld)
      hld_build();
    seg.update(subl[i] + 1, subr[i], v);
  }

  template <class S> T seg_get_sub_edge(S &seg, int i, int v) {
    if (never_hld)
      hld_build();
    return seg.get(subl[i] + 1, subr[i], v);
  }
};

template <class T = int> class grid_k6 : public undigraph<T> {

  vi costs;

public:
  using undigraph<T>::g;
  using undigraph<T>::n;
  using undigraph<T>::edges;

  int H, W;

  vector<vector<char>> ba;

  char wall;

  void add(int f, int t, T c = 1) {

    if (!(0 <= f && f < n && 0 <= t && t < n)) {
      debugline("grid_k6 add");
      deb(f, t, c);
      ole();
    }

    g[f].emplace_back(f, t, c);

    g[t].emplace_back(t, f, c);
  }

  int getid(int h, int w) {
    assert(ins(h, w, H, W));
    return W * h + w;
  }

  int getid(P p) { return getid(p.first, p.second); }

  P get2(int id) { return mp(id / W, id % W); }

  P operator()(int id) { return get2(id); }

  int operator()(int h, int w) { return getid(h, w); }

  int operator()(P p) { return getid(p); }

  grid_k6(int H, int W) : H(H), W(W), undigraph<T>(H * W) {}

  grid_k6(vector<vector<char>> ba, char wall = '#')
      : H(sz(ba)), W(sz(ba[0])), undigraph<T>(sz(ba) * sz(ba[0])) {
    rep(h, H) {
      rep(w, W) {
        if (ba[h][w] == wall)
          con;
        int f = getid(h, w);
        if (w + 1 < W && ba[h][w + 1] != wall) {
          add(f, getid(h, w + 1));
        }
        if (h + 1 < H && ba[h + 1][w] != wall) {
          add(f, getid(h + 1, w));
        }
      }
    }
  }

  grid_k6(vector<vector<char>> ba, int oo, int ox, int xo, int xx,
          char wall = '#')
      : H(sz(ba)), W(sz(ba[0])), undigraph<T>(sz(ba) * sz(ba[0])),
        costs({oo, ox, xo, xx}), ba(ba), wall(wall) {
    rep(h, H) {
      rep(w, W) {
        add(h, w, h + 1, w);
        add(h, w, h - 1, w);
        add(h, w, h, w + 1);
        add(h, w, h, w - 1);
      }
    }
  }

  void add(int fh, int fw, int th, int tw) {

    if (ins(fh, fw, H, W) && ins(th, tw, H, W)) {

      int cm = 0;

      if (ba[fh][fw] == wall) {
        cm += 2;
      }

      if (ba[th][tw] == wall) {
        cm++;
      }

      int f = getid(fh, fw);

      int t = getid(th, tw);

      g[f].emplace_back(f, t, costs[cm]);
    }
  }

  void set_edges() {
    rep(i, n) fora(e, g[i]) if (e.f < e.t) edges.push_back(e);
  }
};

template <class T = int> class digrid_k6 : public digraph<T> {

public:
  using digraph<T>::g;
  using digraph<T>::n;
  using digraph<T>::edges;

  int H, W;

  void add(int f, int t, T c = 1) {

    if (!(0 <= f && f < n && 0 <= t && t < n)) {
      debugline("digrid_k6 add");
      deb(f, t, c);
      ole();
    }

    g[f].emplace_back(f, t, c);
  }

  int getid(int h, int w) {
    if (!ins(h, w, H, W))
      return -1;
    return W * h + w;
  }

  P get2(int id) { return mp(id / W, id % W); }

  P operator()(int id) { return get2(id); }

  int operator()(int h, int w) { return getid(h, w); }

  digrid_k6(int H, int W) : H(H), W(W), digraph<T>(H * W) {}

  digrid_k6(vector<vector<char>> ba, char wall = '#')
      : H(sz(ba)), W(sz(ba[0])), digraph<T>(sz(ba) * sz(ba[0])) {
    rep(h, H) {
      rep(w, W) {
        if (ba[h][w] == wall)
          con;
        int f = getid(h, w);
        if (w + 1 < W && ba[h][w + 1] != wall) {
          add(f, getid(h, w + 1));
        }
        if (h + 1 < H && ba[h + 1][w] != wall) {
          add(f, getid(h + 1, w));
        }
      }
    }
  }

  void add(int fh, int fw, int th, int tw) {
    add(getid(fh, fw), getid(th, tw));
  }

  void set_edges() { rep(i, n) fora(e, g[i]) edges.push_back(e); }
};

template <class T = int> class segdi : public digraph<T> {
  int getid(int k) {
    if (k >= len * 2 - 1) {
      return k;
    } else if (k < len - 1) {
      return k + len;
    } else {
      return k - len + 1;
    }
  }
  void add(int f, int t, T c = 1) {
    f = getid(f);
    t = getid(t);
    if (!(0 <= f && f < n && 0 <= t && t < n)) {
      debugline("segdi add");
      deb(f, t, c);
      ole();
    }
    g[f].emplace_back(f, t, c);
  }
  int mid;
  int len;

public:
  using digraph<T>::g;
  using digraph<T>::n;
  using digraph<T>::edges;

  segdi(int n_) : digraph<T>(1) {
    int nn = 1;
    while (nn < n_)
      nn *= 2;
    n_ = nn;
    len = n_;
    this->resize(n_ + (n_ - 1) * 2 + n_);
    mid = n_ + (n_ - 1) * 2;
    int ad = len * 2 - 1;
    rep(i, len - 1) {
      add(i, i * 2 + 1, 0);
      add(i, i * 2 + 2, 0);
      if (i * 2 + 1 >= len - 1) {
        add(i * 2 + 1, i + ad, 0);
        add(i * 2 + 2, i + ad, 0);
      } else {
        add(i * 2 + 1 + ad, i + ad, 0);
        add(i * 2 + 2 + ad, i + ad, 0);
      }
    }
  }

  void dfs(vi &list, int nl, int nr, int k, int l, int r) {
    if (r <= nl || nr <= l)
      return;
    if (l <= nl && nr <= r) {
      list += k;
    } else {
      dfs(list, nl, (nl + nr) / 2, k * 2 + 1, l, r);
      dfs(list, (nl + nr) / 2, nr, k * 2 + 2, l, r);
    }
  }

  void rekkyo(vi &list, int l, int r) {
    l += len - 1;
    r += len - 1;
    while (l < r) {
      if (!(l & 1)) {
        list.push_back(l);
      }
      if (!(r & 1)) {
        list.push_back(r - 1);
      }
      l >>= 1;
      r = (r - 1) >> 1;
    }
  }

  void add(int fl, int fr, int tl, int tr, int cost) {
    int ad = 2 * len - 1;
    if (mid >= n) {
      this->resize(n + 100);
    }
    {
      int l = fl, r = fr;
      l += len - 1;
      r += len - 1;
      while (l < r) {
        if (!(l & 1)) {
          if (l - len + 1 < 0)
            add(l + ad, mid, cost);
          else
            add(l, mid, cost);
        }
        if (!(r & 1)) {
          if (r - 1 - len + 1 < 0)
            add(r - 1 + ad, mid, cost);
          else
            add(r - 1, mid, cost);
        }
        l >>= 1;
        r = (r - 1) >> 1;
      }
    }
    {
      int l = tl, r = tr;
      l += len - 1;
      r += len - 1;
      while (l < r) {
        if (!(l & 1)) {
          add(mid, l, 0);
        }
        if (!(r & 1)) {
          add(mid, r - 1, 0);
        }
        l >>= 1;
        r = (r - 1) >> 1;
      }
    }
    mid++;
  }
};

