  void rekkyo(vi &list, int l, int r) {
    l += len - 1;
    r += len - 1;
    while (l < r) {
      if (!(l & 1)) {
        list.push_back(l);
      }
      if (!(r & 1)) {
        list.push_back(r - 1);
      }
      l >>= 1;
      r = (r - 1) >> 1;
    }
  }

  void add(int fl, int fr, int tl, int tr, int cost) {
    int ad = 2 * len - 1;
    if (mid >= n) {
      this->resize(n + 100);
    }
    {
      int l = fl, r = fr;
      l += len - 1;
      r += len - 1;
      while (l < r) {
        if (!(l & 1)) {
          if (l - len + 1 < 0)
            add(l + ad, mid, cost);
          else
            add(l, mid, cost);
        }
        if (!(r & 1)) {
          if (r - 1 - len + 1 < 0)
            add(r - 1 + ad, mid, cost);
          else
            add(r - 1, mid, cost);
        }
        l >>= 1;
        r = (r - 1) >> 1;
      }
    }
    {
      int l = tl, r = tr;
      l += len - 1;
      r += len - 1;
      while (l < r) {
        if (!(l & 1)) {
          add(mid, l, 0);
        }
        if (!(r & 1)) {
          add(mid, r - 1, 0);
        }
        l >>= 1;
        r = (r - 1) >> 1;
      }
    }
    mid++;
  }
};

