template <class T> bool close(undigraph<T> &g, int v) {
  unionfind uf(g.n);
  rep(i, g.n) {
    forg(gi, g[i]) {
      forg_init(g[i]);
      if (f < t)
        break;
      if (f == t && f == v)
        return true;
      if (uf.same(f, v) && uf.same(t, v))
        return true;
      uf.unite(f, t);
    }
  }
  return false;
}
