template <class T> tree<T> get_bfs_tree(tree<T> &g, vi &ind, vi &l, vi &r) {
  if (sz(ind)) {
    cerr << "ind must be empty" << endl;
    exit(0);
  }
  int N = sz(g);
  ind.resize(N);
  l.resize(N, inf);
  r.resize(N, -1);
  tree<T> h(N);
  queue<P> q;
  q.emplace(-1, 0);
  int c = 0;
  while (sz(q)) {
    int p = q.front().first;
    int i = q.front().second;
    q.pop();
    ind[i] = c;
    if (~p)
      chmi(l[ind[p]], c);
    if (~p)
      chma(r[ind[p]], c);
    c++;
    forg(gi, g[i]) {
      forg_init(g[i]);
      if (t != p)
        q.emplace(i, t);
    }
  }
  fora(e, g.edges) {
    if (e.f < e.t) {
      h.add(ind[e.f], ind[e.t], e.c);
    }
  }
  rep(i, N) {
    if (l[i] == inf)
      l[i] = -1;
  }
  return h;
}

