template <class T> int longest_path(digraph<T> &g) {
  vi top;
  if (!topo(top, g)) {
    return linf;
  }
  int n = sz(top);
  vi dp(n, 0);
  for (auto &&i : top) {
    forg(gi, g[i]) {
      forg_init(g[i]);
      chma(dp[t], dp[i] + 1);
    }
  }
  return max(dp);
}

template <class T> vi longest_path_v(digraph<T> &g) {
  vi top;
  if (!topo(top, g)) {
    return vi();
  }
  int n = sz(top);
  vi dp(n, 0);
  vi pre(n, -1);
  for (auto &&i : top) {
    forg(gi, g[i]) {
      forg_init(g[i]);
      if (chma(dp[t], dp[i] + 1)) {
        pre[t] = i;
      }
    }
  }
  int s = std::max_element(dp.begin(), dp.end()) - dp.begin();
  vi path;
  while (s != -1) {
    path.push_back(s);
    s = pre[s];
  }
  std::reverse(path.begin(), path.end());
  return path;
}

template <class T> vp bridge(graph<T> &G) {
  static bool was;
  vp brid;
  vi articulation;
  vi ord(G.n), low(G.n);
  vb vis(G.n);
  function<void(int, int, int)> dfs = [&](int v, int p, int k) {
    vis[v] = true;
    ord[v] = k++;
    low[v] = ord[v];
    bool isArticulation = false;
    int ct = 0;
    for (int i = 0; i < G[v].size(); i++) {
      if (!vis[G[v][i].t]) {
        ct++;
        dfs(G[v][i].t, v, k);
        low[v] = min(low[v], low[G[v][i].t]);
        if (~p && ord[v] <= low[G[v][i].t])
          isArticulation = true;
        if (ord[v] < low[G[v][i].t])
          brid.push_back(make_pair(min(v, G[v][i].t), max(v, G[v][i].t)));
      } else if (G[v][i].t != p) {
        low[v] = min(low[v], ord[G[v][i].t]);
      }
    }
    if (p == -1 && ct > 1)
      isArticulation = true;
    if (isArticulation)
      articulation.push_back(v);
  };
  int k = 0;
  rep(i, G.n) {
    if (!vis[i])
      dfs(i, -1, k);
  }
  sort(brid.begin(), brid.end());
  return brid;
}

