vi close_path_min(digraph<> &g) {
  int n = g.n;
  vvi(dis, n);
  rep(i, n) dis[i] = dijkstra(g, i, linf);
  int mind = linf;
  int f = 0, t = 0;
  rep(i, n) {
    rep(j, n) {
      if (i == j)
        continue;
      if (chmi(mind, dis[i][j] + dis[j][i])) {
        f = i;
        t = j;
      }
    }
  }
  vi path;
  auto add = [&](int f, int t) {
    int now = f;
    while (now != t) {
      rep(i, n) {
        if (dis[now][i] == 1 && dis[f][i] + dis[i][t] == dis[f][t]) {
          path.push_back(i);
          now = i;
          break;
        }
      }
    }
  };
  add(f, t);
