template <class T> struct helper_pq {
  priority_queue<T, vector<T>, greater<T>> q;
  T su = 0;
  helper_pq() {}
  void clear() {
    q = priority_queue<T, vector<T>, greater<T>>();
    su = 0;
  }
  void operator+=(T v) {
    su += v;
    q.push(v);
  }
  T sum() { return su; }
  T top() { return q.top(); }
  void pop() {
    su -= q.top();
    q.pop();
  }
  T poll() {
