template <class T> struct pq {
  helper_pq<T> a_q;
  helper_pq_size<T> b_q;
  bool aquery;
  T su = 0;
  pq(int size = inf) {
    aquery = size == inf;
    if (!aquery) {
      b_q = helper_pq_size<T>(size);
    }
  }
  void clear() {
    if (aquery)
      a_q.clear();
    else
      b_q.clear();
  }
  void operator+=(T v) {
    if (aquery)
      a_q += v;
    else
      b_q += v;
  }
  T sum() {
    if (aquery)
      return a_q.sum();
    else
      return b_q.sum();
  }
  T top() {
    if (aquery)
      return a_q.top();
    else
      return b_q.top();
  }
  void pop() {
    if (aquery)
      a_q.pop();
    else
      b_q.pop();
  }
  T poll() {
    if (aquery)
      return a_q.poll();
    else
      return b_q.poll();
  }
  ll size() {
    if (aquery)
      return a_q.size();
    else
      return b_q.size();
  }
};

