template <class T>
void nex_repv2(int &i, int &j, int &I, int &J, vector<vector<T>> &s) {
  while (1) {
    j++;
    if (j >= J) {
      j = 0;
      i++;
      if (i < I) {
        J = (int)s[i].size();
      }
    }
    if (i >= I || J)
      return;
  }
}

template <class T>
void nex_repv3(int &i, int &j, int &k, int &I, int &J, int &K,
               vector<vector<vector<T>>> &s) {
  while (1) {
    k++;
    if (k >= K) {
      k = 0;
      j++;
      if (j >= J) {
        j = 0;
        i++;
        if (i >= I)
          return;
      }
    }
    J = (int)s[i].size();
    K = (int)s[i][j].size();
    if (J && K)
      return;
  }
}

