string deb_tos_f(vector<vector<T>> &a, F f, int key = -1) {
  vi hs, ws_;
  int H = sz(a), W = sz(a[0]);
  vi exh(H), exw(W);
  rep(h, H) {
    rep(w, W) {
      if (f(a[h][w])) {
        exh[h] = true;
        exw[w] = true;
      }
    }
  }
  rep(h, H) if (exh[h]) hs.push_back(h);
  rep(w, W) if (exw[w]) ws_.push_back(w);
  return deb_tos(a, hs, ws_, key);
}

