ll keta(ll v, int if_zero_res) {
  if (!v)
    return if_zero_res;
  if (v < p10[9]) {
    if (v < p10[4]) {
      if (v < p10[2]) {
        if (v < p10[1]) {
          if (v < p10[0])
            return 0;
          else
            return 1;
        } else
          return 2;
      } else {
        if (v < p10[3])
          return 3;
        else
          return 4;
      }
    } else {
      if (v < p10[7]) {
        if (v < p10[5])
          return 5;
        else if (v < p10[6])
          return 6;
        else
          return 7;
      } else {
        if (v < p10[8])
          return 8;
        else
          return 9;
      }
    }
  } else {
    if (v < p10[13]) {
      if (v < p10[11]) {
        if (v < p10[10])
          return 10;
        else
          return 11;
      } else {
        if (v < p10[12])
          return 12;
        else
          return 13;
      }
    } else {
      if (v < p10[15]) {
        if (v < p10[14])
          return 14;
        else
          return 15;
      } else {
        if (v < p10[17]) {
          if (v < p10[16])
            return 16;
          else
            return 17;
        } else {
          if (v < p10[18])
            return 18;
          else
            return 19;
        }
      }
    }
  }
}

