#define dijkstra_path dis_path

template <class T, class I>
vi dis_path(digraph<T> &g, vector<T> &dis, int s, int t, I init_value) {
  assert(dis[t] != init_value);
  auto rg = rev(g);
  int now = t;
  vi path;
  path.push_back(now);
  T cost = 0;
  while (now != s) {
    rep(gi, sz(rg[now])) {
      int m = rg[now][gi].t;
      if (dis[m] == init_value)
        continue;
      if (dis[m] + rg[now][gi].c + cost == dis[t]) {
        cost += rg[now][gi].c;
        now = m;
        break;
      }
    }
    path.push_back(now);
  }
  rev(path);
  return path;
}

