tuple<bool, vi> topo(digraph<int> &g) {
  vi res;
  int n = g.g.size();
  vi nyu(n);
  rep(i, n) for (auto &&e : g[i]) nyu[e.t]++;
  queue<int> st;
  rep(i, n) if (nyu[i] == 0) st.push(i);
  while (st.size()) {
    int v = st.front();
    st.pop();
    res.push_back(v);
    fora(e, g[v]) if (--nyu[e.t] == 0) st.push(e.t);
  }
  return make_tuple(res.size() == n, res);
}

tuple<bool, vi> topos(digraph<int> &g) {
  vi res;
  int n = g.g.size();
  vi nyu(n);
  rep(i, n) for (auto &&e : g[i]) nyu[e.t]++;
  priority_queue<int, vector<int>, greater<int>> q;
