template <class T> vi longest_path_v(digraph<T> &g) {
  vi top;
  if (!topo(top, g)) {
    return vi();
  }
  int n = sz(top);
  vi dp(n, 0);
  vi pre(n, -1);
  for (auto &&i : top) {
    forg(gi, g[i]) {
      forg_init(g[i]);
      if (chma(dp[t], dp[i] + 1)) {
        pre[t] = i;
      }
    }
  }
  int s = std::max_element(dp.begin(), dp.end()) - dp.begin();
  vi path;
  while (s != -1) {
    path.push_back(s);
    s = pre[s];
  }
  std::reverse(path.begin(), path.end());
  return path;
}

