  while (ch > '9' || ch < '0') {
    if (ch == '-')
      f = -1;
    ch = getchar();
  }

  while (ch >= '0' && ch <= '9') {
    sum = (sum << 3) + (sum << 1) + ch - '0';
    ch = getchar();
  }

  return f * sum;
}

const int N = 110;

int n, x, D, p[N], v[N], id[N];

ll m[N], f[N * N * N];

void upt(ll m, int val) {
  for (int i = n * n * n; i >= val; i--)
    f[i] = min(f[i], f[i - val] + m);
}

bool cmp(int x, int y) { return 1ll * m[y] * v[x] > 1ll * m[x] * v[y]; }

int main()

{

  n = gi();
  x = gi();
  D = gi();
  m[1] = gi();

  for (int i = 2; i <= n; i++) {
