    v[i] = 1, id[i] = i;

  for (int i = n; i > 1; i--)
    m[p[i]] += m[i], v[p[i]] += v[i];

  memset(f, 63, sizeof(f));
  f[0] = 0;

  for (int i = 1; i <= n; i++)

  {

    int lim = 1, ret = (i == 1) ? n : min(n, D);

    while (ret >= lim)

    {

      ret -= lim;
      upt(1ll * m[i] * lim, 1ll * lim * v[i]);
      lim <<= 1;
    }

    upt(1ll * m[i] * ret, 1ll * ret * v[i]);
  }

  int ans = 0;
  sort(id + 1, id + n + 1, cmp);

  for (int i = 0; i <= n * n * n; i++)

    if (f[i] <= x)

