      int res = x - f[i], sum = i;

      for (int j = 1; j <= n; j++)

      {

        int del = (id[j] == 1) ? res / m[1]
                               : min(max(0ll, (ll)D - n), res / m[id[j]]);

        sum += v[id[j]] * del;

        res -= del * m[id[j]];
      }

      ans = max(ans, sum);
    }

  printf("%d\n", ans);

  return 0;
}

