int memo[5][5][1111];

int a, b;

int solve(int k, int t, int q) {

  if (k == 4)
    return abs(p[t][q].first - gx) + abs(p[t][q].second - gy);

  if (memo[k][t][q])
    return memo[k][t][q];

  int ans = INF, d = (t + 1) % 5, s;

  for (int i = 0; i < p[d].size(); i++) {

    if (!k)
      s = abs(sx - p[d][i].first) + abs(sy - p[d][i].second);

    else
      s = abs(p[t][q].first - p[d][i].first) +
          abs(p[t][q].second - p[d][i].second);

    ans = min(ans, solve(k + 1, d, i) + s);
  }

  return memo[k][t][q] = ans;
}

int main() {

  int w, h;

  char c;

  while (true) {

    scanf("%d %d", &w, &h);

    if (!w && !h)
