      for (int j = 0; j < w; j++) {

        scanf(" %c", &c);

        if (c == 'S')
          sx = j, sy = i;

        if (c == 'G')
          gx = j, gy = i;

        else if (c != '.')
          p[c - '1'].push_back(P(j, i));
      }
    }

    b = INF;

    for (int i = 0; i < 5; i++) {

      memset(memo, 0, sizeof(memo));

      if (b > solve(0, i, 0))
        a = i, b = solve(0, i, 0);
