using std::cout;

using std::vector;

using std::endl;

using std::cin;

using std::string;

using std::min;

using std::max;

const ll MOD = 1000000007;

const ll INF = 9e9;

ll N, M, ans = INF;

ll A[300010], S[301000];

using namespace std;

int main() {

  fill(begin(S), end(S), 0);

  N = M = 0;

  std::ios_base::sync_with_stdio(false);

  cin >> N;

  REP(i, N) {

    cin >> A[i];

    S[i] += A[i];

    S[i + 1] = S[i];
  }

  ll a = 0, b = 2, s, t;

  REP(i, N - 1) {

    if (i == b)
      b++;

    s = (S[i] - S[a]) - S[a];

    t = (S[N - 1] - S[b]) - (S[b] - S[i]);

    bool f = true;

    if (i == 0)
      continue;

    while (f) {

      f = false;

      if (a + 1 == i)
        continue;

      if (abs(s) > abs(s - A[a + 1] * 2)) {

        s -= A[a + 1] * 2;

        a++;
        f = true;
      }
    }

    f = true;

    while (f) {

      f = false;

      if (b + 1 == N - 1 || b == N - 1)
        continue;

      if (abs(t) > abs(t - A[b + 1] * 2)) {

        t -= A[b + 1] * 2;

        b++;
        f = true;
      }
