#include <bits/stdc++.h>

#define INF (1e9)

#define MAX_V 2010

#define MAX_N 1010

using namespace std;

struct edge {
  int to, cap, rev;
};

vector<edge> G[MAX_V];

bool used[MAX_V];

void add_edge(int from, int to, int cap) {

  G[from].push_back((edge){to, cap, G[to].size()});

  G[to].push_back((edge){from, 0, G[from].size() - 1});
}

int dfs(int v, int t, int f) {

  if (v == t)
    return f;

  used[v] = true;

  for (int i = 0; i < G[v].size(); i++) {

    edge &e = G[v][i];

    if (!used[e.to] && e.cap > 0) {

      int d = dfs(e.to, t, min(f, e.cap));

      if (d > 0) {

        e.cap -= d;

        G[e.to][e.rev].cap += d;

        return d;
      }
    }
  }

  return 0;
}

int max_flow(int s, int t) {

  int flow = 0;

  for (;;) {

    memset(used, 0, sizeof(used));

    int f = dfs(s, t, INF);

    if (f == 0)
      return flow;

    flow += f;
  }
}

bool can[MAX_N][MAX_N];

int Biparite_Matching(int N, int K) {

  int s = N + K, t = s + 1;

  for (int i = 0; i < N; i++)
    add_edge(s, i, 1);

  for (int i = 0; i < K; i++)
    add_edge(N + i, t, 1);

  for (int i = 0; i < N; i++)

    for (int j = 0; j < K; j++)

      if (can[i][j])
        add_edge(i, N + j, 1);

  return max_flow(s, t);
}

