  for (int i = 0; i < N; i++)
    add_edge(s, i, 1);

  for (int i = 0; i < K; i++)
    add_edge(N + i, t, 1);

  for (int i = 0; i < N; i++)

    for (int j = 0; j < K; j++)

      if (can[i][j])
        add_edge(i, N + j, 1);

  return max_flow(s, t);
}

