  return s1.x != s2.x ? s1.x < s2.x : s1.y < s2.y;
}

bool yComp(const vertex &s1, const vertex &s2) {

  return s1.y != s2.y ? s1.y < s2.y : s1.x < s2.x;
}

struct node {

  int innum;

  node *left;

  node *right;
};

