void makeT(int a, int b, node **focus, int turn) {

  if (a >= b)
    return;

  if (turn % 2 == 0)
    sort(V.begin() + a, V.begin() + b, xComp);

  else
    sort(V.begin() + a, V.begin() + b, yComp);

  int mid = (a + b) / 2;

  node *buf = (node *)malloc(sizeof(node));

  buf->innum = mid;

  buf->left = NIL;

  buf->right = NIL;

  *focus = buf;

  makeT(a, mid, &((*focus)->left), turn + 1);

  makeT(mid + 1, b, &((*focus)->right), turn + 1);
}

vi ret;

void findT(int sx, int tx, int sy, int ty, node *focus, bool t) {

  if (focus == NIL)
    return;

  int xx = V[focus->innum].x, yy = V[focus->innum].y;

  if (sx <= xx && xx <= tx && sy <= yy && yy <= ty) {

    ret.push_back(V[focus->innum].id);
  }

  if (t == 0) {

    if (sx <= xx)
      findT(sx, tx, sy, ty, focus->left, 1);

    if (xx <= tx)
      findT(sx, tx, sy, ty, focus->right, 1);

  }

  else {

    if (sy <= yy)
      findT(sx, tx, sy, ty, focus->left, 0);

    if (yy <= ty)
      findT(sx, tx, sy, ty, focus->right, 0);
  }
}

int main() {

  root = NIL;

  int n;

  scanf("%d", &n);

  Loop(i, n) {

    int x, y;

    scanf("%d %d", &x, &y);

