    if (target == nil)
      return;

    else {

      Loop(i, dimension) {

        focus->range_l[i] = min(focus->range_l[i], target->range_l[i]);

        focus->range_r[i] = max(focus->range_r[i], target->range_r[i]);
      }

      return;
    }
