template <typename T, typename F> int erase_if2(vector<T> &v, F f) {
  vector<T> nv;
  int cou = 0;
  rep(i, sz(v)) {
    if (f(v[i])) {
      cou++;
    } else {
      nv.push_back(v[i]);
    }
  }
  v = nv;
  return cou;
}

template <typename T, typename F> int erase_if2(vector<vector<T>> &v, F f) {
  int cou = 0;
  rep(i, sz(v)) { cou += erase_if2(v[i], f); }
  return cou;
}

