  H = min({H, sz(a), 12ll});

  W = min({W, sz(a[0]), 12ll});

  stringstream ss;

  ss << endl;

  if (key == -1)
    ss << " *|";
  else
    ss << " " << key << "|";

  rep(w, W) ss << std::right << std::setw(4) << w;

  ss << "" << endl;

  rep(w, W * 4 + 3) ss << "_";

  ss << "" << endl;

  rep(h, H) {

    ss << std::right << std::setw(2) << h << "|";

    rep(w, min(sz(a[h]), 12ll)) {
      if (abs(a[h][w]) == linf)
        ss << "   e" << "";
      else
        ss << std::right << std::setw(4) << a[h][w];
    }

    ss << "" << endl;
  }

  return ss.str();
}

