struct sint {

  ll v;

  sint(ll v) : v(v) {}

  operator ll() { return v; }

  ll operator[](ll i) { return (v / p10[i]) % 10; }

  ll back(ll i) { return operator[](i); }

  ll top(ll i) {

    ll len = keta(v);

    return operator[](len - 1 - i);
  }

  ll settop(ll i, ll k) {

    ll len = keta(v);

    return set(len - 1 - i, k);
  }

  ll set(ll i, ll k) {

    if (i < 0)
      return settop(abs(i) - 1, k);

    return v += p10[i] * (k - (v / p10[i]) % 10);
