  if ((g.n + sz(g.edges)) * 20 > g.n * g.n) {
    return dijkstra_mitu(g, s, init_value);
  }
  T initValue = MAX(T);
  vector<T> dis(g.n, initValue);
  priority_queue<pair<T, int>, vector<pair<T, int>>, greater<pair<T, int>>> q;
  dis[s] = 0;
  q.emplace(0, s);
  while (q.size()) {
    T nowc = q.top().fi;
    int i = q.top().se;
    q.pop();
    if (dis[i] != nowc)
      continue;
    for (auto &&e : g.g[i]) {
      int to = e.t;
      T c = nowc + e.c;
      if (dis[to] > c) {
        dis[to] = c;
        q.emplace(dis[to], to);
      }
    }
  }
  for (auto &&d : dis)
    if (d == initValue)
      d = init_value;
  return dis;
}

template <class T> vector<T> dijkstra_01(graph<T> &g, int s) {
  int N = g.n;
  vi dis(N, linf);
  dis[s] = 0;
  deque<int> q;
  q.push_back(s);
  vb was(N);
  while (!q.empty()) {
    int f = q.front();
    q.pop_front();
    if (was[f])
      continue;
    was[f] = true;
    fora(e, g[f]) {
      if (dis[e.t] > dis[f] + e.c) {
        if (e.c) {
          dis[e.t] = dis[f] + 1;
          q.push_back(e.t);
        } else {
          dis[e.t] = dis[f];
          q.push_front(e.t);
        }
      }
    }
  }
  return dis;
}

