template <class T>
vector<T> dijkstra_mitu(const graph<T> &g, int s, int init_value = -1) {
  if (!(0 <= s && s < g.n)) {
    debugline("dijkstra_mitu");
    deb(s, g.n);
    ole();
  }
  T initValue = MAX(T);
  vector<T> dis(g.n, initValue);
  dis[s] = 0;
  vb used(g.n);
  while (true) {
    int v = -1;
    rep(i, g.n) {
      if (!used[i] && ((v == -1 && dis[i] != initValue) || (dis[i] < dis[v]))) {
        v = i;
      }
    }
    if (v == -1)
      break;
    used[v] = 1;
    for (auto &&e : g.g[v]) {
      if (dis[e.t] > dis[v] + e.c) {
        dis[e.t] = dis[v] + e.c;
      }
    }
  }
  for (auto &&d : dis) {
    if (d == initValue) {
      d = init_value;
    }
  }
  return dis;
}

template <typename T> struct radixheap {
  vector<pair<u64, T>> v[65];
  u64 size, last;
  radixheap() : size(0), last(0) {}
  bool empty() const { return size == 0; }
  int getbit(int a) { return a ? 64 - __builtin_clzll(a) : 0; }
  void push(u64 key, const T &value) {
    ++size;
    v[getbit(key ^ last)].emplace_back(key, value);
  }
  pair<u64, T> pop() {
    if (v[0].empty()) {
      int idx = 1;
      while (v[idx].empty())
        ++idx;
      last = min_element(begin(v[idx]), end(v[idx]))->first;
      for (auto &p : v[idx])
        v[getbit(p.first ^ last)].emplace_back(p);
      v[idx].clear();
    }
    --size;
    auto ret = v[0].back();
    v[0].pop_back();
    return ret;
  }
};

vi dijkstra(const graph<int> &g, int s, int init_value = -1) {
  if (!(0 <= s && s < g.n)) {
    debugline("dijkstra");
    deb(s, g.n);
    ole();
  }
  if ((g.n + sz(g.edges)) * 20 > g.n * g.n) {
    return dijkstra_mitu(g, s, init_value);
  }
  int initValue = MAX(int);
  vi dis(g.n, initValue);
  radixheap<int> q;
  dis[s] = 0;
  q.push(0, s);
  while (!q.empty()) {
    int nowc, i;
    tie(nowc, i) = q.pop();
    if (dis[i] != nowc)
      continue;
    for (auto &&e : g.g[i]) {
      int to = e.t;
      int c = nowc + e.c;
      if (dis[to] > c) {
        dis[to] = c;
        q.push(dis[to], to);
      }
    }
  }
  for (auto &&d : dis)
    if (d == initValue)
      d = init_value;
  return dis;
}

template <class T>
vector<T> dijkstra_normal(const graph<T> &g, int s, int init_value = -1) {
  if (!(0 <= s && s < g.n)) {
    debugline("dijkstra");
    deb(s, g.n);
    ole();
  }
  if ((g.n + sz(g.edges)) * 20 > g.n * g.n) {
    return dijkstra_mitu(g, s, init_value);
  }
  T initValue = MAX(T);
  vector<T> dis(g.n, initValue);
  priority_queue<pair<T, int>, vector<pair<T, int>>, greater<pair<T, int>>> q;
  dis[s] = 0;
  q.emplace(0, s);
  while (q.size()) {
    T nowc = q.top().fi;
    int i = q.top().se;
    q.pop();
    if (dis[i] != nowc)
      continue;
    for (auto &&e : g.g[i]) {
      int to = e.t;
      T c = nowc + e.c;
      if (dis[to] > c) {
        dis[to] = c;
        q.emplace(dis[to], to);
      }
    }
  }
  for (auto &&d : dis)
    if (d == initValue)
      d = init_value;
  return dis;
}

template <class T> vector<T> dijkstra_01(graph<T> &g, int s) {
  int N = g.n;
  vi dis(N, linf);
  dis[s] = 0;
  deque<int> q;
  q.push_back(s);
  vb was(N);
  while (!q.empty()) {
    int f = q.front();
    q.pop_front();
    if (was[f])
      continue;
    was[f] = true;
    fora(e, g[f]) {
      if (dis[e.t] > dis[f] + e.c) {
        if (e.c) {
          dis[e.t] = dis[f] + 1;
          q.push_back(e.t);
        } else {
          dis[e.t] = dis[f];
          q.push_front(e.t);
        }
      }
    }
  }
  return dis;
}

template <class COU, class T = int>
auto dijkstra_cou(const graph<T> &g, int s, int init_value = -1) {
  if (!(0 <= s && s < g.n)) {
    debugline("dijkstra");
    deb(s, g.n);
    ole();
  }
  err("count by type COU ");
  err("int or mint");
  T initValue = MAX(T);
  vector<T> dis(g.n, initValue);
  vector<COU> cou(g.n);
  cou[s] = 1;
  priority_queue<pair<T, int>, vector<pair<T, int>>, greater<pair<T, int>>> q;
  dis[s] = 0;
  q.emplace(0, s);
  while (q.size()) {
    T nowc = q.top().fi;
    int i = q.top().se;
    q.pop();
    if (dis[i] != nowc)
      continue;
    for (auto &&e : g.g[i]) {
      int to = e.t;
      T c = nowc + e.c;
      if (dis[to] > c) {
        dis[to] = c;
        cou[to] = cou[e.f];
        q.emplace(dis[to], to);
      } else if (dis[to] == c) {
        cou[to] += cou[e.f];
      }
    }
  }
  for (auto &&d : dis)
    if (d == initValue)
      d = init_value;
  return vtop(dis, cou);
}

template <class T>
vector<vector<T>> dijkstra_all(const graph<T> &g, int init_value = -1) {
  int n = g.n;
  assert(n < 1e4);
  if (n * n < (n + sz(g.edges)) * 14) {
    return warshall(g, init_value);
  }
  vector<vector<T>> dis(n);
  rep(i, n) { dis[i] = dijkstra(g, i, init_value); }
  return dis;
}

template <class T> vector<T> bell(graph<T> &g, int s) {
  if (g.n >= 1e4) {
    cout << "bell size too big" << endl;
    exit(0);
  }
  vector<T> res(g.n, linf);
  res[s] = 0;
  vb can(g.n);
  fix([&](auto ds, int p, int i) -> void {
    if (can[i])
      return;
    can[i] = true;
    forg(gi, g[i]) if (t != p) ds(i, t);
  })(-1, 0);
  vector<edge<T>> es;
  fora(e, g.edges) {
    if (can[e.f])
      es += e;
  }
  rep(i, g.n) {
    bool upd = false;
    fora(e, es) {
      if (res[e.f] != linf && res[e.t] > res[e.f] + e.c) {
        upd = true;
        res[e.t] = res[e.f] + e.c;
      }
    }
    if (!upd)
      break;
  }
  rep(i, g.n * 2) {
    bool upd = 0;
    fora(e, g.edges) {
      if (res[e.f] != linf && res[e.t] != -linf && res[e.t] > res[e.f] + e.c) {
        upd = 1;
        res[e.t] = -linf;
      }
    }
    if (!upd)
      break;
  }
  return res;
}

template <class T> vector<T> bell_far(graph<T> &g, int s) {
  if (g.n >= 1e4) {
    cout << "bell_far size too big" << endl;
    exit(0);
  }
  vector<T> res(g.n, linf);
  res[s] = 0;
  vb can(g.n);
  fix([&](auto ds, int p, int i) -> void {
    if (can[i])
      return;
    can[i] = true;
    forg(gi, g[i]) if (t != p) ds(i, t);
  })(-1, 0);
  vector<edge<T>> es;
  fora(e, g.edges) {
    if (can[e.f])
      es += e;
  }
  rep(i, g.n) {
    bool upd = false;
    fora(e, es) {
      if (res[e.f] != linf && res[e.t] > res[e.f] - e.c) {
        upd = true;
        res[e.t] = res[e.f] - e.c;
      }
    }
    if (!upd)
      break;
  }
  rep(i, g.n * 2) {
    bool upd = 0;
    fora(e, g.edges) {
      if (res[e.f] != linf && res[e.t] != -linf && res[e.t] > res[e.f] - e.c) {
        upd = 1;
        res[e.t] = -linf;
      }
    }
    if (!upd)
      break;
  }
  rep(i, g.n) res[i] *= -1;
  return res;
}

template <class T>
vector<vector<T>> warshall(const graph<T> &g, int init_value = -1) {
  int n = g.n;
  assert(n < 1e4);
  vector<vector<T>> dis(n, vector<T>(n, linf));
  rep(i, n) fora(e, g.g[i]) {
    if (dis[e.f][e.t] > e.c) {
      dis[e.f][e.t] = e.c;
    }
  }
  rep(i, n) dis[i][i] = 0;
  rep(k, n) rep(i, n) rep(j, n) {
    if (dis[i][j] > dis[i][k] + dis[k][j]) {
      dis[i][j] = dis[i][k] + dis[k][j];
    }
  }
  rep(i, n) rep(j, n) if (dis[i][j] == linf) dis[i][j] = init_value;
  return dis;
}

template <class T> class MinOp {
public:
  T operator()(T a, T b) { return min(a, b); }
};

template <typename OpFunc> struct SparseTable {
  OpFunc op;
  signed size;
  vector<signed> lg;
  vector<vector<pair<signed, signed>>> table;
  void init(const vector<pair<signed, signed>> &array, OpFunc opfunc) {
    signed n = array.size();
    op = opfunc;
    lg.assign(n + 1, 0);
    for (signed i = 1; i <= n; i++) {
      lg[i] = 31 - __builtin_clz(i);
    }
    table.assign(lg[n] + 1, array);
    for (signed i = 1; i <= lg[n]; i++) {
      for (signed j = 0; j < n; j++) {
        if (j + (1 << (i - 1)) < n) {
          table[i][j] = op(table[i - 1][j], table[i - 1][j + (1 << (i - 1))]);
        } else {
          table[i][j] = table[i - 1][j];
        }
      }
    }
  }
  pair<signed, signed> query(signed l, signed r) {
    assert(l < r);
    return op(table[lg[r - l]][l], table[lg[r - l]][r - (1 << lg[r - l])]);
  }
};

struct PMORMQ {
  vector<signed> a;
  SparseTable<MinOp<pair<signed, signed>>> sparse_table;
  vector<vector<vector<signed>>> lookup_table;
  vector<signed> block_type;
  signed block_size, n_block;
  void init(const vector<signed> &array) {
    a = array;
    signed n = a.size();
    block_size = std::max(1, (31 - __builtin_clz(n)) / 2);
    while (n % block_size != 0) {
      a.push_back(a.back() + 1);
      n++;
    }
    n_block = n / block_size;
    vector<pair<signed, signed>> b(n_block, make_pair(INT_MAX, INT_MAX));
    for (signed i = 0; i < n; i++) {
      b[i / block_size] = min(b[i / block_size], make_pair(a[i], i));
    }
    sparse_table.init(b, MinOp<pair<signed, signed>>());
    block_type.assign(n_block, 0);
    for (signed i = 0; i < n_block; i++) {
      signed cur = 0;
      for (signed j = 0; j < block_size - 1; j++) {
        signed ind = i * block_size + j;
        if (a[ind] < a[ind + 1]) {
          cur |= 1 << j;
        }
      }
      block_type[i] = cur;
    }
    lookup_table.assign(
        1 << (block_size - 1),
        vector<vector<signed>>(block_size, vector<signed>(block_size + 1)));
    for (signed i = 0; i < (1 << (block_size - 1)); i++) {
      for (signed j = 0; j < block_size; j++) {
        signed res = 0;
        signed cur = 0;
        signed pos = j;
        for (signed k = j + 1; k <= block_size; k++) {
          lookup_table[i][j][k] = pos;
          if (i & (1 << (k - 1))) {
            cur++;
          } else {
            cur--;
          }
          if (res > cur) {
            pos = k;
            res = cur;
          }
        }
      }
    }
  }
  signed query(signed l, signed r) {
    assert(l < r);
    signed lb = l / block_size;
    signed rb = r / block_size;
    if (lb == rb) {
      return lb * block_size +
             lookup_table[block_type[lb]][l % block_size][r % block_size];
    }
    signed pl = lb * block_size +
                lookup_table[block_type[lb]][l % block_size][block_size];
    signed pr =
        rb * block_size + lookup_table[block_type[rb]][0][r % block_size];
    signed pos = pl;
    if (r % block_size > 0 && a[pl] > a[pr]) {
      pos = pr;
    }
    if (lb + 1 == rb) {
      return pos;
    }
    signed spv = sparse_table.query(lb + 1, rb).second;
    if (a[pos] > a[spv]) {
      return spv;
    }
    return pos;
  }
};

template <class T = int> class tree : public undigraph<T> {
  PMORMQ rmq;
  int cnt;
  vector<signed> id, in;
  bool never = true;
  bool never_hld = true;
  void dfs(int x, int p, int d, int dis = 0) {
    id[cnt] = x;
    par[x] = p;
    rmq_dep.push_back(d);
    disv[x] = dis;
    in[x] = cnt++;
    forg(gi, g[x]) {
      if (t == p) {
        continue;
      }
      dfs(t, x, d + 1, dis + c);
      id[cnt] = x;
      rmq_dep.push_back(d);
      cnt++;
    }
  }
  void precalc() {
    never = false;
    cnt = 0;
    rmq_dep.clear();
    disv.assign(n, 0);
    in.assign(n, -1);
    id.assign(2 * n - 1, -1);
    par.assign(n, -1);
    dfs(root, -1, 0);
    rmq.init(rmq_dep);

#ifdef _DEBUG

    if (n >= 100)
      return;
    cerr << "---tree---" << endl;
    rep(i, n) {
      if (!(i == root || sz(g[i]) > 1))
        continue;
      cerr << i << " -> ";
      vi ts;
      forg(gi, g[i]) {
        if (t != par[i])
          ts.push_back(t);
      }
      rep(i, sz(ts) - 1) cerr << ts[i] << ", ";
      if (sz(ts))
        cerr << ts.back() << endl;
    }
    cerr << endl;

#endif
  }
  int pos;
  void hld_build() {
    never_hld = false;
    if (never)
      precalc();
    g.resize(n);
    vid.resize(n, -1);
    head.resize(n);
    heavy.resize(n, -1);
    depth.resize(n);
    inv.resize(n);
    subl.resize(n);
    subr.resize(n);
    dfs(root, -1);
    t = 0;
    dfs_hld(root);

#ifdef _DEBUG

    if (n >= 100)
      return;
    cerr << "---hld_index---" << endl;
    vi inds;
    rep(i, n) if (sz(g[i])) inds.push_back(i);
    rep(i, sz(inds)) {
      str s = tos(bel(inds[i]));
      cerr << std::right << std::setw(sz(s) + (i ? 1 : 0)) << inds[i];
    }
    cerr << endl;
    rep(i, sz(inds)) { cerr << bel(inds[i]) << " "; }
    cerr << endl << endl;
    cerr << "---hld_edge_index---" << endl;
    fora(e, edges) {
      if (e.f <= e.t)
        cerr << e.f << "-" << e.t << " " << bel(e) << endl;
    }
    cerr << endl << endl;
    cerr << "!!edge or not edge carefull!!" << endl;
    cerr << "!!if(f<t) seg.add(bel(f,t),c) carefully(f,t) (t,f)!!" << endl;

#endif
  }
  int dfs(int curr, int prev) {
    int sub = 1, max_sub = 0;
    heavy[curr] = -1;
    forg(i, g[curr]) {
      int next = t;
      if (next != prev) {
        depth[next] = depth[curr] + 1;
        int sub_next = dfs(next, curr);
        sub += sub_next;
        if (max_sub < sub_next)
          max_sub = sub_next, heavy[curr] = next;
      }
    }
    return sub;
  }
  int t = 0;
  void dfs_hld(int v = 0) {
    vid[v] = subl[v] = t;
    t++;
    inv[subl[v]] = v;
    if (0 <= heavy[v]) {
      head[heavy[v]] = head[v];
      dfs_hld(heavy[v]);
    }
    forg(i, g[v]) if (depth[v] < depth[t]) if (t != heavy[v]) {
      head[t] = t;
      dfs_hld(t);
    }
    subr[v] = t;
  }
  vector<signed> rmq_dep;

public:
  using undigraph<T>::g;
  using undigraph<T>::n;
  using undigraph<T>::edges;
  using undigraph<T>::usedv;

  vector<int> disv;

  vector<int> vid, head, heavy, par, depth, inv, subl, subr;

  int root;

  tree(int n_, int root = 0) : undigraph<T>(n_), root(root) { n = n_; }

  int lca(int a, int b) {
    if (never)
      precalc();
    int x = in[a];
    int y = in[b];
    if (x > y) {
      swap(x, y);
    }
    int pos = rmq.query(x, y + 1);
    return id[pos];
  }

  int dis(int a, int b) {
    if (never)
      precalc();
    int x = in[a];
    int y = in[b];
    if (x > y) {
      swap(x, y);
    }
    int pos = rmq.query(x, y + 1);
    int p = id[pos];
    return disv[a] + disv[b] - disv[p] * 2;
  }

  void for_each_l(int u, int v, function<void(int)> fnode) {
    int r = lca(u, v);
    while (u != r) {
      fnode(u);
      u = par[u];
    }
    while (v != r) {
      fnode(v);
      v = par[v];
    }
    fnode(r);
  }

  void for_each_edge_l(int u, int v, function<void(edge<int> &)> fedge) {
    int r = lca(u, v);
    auto sub = [&](int u, int r) {
      while (u != r) {
        forg(gi, g[u]) {
          if (t == par[u]) {
            fedge(g[u][gi]);
            u = par[u];
            break;
          }
        }
      }
    };
    sub(u, r);
    sub(v, r);
  }

  void for_each_(int u, int v, const function<void(int, int)> &f) {
    if (never_hld)
      hld_build();
    while (1) {
      if (vid[u] > vid[v])
        swap(u, v);
      int l = max(vid[head[v]], vid[u]);
      int r = vid[v] + 1;
      f(l, r);
      if (head[u] != head[v])
        v = par[head[v]];
      else
        break;
    }
  }

  void for_each_edge(int u, int v, const function<void(int, int)> &f) {
    if (never_hld)
      hld_build();
    while (1) {
      if (vid[u] > vid[v])
        swap(u, v);
      if (head[u] != head[v]) {
        int l = vid[head[v]];
        int r = vid[v] + 1;
        f(l, r);
        v = par[head[v]];
      } else {
        if (u != v) {
          int l = vid[u] + 1;
          int r = vid[v] + 1;
          f(l, r);
        }
        break;
      }
    }
  }

  int bel(int v) {
    if (never_hld)
      hld_build();
    return vid[v];
  }

  int bel(int f, int t) {
    if (never_hld)
      hld_build();
    return depth[f] > depth[t] ? vid[f] : vid[t];
  }

  int bel(edge<T> &e) {
    if (never_hld)
      hld_build();
    return depth[e.f] > depth[e.t] ? vid[e.f] : vid[e.t];
  }

  template <class... U> int operator()(U... args) { return bel(args...); }

  template <class S> void seg_add(S &seg, int lhei, int rhei, int v) {
    for_each_(lhei, rhei, [&](int l, int r) { seg.add(l, r, v); });
  }

  template <class S> void seg_update(S &seg, int lhei, int rhei, int v) {
    for_each_(lhei, rhei, [&](int l, int r) { seg.update(l, r, v); });
  }

  template <class S> int seg_get(S &seg, int lhei, int rhei) {
    int res = 0;
    for_each_(lhei, rhei, [&](int l, int r) { res += seg.get(l, r); });
    return res;
  }

  template <class S> void seg_add_edge(S &seg, int lhei, int rhei, int v) {
    for_each_edge(lhei, rhei, [&](int l, int r) { seg.add(l, r, v); });
  }

  template <class S> void seg_update_edge(S &seg, int lhei, int rhei, int v) {
    for_each_edge(lhei, rhei, [&](int l, int r) { seg.update(l, r, v); });
  }

  template <class S> int seg_get_edge(S &seg, int lhei, int rhei) {
    int res = 0;
    for_each_edge(lhei, rhei, [&](int l, int r) { res += seg.get(l, r); });
    return res;
  }

  template <class S> void seg_add_sub(S &seg, int i, int v) {
    if (never_hld)
      hld_build();
    seg.add(subl[i], subr[i], v);
  }

  template <class S> void seg_update_sub(S &seg, int i, int v) {
    if (never_hld)
      hld_build();
    seg.update(subl[i], subr[i], v);
  }

  template <class S> int seg_get_sub(S &seg, int i, int v) {
    if (never_hld)
      hld_build();
    return seg.get(subl[i], subr[i], v);
  }

  template <class S> void seg_add_sub_edge(S &seg, int i, int v) {
    if (never_hld)
      hld_build();
    seg.add(subl[i] + 1, subr[i], v);
  }

  template <class S> void seg_update_sub_edge(S &seg, int i, int v) {
    if (never_hld)
      hld_build();
    seg.update(subl[i] + 1, subr[i], v);
  }

  template <class S> int seg_get_sub_edge(S &seg, int i, int v) {
    if (never_hld)
      hld_build();
    return seg.get(subl[i] + 1, subr[i], v);
  }
};
