  static vvd(comb, 2020, 2020);
  if (comb[0][0] == 0) {
    comb[0][0] = 1;
    rep(i, 2000) {
      comb[i + 1][0] = 1;
      rep(j, 1, i + 2) { comb[i + 1][j] = comb[i][j] + comb[i][j - 1]; }
    }
  }
  return comb[n][r];
}

double comd(int n, int r) {
  if (r < 0 || r > n)
    return 0;
  if (n < 2020)
    return comd2(n, r);
  static vd fact(2, 1);
  if (sz(fact) <= n) {
    rep(i, sz(fact), n + 1) { fact.push_back(fact.back() * i); }
  }
  return fact[n] / fact[n - r] / fact[r];
}

