template <class T> vector<T> dijkstra_01(graph<T> &g, int s) {
  int N = g.n;
  vi dis(N, linf);
  dis[s] = 0;
  deque<int> q;
  q.push_back(s);
  vb was(N);
  while (!q.empty()) {
    int f = q.front();
    q.pop_front();
    if (was[f])
      continue;
    was[f] = true;
    fora(e, g[f]) {
      if (dis[e.t] > dis[f] + e.c) {
        if (e.c) {
          dis[e.t] = dis[f] + 1;
          q.push_back(e.t);
        } else {
          dis[e.t] = dis[f];
          q.push_front(e.t);
        }
      }
    }
  }
  return dis;
}

