  vector<T> res(g.n, linf);
  res[s] = 0;
  vb can(g.n);
  fix([&](auto ds, int p, int i) -> void {
    if (can[i])
      return;
    can[i] = true;
    forg(gi, g[i]) if (t != p) ds(i, t);
  })(-1, 0);
  vector<edge<T>> es;
  fora(e, g.edges) {
    if (can[e.f])
      es += e;
  }
  rep(i, g.n) {
    bool upd = false;
    fora(e, es) {
      if (res[e.f] != linf && res[e.t] > res[e.f] + e.c) {
        upd = true;
        res[e.t] = res[e.f] + e.c;
      }
    }
    if (!upd)
      break;
  }
  rep(i, g.n * 2) {
    bool upd = 0;
    fora(e, g.edges) {
      if (res[e.f] != linf && res[e.t] != -linf && res[e.t] > res[e.f] + e.c) {
        upd = 1;
        res[e.t] = -linf;
      }
    }
    if (!upd)
      break;
  }
  return res;
}

template <class T> vector<T> bell_far(graph<T> &g, int s) {
  if (g.n >= 1e4) {
    cout << "bell_far size too big" << endl;
    exit(0);
  }
  vector<T> res(g.n, linf);
  res[s] = 0;
  vb can(g.n);
  fix([&](auto ds, int p, int i) -> void {
    if (can[i])
      return;
    can[i] = true;
    forg(gi, g[i]) if (t != p) ds(i, t);
  })(-1, 0);
  vector<edge<T>> es;
  fora(e, g.edges) {
    if (can[e.f])
      es += e;
  }
  rep(i, g.n) {
    bool upd = false;
    fora(e, es) {
      if (res[e.f] != linf && res[e.t] > res[e.f] - e.c) {
        upd = true;
        res[e.t] = res[e.f] - e.c;
      }
    }
    if (!upd)
      break;
  }
  rep(i, g.n * 2) {
    bool upd = 0;
    fora(e, g.edges) {
      if (res[e.f] != linf && res[e.t] != -linf && res[e.t] > res[e.f] - e.c) {
        upd = 1;
        res[e.t] = -linf;
      }
    }
    if (!upd)
      break;
  }
  rep(i, g.n) res[i] *= -1;
  return res;
}

template <class T>
vector<vector<T>> warshall(const graph<T> &g, int init_value = -1) {
  int n = g.n;
  assert(n < 1e4);
  vector<vector<T>> dis(n, vector<T>(n, linf));
  rep(i, n) fora(e, g.g[i]) {
    if (dis[e.f][e.t] > e.c) {
      dis[e.f][e.t] = e.c;
    }
  }
  rep(i, n) dis[i][i] = 0;
  rep(k, n) rep(i, n) rep(j, n) {
    if (dis[i][j] > dis[i][k] + dis[k][j]) {
      dis[i][j] = dis[i][k] + dis[k][j];
    }
  }
  rep(i, n) rep(j, n) if (dis[i][j] == linf) dis[i][j] = init_value;
  return dis;
}

template <class T> class MinOp {
public:
  T operator()(T a, T b) { return min(a, b); }
};

template <typename OpFunc> struct SparseTable {
  OpFunc op;
  signed size;
  vector<signed> lg;
  vector<vector<pair<signed, signed>>> table;
  void init(const vector<pair<signed, signed>> &array, OpFunc opfunc) {
    signed n = array.size();
    op = opfunc;
    lg.assign(n + 1, 0);
    for (signed i = 1; i <= n; i++) {
      lg[i] = 31 - __builtin_clz(i);
    }
    table.assign(lg[n] + 1, array);
    for (signed i = 1; i <= lg[n]; i++) {
      for (signed j = 0; j < n; j++) {
        if (j + (1 << (i - 1)) < n) {
          table[i][j] = op(table[i - 1][j], table[i - 1][j + (1 << (i - 1))]);
        } else {
          table[i][j] = table[i - 1][j];
        }
      }
    }
  }
  pair<signed, signed> query(signed l, signed r) {
    assert(l < r);
    return op(table[lg[r - l]][l], table[lg[r - l]][r - (1 << lg[r - l])]);
  }
};

struct PMORMQ {
  vector<signed> a;
  SparseTable<MinOp<pair<signed, signed>>> sparse_table;
  vector<vector<vector<signed>>> lookup_table;
  vector<signed> block_type;
  signed block_size, n_block;
  void init(const vector<signed> &array) {
    a = array;
    signed n = a.size();
    block_size = std::max(1, (31 - __builtin_clz(n)) / 2);
    while (n % block_size != 0) {
      a.push_back(a.back() + 1);
      n++;
    }
    n_block = n / block_size;
    vector<pair<signed, signed>> b(n_block, make_pair(INT_MAX, INT_MAX));
    for (signed i = 0; i < n; i++) {
      b[i / block_size] = min(b[i / block_size], make_pair(a[i], i));
    }
    sparse_table.init(b, MinOp<pair<signed, signed>>());
    block_type.assign(n_block, 0);
    for (signed i = 0; i < n_block; i++) {
      signed cur = 0;
      for (signed j = 0; j < block_size - 1; j++) {
        signed ind = i * block_size + j;
        if (a[ind] < a[ind + 1]) {
          cur |= 1 << j;
        }
      }
      block_type[i] = cur;
    }
    lookup_table.assign(
        1 << (block_size - 1),
        vector<vector<signed>>(block_size, vector<signed>(block_size + 1)));
    for (signed i = 0; i < (1 << (block_size - 1)); i++) {
      for (signed j = 0; j < block_size; j++) {
        signed res = 0;
        signed cur = 0;
        signed pos = j;
        for (signed k = j + 1; k <= block_size; k++) {
          lookup_table[i][j][k] = pos;
          if (i & (1 << (k - 1))) {
            cur++;
          } else {
            cur--;
          }
          if (res > cur) {
            pos = k;
            res = cur;
          }
        }
      }
    }
  }
  signed query(signed l, signed r) {
    assert(l < r);
    signed lb = l / block_size;
    signed rb = r / block_size;
    if (lb == rb) {
      return lb * block_size +
             lookup_table[block_type[lb]][l % block_size][r % block_size];
    }
    signed pl = lb * block_size +
                lookup_table[block_type[lb]][l % block_size][block_size];
    signed pr =
        rb * block_size + lookup_table[block_type[rb]][0][r % block_size];
    signed pos = pl;
    if (r % block_size > 0 && a[pl] > a[pr]) {
      pos = pr;
    }
    if (lb + 1 == rb) {
      return pos;
    }
    signed spv = sparse_table.query(lb + 1, rb).second;
    if (a[pos] > a[spv]) {
      return spv;
    }
    return pos;
  }
};

template <class T = int> class tree : public undigraph<T> {
  PMORMQ rmq;
  int cnt;
  vector<signed> id, in;
  bool never = true;
  bool never_hld = true;
  void dfs(int x, int p, int d, int dis = 0) {
    id[cnt] = x;
    par[x] = p;
    rmq_dep.push_back(d);
    disv[x] = dis;
    in[x] = cnt++;
    forg(gi, g[x]) {
      if (t == p) {
        continue;
      }
      dfs(t, x, d + 1, dis + c);
      id[cnt] = x;
      rmq_dep.push_back(d);
      cnt++;
    }
  }
  void precalc() {
    never = false;
    cnt = 0;
    rmq_dep.clear();
    disv.assign(n, 0);
    in.assign(n, -1);
    id.assign(2 * n - 1, -1);
    par.assign(n, -1);
    dfs(root, -1, 0);
    rmq.init(rmq_dep);

#ifdef _DEBUG

    if (n >= 100)
      return;
    cerr << "---tree---" << endl;
    rep(i, n) {
      if (!(i == root || sz(g[i]) > 1))
        continue;
      cerr << i << " -> ";
      vi ts;
      forg(gi, g[i]) {
        if (t != par[i])
          ts.push_back(t);
      }
      rep(i, sz(ts) - 1) cerr << ts[i] << ", ";
      if (sz(ts))
        cerr << ts.back() << endl;
    }
    cerr << endl;

#endif
  }
  int pos;
  void hld_build() {
    never_hld = false;
    if (never)
      precalc();
    g.resize(n);
    vid.resize(n, -1);
    head.resize(n);
    heavy.resize(n, -1);
    depth.resize(n);
    inv.resize(n);
    subl.resize(n);
    subr.resize(n);
    dfs(root, -1);
    t = 0;
    dfs_hld(root);

#ifdef _DEBUG

    if (n >= 100)
      return;
    cerr << "---hld_index---" << endl;
    vi inds;
    rep(i, n) if (sz(g[i])) inds.push_back(i);
    rep(i, sz(inds)) {
      str s = tos(bel(inds[i]));
      cerr << std::right << std::setw(sz(s) + (i ? 1 : 0)) << inds[i];
    }
    cerr << endl;
    rep(i, sz(inds)) { cerr << bel(inds[i]) << " "; }
    cerr << endl << endl;
    cerr << "---hld_edge_index---" << endl;
    fora(e, edges) {
      if (e.f <= e.t)
        cerr << e.f << "-" << e.t << " " << bel(e) << endl;
    }
    cerr << endl << endl;
    cerr << "!!edge or not edge carefull!!" << endl;
    cerr << "!!if(f<t) seg.add(bel(f,t),c) carefully(f,t) (t,f)!!" << endl;

#endif
  }
  int dfs(int curr, int prev) {
    int sub = 1, max_sub = 0;
    heavy[curr] = -1;
    forg(i, g[curr]) {
      int next = t;
      if (next != prev) {
        depth[next] = depth[curr] + 1;
        int sub_next = dfs(next, curr);
        sub += sub_next;
        if (max_sub < sub_next)
          max_sub = sub_next, heavy[curr] = next;
      }
    }
    return sub;
  }
  int t = 0;
  void dfs_hld(int v = 0) {
    vid[v] = subl[v] = t;
    t++;
    inv[subl[v]] = v;
    if (0 <= heavy[v]) {
      head[heavy[v]] = head[v];
      dfs_hld(heavy[v]);
    }
    forg(i, g[v]) if (depth[v] < depth[t]) if (t != heavy[v]) {
      head[t] = t;
      dfs_hld(t);
    }
    subr[v] = t;
  }
  vector<signed> rmq_dep;

public:
  using undigraph<T>::g;
  using undigraph<T>::n;
  using undigraph<T>::edges;
  using undigraph<T>::usedv;

  vector<int> disv;

  vector<int> vid, head, heavy, par, depth, inv, subl, subr;

  int root;

  tree(int n_, int root = 0) : undigraph<T>(n_), root(root) { n = n_; }

  int lca(int a, int b) {
    if (never)
      precalc();
    int x = in[a];
    int y = in[b];
    if (x > y) {
      swap(x, y);
    }
    int pos = rmq.query(x, y + 1);
    return id[pos];
  }

  int dis(int a, int b) {
    if (never)
      precalc();
    int x = in[a];
    int y = in[b];
    if (x > y) {
      swap(x, y);
    }
    int pos = rmq.query(x, y + 1);
    int p = id[pos];
    return disv[a] + disv[b] - disv[p] * 2;
  }

  void for_each_l(int u, int v, function<void(int)> fnode) {
    int r = lca(u, v);
    while (u != r) {
      fnode(u);
      u = par[u];
    }
    while (v != r) {
      fnode(v);
      v = par[v];
    }
    fnode(r);
  }

  void for_each_edge_l(int u, int v, function<void(edge<int> &)> fedge) {
    int r = lca(u, v);
    auto sub = [&](int u, int r) {
      while (u != r) {
        forg(gi, g[u]) {
          if (t == par[u]) {
            fedge(g[u][gi]);
            u = par[u];
            break;
          }
        }
      }
    };
    sub(u, r);
    sub(v, r);
  }

  void for_each_(int u, int v, const function<void(int, int)> &f) {
    if (never_hld)
      hld_build();
    while (1) {
      if (vid[u] > vid[v])
        swap(u, v);
      int l = max(vid[head[v]], vid[u]);
      int r = vid[v] + 1;
      f(l, r);
      if (head[u] != head[v])
        v = par[head[v]];
      else
        break;
    }
  }

  void for_each_edge(int u, int v, const function<void(int, int)> &f) {
    if (never_hld)
      hld_build();
    while (1) {
      if (vid[u] > vid[v])
        swap(u, v);
      if (head[u] != head[v]) {
        int l = vid[head[v]];
        int r = vid[v] + 1;
        f(l, r);
        v = par[head[v]];
      } else {
        if (u != v) {
          int l = vid[u] + 1;
          int r = vid[v] + 1;
          f(l, r);
        }
        break;
      }
    }
  }

  int bel(int v) {
    if (never_hld)
      hld_build();
    return vid[v];
  }

  int bel(int f, int t) {
    if (never_hld)
      hld_build();
    return depth[f] > depth[t] ? vid[f] : vid[t];
  }

  int bel(edge<T> &e) {
    if (never_hld)
      hld_build();
    return depth[e.f] > depth[e.t] ? vid[e.f] : vid[e.t];
  }

  template <class... U> int operator()(U... args) { return bel(args...); }

  template <class S> void seg_add(S &seg, int lhei, int rhei, int v) {
    for_each_(lhei, rhei, [&](int l, int r) { seg.add(l, r, v); });
  }

  template <class S> void seg_update(S &seg, int lhei, int rhei, int v) {
    for_each_(lhei, rhei, [&](int l, int r) { seg.update(l, r, v); });
  }

  template <class S> int seg_get(S &seg, int lhei, int rhei) {
    int res = 0;
    for_each_(lhei, rhei, [&](int l, int r) { res += seg.get(l, r); });
    return res;
  }

  template <class S> void seg_add_edge(S &seg, int lhei, int rhei, int v) {
    for_each_edge(lhei, rhei, [&](int l, int r) { seg.add(l, r, v); });
  }

  template <class S> void seg_update_edge(S &seg, int lhei, int rhei, int v) {
    for_each_edge(lhei, rhei, [&](int l, int r) { seg.update(l, r, v); });
  }

  template <class S> int seg_get_edge(S &seg, int lhei, int rhei) {
    int res = 0;
    for_each_edge(lhei, rhei, [&](int l, int r) { res += seg.get(l, r); });
    return res;
  }

  template <class S> void seg_add_sub(S &seg, int i, int v) {
    if (never_hld)
      hld_build();
    seg.add(subl[i], subr[i], v);
  }

  template <class S> void seg_update_sub(S &seg, int i, int v) {
    if (never_hld)
      hld_build();
    seg.update(subl[i], subr[i], v);
  }

  template <class S> int seg_get_sub(S &seg, int i, int v) {
    if (never_hld)
      hld_build();
    return seg.get(subl[i], subr[i], v);
  }

  template <class S> void seg_add_sub_edge(S &seg, int i, int v) {
    if (never_hld)
      hld_build();
    seg.add(subl[i] + 1, subr[i], v);
  }

  template <class S> void seg_update_sub_edge(S &seg, int i, int v) {
    if (never_hld)
      hld_build();
    seg.update(subl[i] + 1, subr[i], v);
  }

  template <class S> int seg_get_sub_edge(S &seg, int i, int v) {
    if (never_hld)
      hld_build();
    return seg.get(subl[i] + 1, subr[i], v);
  }
};
;

template <class T = int> class grid_k6 : public undigraph<T> {
public:
  using undigraph<T>::g;
  using undigraph<T>::n;
  using undigraph<T>::edges;
  using undigraph<T>::usedv;
  int H, W;
  int eid = 0;
  vector<vector<char>> ba;
  vi costs;
  char wall;
  void add(int f, int t, T c = 1, int ty = -1, int id = -1) {
    if (!(0 <= f && f < n && 0 <= t && t < n)) {
      debugline("grid_k6 add");
      deb(f, t, c, ty, id);
      ole();
    }
    g[f].emplace_back(f, t, c, ty, eid++);
    g[t].emplace_back(t, f, c, ty, eid++);
  }
  int getid(int h, int w) {
    assert(ins(h, w, H, W));
    return W * h + w;
  }
  int getid(P p) { return getid(p.first, p.second); }
  P get2(int id) { return mp(id / W, id % W); }
  P operator()(int id) { return get2(id); }
  int operator()(int h, int w) { return getid(h, w); }
  int operator()(P p) { return getid(p); }
  grid_k6(int H, int W) : H(H), W(W), undigraph<T>(H * W) {
    rep(h, H) {
      rep(w, W) {
        int f = getid(h, w);
        if (w + 1 < W)
          add(f, getid(h, w + 1));
        if (h + 1 < H)
          add(f, getid(h + 1, w));
      }
    }
  }
  grid_k6(vector<vector<char>> ba, char wall = '#')
      : H(sz(ba)), W(sz(ba[0])), undigraph<T>(sz(ba) * sz(ba[0])) {
    rep(h, H) {
      rep(w, W) {
        if (ba[h][w] == wall)
          con;
        int f = getid(h, w);
        if (w + 1 < W && ba[h][w + 1] != wall) {
          add(f, getid(h, w + 1));
        }
        if (h + 1 < H && ba[h + 1][w] != wall) {
          add(f, getid(h + 1, w));
        }
      }
    }
  }
  grid_k6(vector<vector<char>> ba, int oo, int ox, int xo, int xx,
          char wall = '#')
      : H(sz(ba)), W(sz(ba[0])), undigraph<T>(sz(ba) * sz(ba[0])),
        costs({oo, ox, xo, xx}), ba(ba), wall(wall) {
    rep(h, H) {
      rep(w, W) {
        add2(h, w, h + 1, w);
        add2(h, w, h - 1, w);
        add2(h, w, h, w + 1);
        add2(h, w, h, w - 1);
      }
    }
  }
  void add2(int fh, int fw, int th, int tw) {
    if (ins(fh, fw, H, W) && ins(th, tw, H, W)) {
      int cm = 0;
      if (ba[fh][fw] == wall) {
        cm += 2;
      }
      if (ba[th][tw] == wall) {
        cm++;
      }
      int f = getid(fh, fw);
      int t = getid(th, tw);
      g[f].emplace_back(f, t, costs[cm], -1, eid++);
    }
  }
  void set_edges() {
    rep(i, n) fora(e, g[i]) if (e.f < e.t) edges.push_back(e);
  }
};

template <class T = int> class digrid_k6 : public digraph<T> {
public:
  using digraph<T>::g;
  using digraph<T>::n;
  using digraph<T>::edges;
  using digraph<T>::usedv;
  int H, W;
  int eid = 0;
  void add(int f, int t, T c = 1, int ty = -1, int id = -1) {
    if (!(0 <= f && f < n && 0 <= t && t < n)) {
      debugline("digrid_k6 add");
      deb(f, t, c, ty, id);
      ole();
    }
    g[f].emplace_back(f, t, c, ty, eid++);
  }
  int getid(int h, int w) {
    if (!ins(h, w, H, W))
      return -1;
    return W * h + w;
  }
  P get2(int id) { return mp(id / W, id % W); }
  P operator()(int id) { return get2(id); }
  int operator()(int h, int w) { return getid(h, w); }
  digrid_k6(int H, int W) : H(H), W(W), digraph<T>(H * W) {
    rep(h, H) {
      rep(w, W) {
        int f = getid(h, w);
        if (w + 1 < W)
          add(f, getid(h, w + 1));
        if (h + 1 < H)
          add(f, getid(h + 1, w));
      }
    }
  }
  digrid_k6(vector<vector<char>> ba, char wall = '#')
      : H(sz(ba)), W(sz(ba[0])), digraph<T>(sz(ba) * sz(ba[0])) {
    rep(h, H) {
      rep(w, W) {
        if (ba[h][w] == wall)
          con;
        int f = getid(h, w);
        if (w + 1 < W && ba[h][w + 1] != wall) {
          add(f, getid(h, w + 1));
        }
        if (h + 1 < H && ba[h + 1][w] != wall) {
          add(f, getid(h + 1, w));
        }
      }
    }
  }
  void add(int fh, int fw, int th, int tw) {
    add(getid(fh, fw), getid(th, tw));
  }
  void set_edges() { rep(i, n) fora(e, g[i]) edges.push_back(e); }
};

