  stringstream ss;

  ss << endl;

  if (key == -1)
    ss << " *|";
  else
    ss << " " << key << "|";

  rep(w, W) ss << std::right << std::setw(4) << w;

  ss << "" << endl;

  rep(w, W * 4 + 3) ss << "_";

  ss << "" << endl;

  rep(h, H) {

