template <class T> vector<T> bell(graph<T> &g, int s) {
  if (g.n >= 1e4) {
    cout << "bell size too big" << endl;
    exit(0);
  }
  vector<T> res(g.n, linf);
  res[s] = 0;
  vb can(g.n);
  fix([&](auto ds, int p, int i) -> void {
    if (can[i])
      return;
    can[i] = true;
    forg(gi, g[i]) if (t != p) ds(i, t);
  })(-1, 0);
  vector<edge<T>> es;
  fora(e, g.edges) {
    if (can[e.f])
      es += e;
  }
  rep(i, g.n) {
    bool upd = false;
    fora(e, es) {
      if (res[e.f] != linf && res[e.t] > res[e.f] + e.c) {
        upd = true;
        res[e.t] = res[e.f] + e.c;
      }
    }
    if (!upd)
      break;
  }
  rep(i, g.n * 2) {
    bool upd = 0;
    fora(e, g.edges) {
      if (res[e.f] != linf && res[e.t] != -linf && res[e.t] > res[e.f] + e.c) {
        upd = 1;
        res[e.t] = -linf;
      }
    }
    if (!upd)
      break;
  }
  return res;
}

