  })(-1, 0);
  vector<edge<T>> es;
  fora(e, g.edges) {
    if (can[e.f])
      es += e;
  }
  rep(i, g.n) {
    bool upd = false;
    fora(e, es) {
      if (res[e.f] != linf && res[e.t] > res[e.f] - e.c) {
        upd = true;
        res[e.t] = res[e.f] - e.c;
      }
    }
    if (!upd)
      break;
  }
  rep(i, g.n * 2) {
