vi diameters(undigraph<> &E) {
  vi D[3];
  D[0].resize(E.size());
  D[1].resize(E.size());
  auto v1 = farthest(E, 0, 0, 0, D[0]);
  auto v2 = farthest(E, v1.second, v1.second, 0, D[0]);
  farthest(E, v2.second, v2.second, 0, D[1]);
  int i;
  rep(i, D[0].size()) D[2].push_back(max(D[0][i], D[1][i]));
  return D[2];
}

int diameter(undigraph<> &E) {
  vi d = diameters(E);
  return max(d);
}

vp diameter_p(undigraph<> &E) {
  vector<int> D[3];
  D[0].resize(E.size());
  D[1].resize(E.size());
  auto v1 = farthest(E, 0, 0, 0, D[0]);
  auto v2 = farthest(E, v1.second, v1.second, 0, D[0]);
  farthest(E, v2.second, v2.second, 0, D[1]);
  int i;
  vp res(E.size());
  rep(i, D[0].size()) {
    if (D[0][i] > D[1][i])
      res[i] = mp(D[0][i], v1.second);
    else
      res[i] = mp(D[1][i], v2.second);
  }
  return res;
}

template <class T> int longest_path(digraph<T> &g) {
  vi top;
  if (!topo(top, g)) {
    return linf;
  }
  int n = sz(top);
  vi dp(n, 0);
  for (auto &&i : top) {
    forg(gi, g[i]) { chma(dp[t], dp[i] + 1); }
  }
  return max(dp);
}

template <class T> vi longest_path_v(digraph<T> &g) {
  vi top;
  if (!topo(top, g)) {
    return vi();
  }
  int n = sz(top);
  vi dp(n, 0);
  vi pre(n, -1);
  for (auto &&i : top) {
    forg(gi, g[i]) {
      if (chma(dp[t], dp[i] + 1)) {
        pre[t] = i;
      }
    }
  }
  int s = std::max_element(dp.begin(), dp.end()) - dp.begin();
  vi path;
  while (s != -1) {
    path.push_back(s);
    s = pre[s];
  }
  std::reverse(path.begin(), path.end());
  return path;
}

template <class T> vp bridge(graph<T> &G) {
  static bool was;
  vp brid;
  vi articulation;
  vi ord(G.n), low(G.n);
  vb vis(G.n);
  function<void(int, int, int)> dfs = [&](int v, int p, int k) {
