  static ifstream ina;
  static int rem;
  static vp edges;
  static int pk = -1;
  if (pk != k) {
    if (~pk)
      ina.close();
    edges.clear();
    pk = k;
    name = (k == 6) ? "C:\\Users\\kaout\\Desktop\\trees_sizek\\nazeka6.txt"
                    : "C:\\Users\\kaout\\Desktop\\trees_sizek\\tree_size" +
                          tos(k) + ".txt";
    ina = ifstream(name);
    rem = pow(k, k - 2);
    rep(i, k) rep(j, i + 1, k) edges.emplace_back(i, j);
    pk = k;
  }
  tree<int> g(k);
  if (rem == 0) {
    g.resize(0);
    return g;
  }
  int m;
  ina >> m;
  while (m) {
    int lb = lbit(m);
    int id = log2(lb);
    g.add(edges[id].first, edges[id].second);
    m ^= lb;
  }
  rem--;
  return g;
}

