  int v;

  ll m[2];

  Edge(int a, int b, int c) { v = a, m[0] = b, m[1] = c; }
};

vector<Edge> G[Maxn + 5];

void AddEdge(int u, int v, int x, int y) {

  G[u].push_back(Edge(v, x, y));

  G[v].push_back(Edge(u, x, y));
}

ll dist[2][Maxn + 5];

bool vis[Maxn + 5];

void SPFA(int s, int ty) {

  queue<int> q;

  memset(vis, 0, sizeof vis);

  memset(dist[ty], 0x3f, sizeof dist[ty]);

  q.push(s);

  vis[s] = true;
  dist[ty][s] = 0;

  while (!q.empty()) {

    int u = q.front();

    q.pop();
    vis[u] = false;

    for (int i = 0; i < G[u].size(); i++) {

      int v = G[u][i].v, w = G[u][i].m[ty];

      if (dist[ty][v] > dist[ty][u] + w) {

        dist[ty][v] = dist[ty][u] + w;

        if (!vis[v]) {

          vis[v] = true;

          q.push(v);
        }
      }
    }
  }
}

int N, M, S, T;

ll ans[Maxn + 5];

