#include <iostream>

#include <stdio.h>

#include <string.h>

#include <math.h>

#include <queue>

#include <algorithm>

#define N 200500

#define LL long long

#define mem(a, b) memset(a, b, sizeof(a));

using namespace std;

LL sum[N], t[N];

LL tree[N];

int n, k, a, m, nn;

void add(int x)

{

  while (x <= nn)

  {

    tree[x]++;

    x += x & -x;
  }
}

LL query(int x)

{

  LL num = 0;

  while (x)

  {

    num += tree[x];

    x -= x & -x;
  }

  return num;
}

int main()

{

  mem(t, 0);

  mem(tree, 0);

  mem(sum, 0);

  scanf("%d%d", &n, &k);

  nn = n + 10;

  for (int i = 1; i <= n; i++)

  {

    scanf("%d", &a);

    t[i] = sum[i] = sum[i - 1] + a - k;
  }

  sort(t, t + n + 1);

  m = unique(t, t + n + 1) - t;

  for (int i = 0; i <= n; i++)

    sum[i] = lower_bound(t, t + m + 1, sum[i]) - t + 1;

  LL ans = 0;

  for (int i = 0; i <= n; i++)

  {

    ans += query(sum[i]);

    add(sum[i]);
  }

  printf("%lld\n", ans);
}

