  int SPF[1000001], Primes[168], sz;
} Template;

Template P;

static inline void ready(void)

{

  *P.SPF = 1, *P.Primes = 2, P.sz = 1;

  rep(i, MAX / 2) P.SPF[2 * (i + 1)] = 2,
                                 P.SPF[2 * (i + 1) - 1] = 2 * (i + 1) - 1;

  rep(i, MAX / 2 - 1)

  {

    int x = 2 * (i + 1) + 1;
    if (P.SPF[x] == x) {
      P.Primes[P.sz++] = x;
    }
    if (x * x > MAX)
      break;

    rep(j, P.sz) {
      if (P.Primes[j] <= P.SPF[x] && x * P.Primes[j] <= MAX)
        P.SPF[x * P.Primes[j]] = P.Primes[j];
      else
