        return 0;
    }

    esc[vol][0] = P.Primes[i], esc[vol++][1] = 1;

    while (x % P.Primes[i] == 0) {
      x /= P.Primes[i];
    }
  }

  if (x != 1)

  {

    rep(j, vol) {
      if (esc[j][0] == x && esc[j][1])
        return 0;
