struct edge

{

  int to;

  ll cost;

  edge(int to = 0, ll cost = 0) : to(to), cost(cost) {}
};

struct UF

{

  int par[SIZE], rank[SIZE];

  void init(int n)

  {

    for (int i = 0; i < n; i++)

    {

      par[i] = i;

      rank[i] = 0;
    }
  }

  int find(int x)

  {

    if (par[x] == x)
      return x;

    return par[x] = find(par[x]);
  }

  void unite(int x, int y)

  {

    x = find(x);

    y = find(y);

    if (x == y)
      return;

    if (rank[x] < rank[y])
      par[x] = y;

    else

    {

      par[y] = x;

      if (rank[x] == rank[y])
        rank[x]++;
    }
  }

  bool same(int x, int y)

  {

    return find(x) == find(y);
  }
};

UF uf;

vector<edge> vec[SIZE];

ll X[SIZE];

int v1[SIZE], v2[SIZE];

ll d1[SIZE], d2[SIZE];

int id[SIZE], ch[SIZE];

int now_id;

void dfs(int v = 0, int p = -1)

{

  id[v] = now_id++;

  d1[v] = d2[v] = INF;

  v1[v] = v2[v] = -1;

  for (int i = 0; i < vec[v].size(); i++)

  {

    edge e = vec[v][i];

    if (e.to != p)

    {

      dfs(e.to, v);

      ll vl = d1[e.to] + e.cost;

      int vv = v1[e.to];

      if (vl > e.cost + X[e.to])

      {

        vl = e.cost + X[e.to];

        vv = e.to;
      }

      if (vl < d1[v])

      {

        swap(vl, d1[v]);

        swap(vv, v1[v]);
      }
    }
  }

  ch[v] = now_id;
}

void make(int v = 0, int p = -1)

{

  for (int i = 0; i < vec[v].size(); i++)

  {

    edge e = vec[v][i];

    if (e.to != p)

    {

      ll vl = d1[v] + e.cost;

      int vv = v1[v];

      if (id[e.to] <= id[vv] && id[vv] < ch[e.to])

      {

        vl = d2[v] + e.cost;

        vv = v2[v];
      }

      if (vl > e.cost + X[v])

      {

        vl = e.cost + X[v];

        vv = v;
      }

