    return;
  }

  v = ++tot;

  int mid = l + r >> 1;

  build(le[v], l, mid, flag);

  build(ri[v], mid + 1, r, flag);

  add(v, le[v]);
  add(v, ri[v]);
}

void link(int v, int l, int r, int x, int y, int z) {

  if (x > y)
    return;

  if (l == x && r == y) {
    add(z, v);
    return;
  }

  int mid = l + r >> 1;

  if (y <= mid)
    link(le[v], l, mid, x, y, z);

  else if (x > mid)
    link(ri[v], mid + 1, r, x, y, z);

  else
    link(le[v], l, mid, x, mid, z), link(ri[v], mid + 1, r, mid + 1, y, z);
}

