    u = gi(), v = gi(), w = gi(), s[u] ^= w, s[v] ^= w;

  for (int i = 0; i < n; i++)

    cnt[s[i]]++;

  int now = 0;

  for (int i = 1; i < 16; i++)

    ans += cnt[i] / 2, now += ((cnt[i] & 1) << i - 1);

  memset(f, 127, sizeof(f));
  f[now] = 0;

  for (int i = (1 << 15) - 1; i; i--)

    if (f[i] < 2000000000)

    {

