    {

      scanf("%d", &p[i]);

      a[p[i]] = i;
    }

    for (int i = 1; i < n; i++)

      if (a[i] < a[i + 1])

        g[a[i]].push_back(a[i + 1]);

    memset(dp, 0, sizeof dp);

    int ma = -1;

