ll r[9], a[100000], b[100000], c[100000];

ll cutg[10][10];

struct edge {

  ll to, cost;
};

int V, E;

vector<edge> g[100000];

ll d[210];

void dijkstra(int s) {

  priority_queue<pi, vector<pi>, greater<pi>> q;

  for (int i = 0; i < V; i++)
    d[i] = INF;

  d[s] = 0;

  q.push(pi(0, s));

  while (!q.empty()) {

    pi p = q.top();
    q.pop();

    int w = p.second;

    if (d[w] < p.first)
      continue;

    for (int i = 0; i < g[w].size(); i++) {

      int t = g[w][i].to;

      ll c = g[w][i].cost;

      if (d[t] > d[w] + c) {

        d[t] = d[w] + c;

        q.push(pi(d[t], t));
      }
    }
  }
}

ll dp[1 << 10][10];

ll rec(int S, int v, int go) {

  if (dp[S][v] >= 0)
    return dp[S][v];

  if (S == (1 << R) - 1 && v == go)
    return dp[S][v] = 0;

  ll res = 1e+12;

  rep(u, R) {

    if (!(S >> u & 1)) {

      res = min(res, rec(S | 1 << u, u, go) + cutg[v][u]);
    }
  }

  return dp[S][v] = res;
}

