    rep(j, R) { cutg[i][j] = d[r[j] - 1]; }
  }

  ll res = 1e+12;

  rep(i, R) {

    rep(j, R) {

      memset(dp, -1, sizeof(dp));

      res = min(res, rec(1 << i, i, j));
    }
  }

  prin(res);

  return 0;
}

