    p->to = v, p->cap = c, p->flow = 0, p->cost = w;

    p->nxt = adj[u], adj[u] = p;

    q->to = u, q->cap = 0, q->flow = 0, q->cost = -w;

    q->nxt = adj[v], adj[v] = q;

    p->rev = q, q->rev = p;
  }

  int s, t;

