  ll f[MAXV + 5];

  void update(int x, ll k) {

    f[x] = k;

    while (x) {

      hp[x] = x;

      if ((x << 1) <= t && f[hp[x << 1]] < f[hp[x]])

        hp[x] = hp[x << 1];

      if ((x << 1 | 1) <= t && f[hp[x << 1 | 1]] < f[hp[x]])

        hp[x] = hp[x << 1 | 1];

      x >>= 1;
    }
  }

  ll d[MAXV + 5], h[MAXV + 5];

