      for (edge *p = adj[x]; p; p = p->nxt) {

        ll dis = d[x] + p->cost + (h[x] - h[p->to]);

        if (p->cap > p->flow && dis < d[p->to])

          update(p->to, d[p->to] = dis);
      }
    }

    return !(d[t] == inf);
  }

  bool vis[MAXV + 5];

  int aug(int x, int tot) {

    if (x == t)
      return tot;

