    vis[x] = true;

    for (edge *&p = cur[x]; p; p = p->nxt) {

      ll dis = d[x] + p->cost + (h[x] - h[p->to]);

      if (!vis[p->to] && p->cap > p->flow && dis == d[p->to]) {

