template <class T>

class Imos {

private:
  int N;

  vector<T> data;

public:
  Imos(int _N) : N(_N) { reset(); }

  void reset() { data = vector<T>(N + 1, T{}); }

  void add(int l, int r, T d) {

    data[l] += d;

    data[r + 1] -= d;
  }

  void build() {

    for (int i = 0; i < N; i++)
      data[i + 1] += data[i];
  }

  T get(T pos) { return data[pos]; }

  T &operator[](int n) { return data[n]; }

  void show() {

    for (int i = 0; i < N + 1; i++) {

      printf("%5d ", data[i]);
    }

    printf("\n");
  }
};

template <int_fast64_t Modulas = 1000000007ul>

class ModInt {

  using u64 = int_fast64_t;

public:
  u64 x;

  constexpr ModInt() : x(0) {}

  constexpr ModInt(int_fast64_t v) : x((v % Modulas + Modulas) % Modulas) {}

  constexpr ModInt operator+(const ModInt rhs) const noexcept {

    return ModInt(*this) += rhs;
  }

  constexpr ModInt operator-(const ModInt rhs) const noexcept {

    return ModInt(*this) -= rhs;
  }

  constexpr ModInt operator*(const ModInt rhs) const noexcept {

    return ModInt(*this) *= rhs;
  }

  constexpr ModInt operator/(const ModInt rhs) const noexcept {

    return ModInt(*this) /= rhs;
  }

  constexpr ModInt operator/(const long long rhs) const noexcept {

    return ModInt(*this) /= rhs;
  }

  constexpr ModInt operator+=(const ModInt rhs) noexcept {

    x += rhs.x;

    if (x >= Modulas)
      x -= Modulas;

    return *this;
  }

  constexpr ModInt operator+=(const long long rhs) noexcept {

    auto hs = ModInt<Modulas>(rhs);

    (*this) += hs;

    return *this;
  }

  constexpr ModInt operator-=(const ModInt rhs) noexcept {

    if (x < rhs.x)
      x += Modulas;

    x -= rhs.x;

    return *this;
  }

  constexpr ModInt operator-=(const long long rhs) noexcept {

    auto hs = ModInt<Modulas>(rhs);

    (*this) -= hs;

    return *this;
  }

  constexpr ModInt operator*=(const ModInt rhs) noexcept {

    x = x * rhs.x % Modulas;

    return *this;
  }

  constexpr ModInt operator*=(const long long rhs) noexcept {

    auto hs = ModInt<Modulas>(rhs);

    (*this) *= hs;

    return *this;
  }

  constexpr ModInt &operator/=(ModInt rhs) noexcept {

    u64 exp = Modulas - 2;

    while (exp > 0) {

      if (exp & 1ul)
        *this *= rhs;

      rhs *= rhs;

      exp >>= 1ul;
    }

    return *this;
  }

  constexpr ModInt &operator/=(long long rhs) noexcept {

    auto hs = ModInt<Modulas>(rhs);

    (*this) /= hs;

    return *this;
  }

  constexpr ModInt &operator++() noexcept {

    x++;

    if (x >= Modulas)
      x -= Modulas;

    return *this;
  }

  constexpr ModInt &operator--() noexcept {

    if (x == 0)
      x += Modulas;

    x--;

    return *this;
  }

  constexpr bool operator<(const ModInt rhs) const noexcept {

    return x < rhs.x;
  }

  constexpr bool operator==(const ModInt rhs) const noexcept {

    return this->x == rhs.x;
  }

  constexpr bool operator!=(const ModInt rhs) const noexcept {

    return !(*this == rhs);
  }

  friend istream &operator>>(istream &in, ModInt &m) {

    in >> m.x;

    if (m.x < 0)
      m.x += Modulas;

    m.x %= Modulas;

    return in;
  }

  friend ostream &operator<<(ostream &out, const ModInt &p) {

    out << p.x;

    return out;
  }

  constexpr ModInt pow(u64 p) const {

    ModInt ret(1);

    ModInt mul(x);

    while (p > 0) {

      if (p & 1ul)
        ret *= mul;

      mul *= mul;

      p >>= 1ul;
    }

    return ret;
  }

  constexpr ModInt operator~() const noexcept {

    u64 exp = Modulas - 2;

    return pow(exp);
  }

  constexpr static ModInt arith_sum(ModInt<Modulas> a, ModInt<Modulas> d,
                                    ModInt<Modulas> n) noexcept {

    return (a * ModInt<Modulas>(2) + (n - 1) * d) * n / ModInt<Modulas>(2);
  }
};

constexpr int MAX = 2020;

int main() {

  int S;

  cin >> S;

  vector<vector<ModInt<>>> dp(MAX + 1, vector<ModInt<>>(S + 1, 0));

  dp[0][0] = 1;

  ModInt<> ans = 0;

  for (int i = 0; i < MAX; i++) {

    Imos<ModInt<>> imos(S + 1);

    for (int j = 0; j <= S; j++) {

      int f = j + 3;

      if (f <= S) {

        imos.add(f, S, dp[i][j]);
      }
    }

    imos.build();

    for (int j = 0; j <= S; j++)
      dp[i + 1][j] = imos[j];

    ans += dp[i + 1][S];
  }

  cout << ans << endl;
}

