  k++;

  while (k < 300000) {

    bit[k] += x;

    k += k & -k;
  }
}

int sum(int k) {

  k++;

  int ans = 0;

  while (k) {

    ans += bit[k];

    k -= k & -k;
  }

  return ans;
}

