  priority_queue<P, vector<P>, greater<P>> que;

  fill(d, d + V, INF);

  d[s] = 0;

  que.push(P(0, s));

  while (!que.empty()) {

    P p = que.top();

    que.pop();

    int v = p.second;

    if (d[v] < p.first)
