#include <bits/stdc++.h>

using namespace std;

const int N = 2e5 + 10;

typedef long long ll;

int gi() {

  int x = 0, o = 1;
  char ch = getchar();

  while ((ch < '0' || ch > '9') && ch != '-')
    ch = getchar();

  if (ch == '-')
    o = -1, ch = getchar();

  while (ch >= '0' && ch <= '9')
    x = x * 10 + ch - '0', ch = getchar();

  return x * o;
}

struct edge {
  int to, w, nxt;
} e[N << 1];

int tot = 1, h[N];

void adde(int u, int v) {

  e[++tot] = (edge){v, 1, h[u]};
  h[u] = tot;

  e[++tot] = (edge){u, -1, h[v]};
  h[v] = tot;
}

int n, m, V, E, col[N], cnt[3];

bool vis[N], vise[N];

ll ans = 0;

bool flag = 0;

void dfs(int u) {

  V++;
  vis[u] = 1;

  cnt[col[u]]++;

  for (int i = h[u]; i; i = e[i].nxt) {

    if (vise[i >> 1])
      continue;
    vise[i >> 1] = 1, E++;

    int v = e[i].to;

    if (!vis[v])
      col[v] = (col[u] + e[i].w + 3) % 3, dfs(v);

    else if (col[v] != (col[u] + e[i].w + 3) % 3)
      flag = 1;
  }
}

int main() {

  cin >> n >> m;

  for (int i = 1, u, v; i <= m; i++)
    u = gi(), v = gi(), adde(u, v);

  for (int i = 1; i <= n; i++)

    if (!vis[i]) {

      V = E = cnt[0] = cnt[1] = cnt[2] = 0;
      flag = 0;
      dfs(i);

      if (flag)
        ans += 1ll * V * V;

      else if (!cnt[0] || !cnt[1] || !cnt[2])
        ans += E;

      else
        ans += 1ll * cnt[0] * cnt[1] + 1ll * cnt[1] * cnt[2] +
               1ll * cnt[2] * cnt[0];
    }

  printf("%lld\n", ans);

  return 0;
}

