void dfs(int r, int c)

{

  stack<int> S;

  S.push(r);

  color[r] = c;

  while (!S.empty())

  {

    int u = S.top();
    S.pop();

    for (int i = 0; i < G[u].size(); i++)

    {

      int v = G[u][i];

      if (color[v] == NIL)

      {

        color[v] = c;

        S.push(v);
      }
    }
  }
}

void dfs_(int r, int c)

{

  color[r] = c;

  for (int i = 0; i < G[r].size(); i++)

  {

    int v = G[r][i];

    if (color[v] == NIL)

    {

      color[v] = c;

      dfs_(v, c);
    }
  }
}

void bfs(int r, int c)

{

  queue<int> S;

  S.push(r);

  color[r] = c;

  while (!S.empty())

  {

    int u = S.front();
    S.pop();

    for (int i = 0; i < G[u].size(); i++)

    {

      int v = G[u][i];

      if (color[v] == NIL)

      {

        color[v] = c;

        S.push(v);
      }
    }
  }
}

void assigncolor()

{

  int id = 1;

  memset(color, NIL, sizeof(color));

  for (int u = 0; u < n; u++)

    if (color[u] == NIL)

      dfs_(u, id++);
}

