  for (int i = 0; i < N; ++i) {

    cnt[A[i]]++;
  }

  FFT<long long> C(cnt, cnt);

  long long ans = 0;

  for (int i = 2 * MAX_A; i >= 0; --i) {

    if (M >= C[i]) {

      ans += i * C[i];

      M -= C[i];

    } else {

      ans += i * M;

      break;
    }
  }

  std::cout << ans << std::endl;
}
