ll dinic(int s, int t, const vector<vector<P>> &graph) {

  struct max_flow {

    struct edge_ {
      int to;
      ll cap;
      int rev;
    };

    int V;

    vector<vector<edge_>> G;

    vector<int> itr, level;

    max_flow(int V) : V(V) { G.assign(V, vector<edge_>()); }

    void add_edge(int from, int to, ll cap) {

      G[from].push_back((edge_){to, cap, (int)G[to].size()});

      G[to].push_back((edge_){from, 0, (int)G[from].size() - 1});
    }

    void bfs(int s) {

      level.assign(V, -1);

      std::queue<int> q;

      level[s] = 0;
      q.push(s);

      while (!q.empty()) {

        int v = q.front();
        q.pop();

        for (auto &e : G[v])
          if (e.cap > 0 and level[e.to] < 0) {

            level[e.to] = level[v] + 1;

            q.push(e.to);
          }
      }
    }

    ll dfs(int v, int t, ll f) {

      if (v == t)
        return f;

      for (int &i = itr[v]; i < (int)G[v].size(); ++i) {

        edge_ &e = G[v][i];

        if (e.cap > 0 and level[v] < level[e.to]) {

          int d = dfs(e.to, t, std::min(f, e.cap));

          if (d > 0) {

            e.cap -= d;

            G[e.to][e.rev].cap += d;

            return d;
          }
        }
      }

      return 0;
    }

    int run(int s, int t) {

      int ret = 0, f;

      while (bfs(s), level[t] >= 0) {

        itr.assign(V, 0);

        while ((f = dfs(s, t, 1LL << 59)) > 0)
          ret += f;
      }

      return ret;
    }
  };

  max_flow d(graph.size());

  REP(i, graph.size()) for (auto e : graph[i]) {

    d.add_edge(i, e.second, e.first);
  }

  return d.run(s, t);
