    return *this;
  }

  MAT operator/=(T a) {
    *this = *this / a;
    return *this;
  }

  friend MAT operator*(T n, MAT x) {

    MAT r(x.row, x.col);

    REP(i, x.row) REP(j, x.col) r[i][j] = n * x[i][j];

    return r;
  }

  friend MAT operator*(MAT x, T n) {

    MAT r(x.row, x.col);

    REP(i, x.row) REP(j, x.col) r[i][j] = n * x[i][j];

    return r;
  }

  explicit operator vector<vector<T>>() { return _A; }

  friend std::ostream &operator<<(std::ostream &os, const MAT &x) {
    REP(i, x.row) REP(j, x.col) os << x._A[i][j] << " \n"[j == x.col - 1];
    return os;
  }

  friend std::istream &operator>>(std::istream &is, MAT &x) {
    REP(i, x.row) REP(j, x.col) is >> x._A[i][j];
    return is;
  }

  size_t size_row() const { return row; }

  size_t size_col() const { return col; }

  MAT transpose() const {

    MAT r(col, row);

    REP(i, col) REP(j, row) r[i][j] = _A[j][i];

    return r;
  }

  MAT inverse() const {

    T buf;

    MAT<T> inv_a(row, 0);

    vector<vector<T>> a = _A;

    REP(i, row) {

      buf = 1 / a[i][i];

      REP(j, row) {

        a[i][j] *= buf;

        inv_a[i][j] *= buf;
      }

      REP(j, row) {

        if (i != j) {

          buf = a[j][i];

          REP(k, row) {

            a[j][k] -= a[i][k] * buf;

            inv_a[j][k] -= inv_a[i][k] * buf;
          }
        }
      }
    }

    return inv_a;
  }

  MAT Jacobi(MAT b) const {

    size_t sz = row;

    MAT D(sz, sz), inD(sz, sz), H(sz, sz), N(sz, sz);

    MAT c(sz, 1), x(sz, 1), tmp(sz, 1);

    REP(i, sz) {

      REP(j, sz) {

        H[i][j] = 0;

        if (i == j) {

          D[i][j] = _A[i][j];

          inD[i][j] = 1 / _A[i][j];

          N[i][j] = 0;

        }

        else if (i != j) {

          D[i][j] = 0;

          inD[i][j] = 0;

          N[i][j] = _A[i][j];
        }
      }

      c[i][0] = 0;

      x[i][0] = 1;
    }

    c = inD * b;

    H = inD * N;

    while (1) {

      tmp = x;

      x = c - H * x;

      T r = T(0);

      for (int i = 0; i < row; ++i) {

        r += (x[i][0] - tmp[i][0]) * (x[i][0] - tmp[i][0]);
      }

      if (r < eps)
        break;
    }

    return x;
  }

  MAT Gauss(MAT b) const {

    MAT<T> DL(row), U(row), inDL(row), H(row), c(row, 1), x(row, 1),
        tmp(row, 1);

    for (int i = 0; i < row; i++) {

      for (int j = 0; j < col; j++) {

        H[i][j] = 0;

        if (i >= j) {

          DL[i][j] = _A[i][j];

          U[i][j] = 0;

        }

        else {

          DL[i][j] = 0;

          U[i][j] = _A[i][j];
        }
      }

      x[i][0] = 1;
    }

    inDL = DL.inverse();

    c = inDL * b;

    H = inDL * U;

    int n = 0;

    while (1) {

      tmp = x;

      x = c - H * x;

      T r = T(0);

      for (int i = 0; i < row; ++i) {

        r += (x[i][0] - tmp[i][0]) * (x[i][0] - tmp[i][0]);
      }

      n++;

      if (r < eps)
        break;
    }

    return x;
  }

  int rank() const {

    vector<vector<T>> A = _A;

    const int n = row, m = col;

    int r = 0;

    for (int i = 0; r < n && i < m; ++i) {

      int pivot = r;

      for (int j = r + 1; j < n; ++j)
        if (fabs(A[j][i]) > fabs(A[pivot][i]))
          pivot = j;

      swap(A[pivot], A[r]);

      if (fabs(A[r][i]) < eps)
        continue;

      for (int k = m - 1; k >= i; --k)
        A[r][k] /= A[r][i];

      rep(j, r + 1, n) rep(k, i, m) A[j][k] -= A[r][k] * A[j][i];

      ++r;
    }

    return r;
  }
};

class UnionFind {

private:
  vector<int> Parent, es;

  vector<ll> diff_weight;

public:
  UnionFind(int N) {

    es.resize(N, 0);

    Parent.resize(N, -1);

    diff_weight.resize(N, 0LL);
  }

  int root(int A) {

    if (Parent[A] < 0)
      return A;

    else {

      int r = root(Parent[A]);

      diff_weight[A] += diff_weight[Parent[A]];

      return Parent[A] = r;
    }
  }

  bool issame(int A, int B) { return root(A) == root(B); }

  ll weight(int x) {

    root(x);

    return diff_weight[x];
  }

  ll diff(int x, int y) { return weight(y) - weight(x); }

  int size(int A) { return -Parent[root(A)]; }

  int eize(int A) { return es[root(A)]; }

  bool connect(int A, int B) {

    A = root(A);
    B = root(B);

    if (A == B)
      return false;

    if (size(A) < size(B))
      std::swap(A, B);

    Parent[A] += Parent[B];

    es[A] += es[B] + 1;

    Parent[B] = A;

    return true;
  }

  void unite(int A, int B) {

    A = root(A);
    B = root(B);

    if (A == B) {

      es[A]++;

      return;
    }

    if (size(A) < size(B))
      std::swap(A, B);

    Parent[A] += Parent[B];

    es[A] += es[B] + 1;

    Parent[B] = A;

    return;
  }

  bool merge(int A, int B, ll w) {

    w += weight(A);
    w -= weight(B);

    A = root(A);
    B = root(B);

    if (A == B)
      return false;

    if (size(A) < size(B))
      std::swap(A, B), w = -w;

    Parent[A] += Parent[B];

    Parent[B] = A;

    diff_weight[B] = w;

    return true;
  }
};

class SOSU {

private:
  vector<int> Prime_Number;

  vector<bool> isp;

public:
  SOSU(int N) {

    isp.resize(N + 1, true);

    isp[0] = isp[1] = false;

    rep(i, 2, N + 1) if (isp[i]) {

      Prime_Number.push_back(i);

      for (int j = 2 * i; j <= N; j += i)
        isp[j] = false;
    }
  }

  int operator[](int i) { return Prime_Number[i]; }

  int size() { return Prime_Number.size(); }

  int back() { return Prime_Number.back(); }

  bool isPrime(int q) { return isp[q]; }
};

class Divisor {

private:
  vector<ll> F;

  vector<P> pfactorize;

public:
  Divisor(ll N) {

    for (ll i = 1; i * i <= N; i++) {

      if (N % i == 0) {

        F.push_back(i);

        if (i * i != N)
          F.push_back(N / i);
      }
    }

    sort(begin(F), end(F));

    SOSU p(Math::sqrt(N) + 1);

    REP(i, p.size()) {

      pfactorize.push_back(P(p[i], 0));

      while (N % p[i] == 0) {

        N /= p[i];

        pfactorize.back().second++;
      }

      if (pfactorize.back().second == 0)
        pfactorize.pop_back();
    }

    if (N > 1)
      pfactorize.push_back(P(N, 1));
  }

  int size() { return F.size(); }

  vector<P> pfac() { return pfactorize; }

  ll operator[](int k) { return F[k]; }
};

struct compress {

  std::map<ll, int> zip;

  vector<ll> unzip;

  compress(vector<ll> x) {

    unzip = x;

    sort(All(x));

    x.erase(unique(All(x)), x.end());

    REP(i, x.size()) { zip[x[i]] = i; }
  }

  int operator[](int k) { return zip[unzip[k]]; }
};

struct edge {

  int from;
  int to;
  ll cost;

  void push(int a, int b, int c) {

    from = a;
    to = b;
    cost = c;
  }

  bool operator<(const edge &y) const {

    if (cost != y.cost)
      return cost < y.cost;

    else if (to != y.to)
      return to < y.to;

    else
      return from < y.from;
  }

  bool operator>(const edge &y) const {

    if (cost != y.cost)
      return cost > y.cost;

    else if (to != y.to)
      return to > y.to;

    else
      return from > y.from;
  }

  bool operator==(const edge &y) const { return !(*this < y) && !(*this > y); }
};

class lca {

public:
  const int n = 0;

  const int log2_n = 0;

  std::vector<std::vector<int>> parent;

  std::vector<int> depth;

  lca() {}

  lca(const Graph &g, int root)

      : n(g.size()), log2_n(log2(n) + 1), parent(log2_n, std::vector<int>(n)),
        depth(n) {

    dfs(g, root, -1, 0);

    for (int k = 0; k + 1 < log2_n; k++) {

      for (int v = 0; v < (int)g.size(); v++) {

        if (parent[k][v] < 0)

          parent[k + 1][v] = -1;

        else

          parent[k + 1][v] = parent[k][parent[k][v]];
      }
    }
  }

  void dfs(const Graph &g, int v, int p, int d) {

    parent[0][v] = p;

    depth[v] = d;

    REP(j, g[v].size()) {

      if (g[v][j] != p)
        dfs(g, g[v][j], v, d + 1);
    }
  }

  int get(int u, int v) {

    if (depth[u] > depth[v])
      std::swap(u, v);

    for (int k = 0; k < log2_n; k++) {

      if ((depth[v] - depth[u]) >> k & 1) {

        v = parent[k][v];
      }
    }

    if (u == v)
      return u;

    for (int k = log2_n - 1; k >= 0; k--) {

      if (parent[k][u] != parent[k][v]) {

        u = parent[k][u];

        v = parent[k][v];
      }
    }

    return parent[0][u];
  }
};

template <typename T> class SegmentTree {

private:
  typedef std::function<T(T, T)> F;

  int n;

  T d0;

  vector<T> vertex;

  F f;

  F g;

public:
  SegmentTree(F f, F g, T d) : d0(d), f(f), g(g) {}

  void init(int _n) {

    n = 1;

    while (n < _n)
      n *= 2;

    vertex.resize(2 * n - 1, d0);
  }

  void build(const vector<T> &v) {

    int n_ = v.size();

    init(n_);

    for (int i = 0; i < n_; i++)
      vertex[n + i - 1] = v[i];

    for (int i = n - 2; i >= 0; i--)

      vertex[i] = f(vertex[2 * i + 1], vertex[2 * i + 2]);
  }

  void update(int i, T x) {

    int k = i + n - 1;

    vertex[k] = g(vertex[k], x);

    while (k > 0) {

      k = (k - 1) / 2;

      vertex[k] = f(vertex[2 * k + 1], vertex[2 * k + 2]);
    }

    return;
  }

  T query(int l, int r) {

    T vl = d0, vr = d0;

    l += n - 1;

    r += n - 1;

    for (; l <= r; l /= 2, r = r / 2 - 1) {

      if (l % 2 == 0)
        vl = f(vl, vertex[l]);

      if (r & 1)
        vr = f(vr, vertex[r]);
    }

    return f(vl, vr);
  }
};

template <typename T, typename E>

struct LazySegmentTree {

  using F = std::function<T(T, T)>;

  using G = std::function<T(T, E)>;

  using H = std::function<E(E, E)>;

  int n, height;

  F f;

  G g;

  H h;

  T ti;

  E ei;

  vector<T> dat;

  vector<E> laz;

  LazySegmentTree(F f, G g, H h, T ti, E ei)
      :

        f(f), g(g), h(h), ti(ti), ei(ei) {}

  void init(int n_) {

    n = 1;
    height = 0;

    while (n < n_)
      n <<= 1, height++;

    dat.assign(2 * n, ti);

    laz.assign(2 * n, ei);
  }

  void build(const vector<T> &v) {

    int n_ = v.size();

    init(n_);

    for (int i = 0; i < n_; i++)
      dat[n + i] = v[i];

    for (int i = n - 1; i; i--)

      dat[i] = f(dat[(i << 1) | 0], dat[(i << 1) | 1]);
  }

  inline T reflect(int k) { return laz[k] == ei ? dat[k] : g(dat[k], laz[k]); }

  inline void propagate(int k) {

    if (laz[k] == ei)
      return;

    laz[(k << 1) | 0] = h(laz[(k << 1) | 0], laz[k]);

    laz[(k << 1) | 1] = h(laz[(k << 1) | 1], laz[k]);

    dat[k] = reflect(k);

    laz[k] = ei;
  }

  inline void thrust(int k) {

    for (int i = height; i; i--)
      propagate(k >> i);
  }

  inline void recalc(int k) {

    while (k >>= 1)

      dat[k] = f(reflect((k << 1) | 0), reflect((k << 1) | 1));
  }

  void update(int a, int b, E x) {

    thrust(a += n);

    thrust(b += n - 1);

    for (int l = a, r = b + 1; l < r; l >>= 1, r >>= 1) {

      if (l & 1)
        laz[l] = h(laz[l], x), l++;

      if (r & 1)
        --r, laz[r] = h(laz[r], x);
    }

    recalc(a);

    recalc(b);
  }

  void set_val(int a, T x) {

    thrust(a += n);

    dat[a] = x;
    laz[a] = ei;

    recalc(a);
  }

  T query(int a, int b) {

    thrust(a += n);

    thrust(b += n - 1);

    T vl = ti, vr = ti;

    for (int l = a, r = b + 1; l < r; l >>= 1, r >>= 1) {

      if (l & 1)
        vl = f(vl, reflect(l++));

      if (r & 1)
        vr = f(reflect(--r), vr);
    }

    return f(vl, vr);
  }

  template <typename C>

  int find(int st, C &check, T &acc, int k, int l, int r) {

    if (l + 1 == r) {

      acc = f(acc, reflect(k));

      return check(acc) ? k - n : -1;
    }

    propagate(k);

    int m = (l + r) >> 1;

    if (m <= st)
      return find(st, check, acc, (k << 1) | 1, m, r);

    if (st <= l && !check(f(acc, dat[k]))) {

      acc = f(acc, dat[k]);

      return -1;
    }

    int vl = find(st, check, acc, (k << 1) | 0, l, m);

    if (~vl)
      return vl;

    return find(st, check, acc, (k << 1) | 1, m, r);
  }

  template <typename C>

  int find(int st, C &check) {

    T acc = ti;

    return find(st, check, acc, 1, 0, n);
  }
};

struct rational {

  ll p, q;

  void normalize() {

    if (q < 0)
      p *= -1, q *= -1;

    ll d = Math::gcd(p < 0 ? -p : p, q);

    if (d == 0)
      p = 0, q = 1;

    else
      p /= d, q /= d;
  }

  rational(ll p, ll q = 1) : p(p), q(q) { normalize(); }

  rational &operator+=(const rational &a) {
    p = a.q * p + a.p * q;
    q = a.q * q;
    normalize();
    return *this;
  }

  rational &operator-=(const rational &a) {
    p = a.q * p - a.p * q;
    q = a.q * q;
    normalize();
    return *this;
  }

  rational &operator*=(const rational &a) {
    p *= a.p;
    q *= a.q;
    normalize();
    return *this;
  }

  rational &operator/=(const rational &a) {
    p *= a.q;
    q *= a.p;
    normalize();
    return *this;
  }

  rational &operator-() {
    p *= -1;
    return *this;
  }

  friend rational operator+(const rational &a, const rational &b) {
    return rational(a) += b;
  }

  friend rational operator*(const rational &a, const rational &b) {
    return rational(a) *= b;
  }

  friend rational operator-(const rational &a, const rational &b) {
    return rational(a) -= b;
  }

  friend rational operator/(const rational &a, const rational &b) {
    return rational(a) /= b;
  }

  friend bool operator<(const rational &a, const rational &b) {

    return (long double)a.p * b.q < (long double)a.q * b.p;
  }

  friend bool operator<=(const rational &a, const rational &b) {
    return !(b < a);
  }

  friend bool operator>(const rational &a, const rational &b) { return b < a; }

  friend bool operator>=(const rational &a, const rational &b) {
    return !(a < b);
  }

  friend bool operator==(const rational &a, const rational &b) {
    return !(a < b) && !(b < a);
  }

  friend bool operator!=(const rational &a, const rational &b) {
    return (a < b) || (b < a);
  }

  friend std::ostream &operator<<(std::ostream &os, const rational &x) {
    printf("%.16f", (double)x.p / (double)x.q);
    return os;
  }

  friend std::istream &operator>>(std::istream &is, rational &x) {
    is >> x.p >> x.q;
    x.normalize();
    return is;
  }
};

template <typename T>

class FFT {

private:
  using Complex = std::complex<double>;

  std::vector<Complex> C;

  void DFT(std::vector<Complex> &F, int n, int sig = 1) {

    if (n == 1)
      return;

    std::vector<Complex> f0(n / 2), f1(n / 2);

    for (int i = 0; i < n / 2; ++i) {

      f0[i] = F[2 * i];

      f1[i] = F[2 * i + 1];
    }

    DFT(f0, n / 2, sig);

    DFT(f1, n / 2, sig);

    Complex z(cos(2.0 * PI / n), sin(2.0 * PI / n) * sig), zi = 1;

    for (int i = 0; i < n; ++i) {

      if (i < n / 2)
        F[i] = f0[i] + zi * f1[i];

      else
        F[i] = f0[i - n / 2] + zi * f1[i - n / 2];

      zi *= z;
    }

    return;
  }

  void invDFT(std::vector<Complex> &f, int n) {

    DFT(f, n, -1);

    for (int i = 0; i < n; ++i) {

      f[i] /= n;
    }

    return;
  }

public:
  FFT(const std::vector<T> &A, const std::vector<T> &B) {

    int n = 1;

    while (n <= A.size() + B.size()) {

      n *= 2;
    }

    std::vector<Complex> g(n, Complex(0));

    C.resize(n, Complex(0));

    int i_len = std::max(A.size(), B.size());

    for (int i = 0; i < i_len; ++i) {

      if (i < A.size())
        C[i] = Complex(A[i]);

      if (i < B.size())
        g[i] = Complex(B[i]);
    }

    DFT(C, n);

    DFT(g, n);

    for (int i = 0; i < n; ++i)
      C[i] = C[i] * g[i];

    invDFT(C, n);

    for (int i = 0; i < n; ++i)
      if (T(C[i].real()) != C[i].real()) {

        C[i] = Complex(C[i].real() + 0.5);
      }
  }

  T operator[](int k) const { return T(C[k].real()); }
};

