  for (int i = 1; i <= n; i++) {

    if (vis[i] != -1)
      continue;

    memset(col, 0, sizeof(col));

    if (dfs(i, 0) == 0) {

      cout << "No\n";

      return 0;
    }
  }

  cout << "Yes\n";

  return 0;
}

