  rep(i, (int)s.size() - (int)t.size() + 1) {

    if (h == hikaku) {

      ans.emplace_back(i);
    }

    h *= ki;

    h %= hamod;

    h += s[i + (int)t.size()];

    h %= hamod;

    h += hamod;

    h -= s[i] * kim % hamod;

    h %= hamod;
  }

  return ans;
}

