const int mod = 1e9 + 7;

template <int MOD> struct Mint {

  int x;

  Mint() : x(0) {}

  Mint(int y) : x(y >= 0 ? y % MOD : MOD - (-y) % MOD) {}

  Mint(int64_t sll) : x(sll % MOD) {
    if (x < 0)
      x += MOD;
  }

  Mint &operator+=(const Mint &rhs) {
    if ((x += rhs.x) >= MOD)
      x -= MOD;
    return *this;
  }

  Mint &operator-=(const Mint &rhs) {
    if ((x += MOD - rhs.x) >= MOD)
      x -= MOD;
    return *this;
  }

  Mint &operator*=(const Mint &rhs) {
    x = 1LL * x * rhs.x % MOD;
    return *this;
  }

  Mint &operator/=(const Mint &rhs) {
    x = (1LL * x * rhs.inv().x) % MOD;
    return *this;
  }

  Mint operator-() const { return Mint(-x); }

  Mint operator+(const Mint &rhs) const { return Mint(*this) += rhs; }

  Mint operator-(const Mint &rhs) const { return Mint(*this) -= rhs; }

  Mint operator*(const Mint &rhs) const { return Mint(*this) *= rhs; }

  Mint operator/(const Mint &rhs) const { return Mint(*this) /= rhs; }

  bool operator<(const Mint &rhs) const { return x < rhs.x; }

  Mint inv() const {

    assert(x != 0);

    signed a = x, b = MOD, u = 1, v = 0, t;

    while (b) {
      t = a / b;
      a -= t * b;
      swap(a, b);
      u -= t * v;
      swap(u, v);
    }

    return Mint(u);
  }

  Mint operator^(uint64_t t) const {

    Mint e = *this, res = 1;

    for (; t; e *= e, t >>= 1)
      if (t & 1)
        res *= e;

    return res;
  }
};

template <int MOD> ostream &operator<<(ostream &os, const Mint<MOD> &rhs) {
  return os << rhs.x;
}

