template <typename T> struct BinaryIndexedTree0 {

  const int N;

  vector<T> val;

  BinaryIndexedTree0(int N) : N(N), val(N) {}

  T sum(int i) const {

    T s = 0;

    --i;

    if (i >= N)
      i = N - 1;

    for (; i >= 0; i = (i & (i + 1)) - 1)
      s += val[i];

    return s;
  }

  T sum(int l, int r) const { return sum(r) - sum(l); }

  void add(int i, T x) {

    for (; i < N; i |= i + 1)
      val[i] += x;
  }
};

mint solve() {

  int n = ri();

  vector<int> A(n);

  rep(i, n) A[i] = ri();

  vector<int> B(n);

  rep(i, n) B[i] = ri();

  sort(all(A));

  sort(all(B));

  sort(all(A));

  sort(all(B));

  {

    A.emplace_back(2e9);

    B.emplace_back(2e9);

    int i = 0;

    int p = 0, q = 0;

    while (1) {

      if (A[p] < B[q]) {

        A[p++] = i++;

      }

      else if (A[p] > B[q]) {

        B[q++] = i++;

      }

      else {

        A.pop_back();

        B.pop_back();

        break;
      }
    }
  }

  out(A);

  out(B);

  BinaryIndexedTree0<int> ftA(n * 2), ftB(n * 2);

  forr(a, A) ftA.add(a, 1);

  forr(b, B) ftB.add(b, 1);

  mint ans = 1;

  rep(i, n) {

    int a = A[i];

    int b = B[i];

    out(i, a, b);

    int j = i;

    if (a < b) {

      for (; j < n && A[j] < B[j]; j++) {

        int cnt = ftA.sum(A[i], B[j]);

        out(i, j, A[i], B[j], cnt);

        cnt -= (j - i);

        ans *= cnt;
      }

    }

    else {

      for (; j < n && A[j] > B[j]; j++) {

        int cnt = ftB.sum(B[i], A[j]);

        out(i, j, B[i], A[j], cnt);

        cnt -= (j - i);

        ans *= cnt;
      }
    }

    i = j - 1;
  }

  return ans;
}

void Main() { cout << solve() << endl; }

