ll n;

std::vector<ll> ara[100010];

ll dp[100010][4];

ll fnc(ll idx, ll last) {

  if (idx == n)
    return 0;

  if (dp[idx][last] != -1)
    return dp[idx][last];

  ll res1 = -(1 << 25);

  ll res2 = -(1 << 25);

  ll res3 = -(1 << 25);

  if (last == 0) {

    res1 = max(res1, ara[idx][0] + fnc(idx + 1, 1));

    res2 = max(res2, ara[idx][1] + fnc(idx + 1, 2));

    res3 = max(res3, ara[idx][2] + fnc(idx + 1, 3));

  } else if (last == 1) {

    res2 = max(res2, ara[idx][1] + fnc(idx + 1, 2));

    res3 = max(res3, ara[idx][2] + fnc(idx + 1, 3));

  } else if (last == 2) {

    res1 = max(res1, ara[idx][0] + fnc(idx + 1, 1));

    res3 = max(res3, ara[idx][2] + fnc(idx + 1, 3));

  } else if (last == 3) {

    res1 = max(res1, ara[idx][0] + fnc(idx + 1, 1));

    res2 = max(res2, ara[idx][1] + fnc(idx + 1, 2));
  }

  dp[idx][last] = max(res1, max(res2, res3));

  return dp[idx][last];
}

int main(int argc, char const *argv[]) {

