    int low = idx;

    int low_cnt = 0, upper_cnt = 0;

    for (int i = idx - 1; i >= 0; i--) {

      if (block[i] == block[idx]) {
        low_cnt++;
      }

      else
        break;
    }

    for (int i = idx + 1; i < size; i++) {

      if (block[i] == block[idx])
        upper_cnt++;

      else
        break;
    }

    int cnt = low_cnt + upper_cnt + 1;

    if (cnt < 4) {

      return size;
    }

    for (int i = 0; i < size - (idx + upper_cnt); i++) {

      block[idx - low_cnt + i] = block[idx + upper_cnt + i + 1];
