  {

    prime[j] = true;
  }

  for (j = 2; j <= 1000; j++)

  {

    if (prime[j])

    {

      for (int k = 2; j * k <= 100000; k++)

      {

        prime[j * k] = false;
      }
    }
  }

  for (j = 1; j <= 100000; j++)

  {

    if (prime[j])

    {

      vec.push_back(j);
    }
  }
