{

  if (b == 0)

    return 1;

  if (b == 1)

    return a % mod;

  else

  {

    int r = power(a, b / 2);

    if (b % 2 == 0)

    {

      return (r * r) % mod;

    }

    else

    {

      int x = (r * r) % mod;

      return (a * x) % mod;
    }
  }
}

int32_t main()

{

  function();

  int n, k;

  cin >> n >> k;

  int arr[k + 2] = {0};

  int j;

  for (j = k; j >= 1; j--)

  {

    int div = k / j;

    int val = power(div, n);

    int i;

    for (i = 2; i <= k; i++)

    {

      int p = j * i;

      if (p <= k)

      {

        val -= arr[p];

        val = val % mod;

      }

      else

      {

