struct UnionFind {

  vector<int> data;

  UnionFind(int sz) { data.assign(sz, -1); }

  inline void Unite(int a, int b) {

    if ((a = Root(a)) == (b = Root(b)))
      return;

    if (data[a] < data[b])
      swap(a, b);

    data[b] += data[a];

    data[a] = b;
  }

  inline int Root(int x) { return (data[x] < 0 ? x : data[x] = Root(data[x])); }
};

struct SegmentTree {

