    if (a >= r || b <= l)
      return (INF);

    if (a <= l && r <= b)
      return (data[k]);

    return (min(Query(a, b, 2 * k + 1, l, (l + r) >> 1),
                Query(a, b, 2 * k + 2, (l + r) >> 1, r)));
  }

  inline int Query(int a, int b)

  {

    return (Query(a, b, 0, 0, sz));
  }
