  fill_n(dist, V, INF);

  fill_n(used, V, false);

  priority_queue<P, vector<P>, greater<P>> q;

  q.push(P(0, s));

  while (!q.empty()) {

    int d;
    int t;

    tie(d, t) = q.top();
    q.pop();

    if (used[t])
      continue;

    used[t] = true;
    dist[t] = d;

    for (P e : G[t]) {

      if (dist[e.second] <= d + e.first)
        continue;

      q.push(P(d + e.first, e.second));
    }
  }
}

