  {

    return this->dist < rhs.dist;
  }
};

Edge ed[MAXN];

ll nc, cnt, x, y, z, tot;

ll dist[MAXN], boss[MAXN];

inline ll read()

{

  register ll num = 0, neg = 1;

  register char ch = getchar();

  while (!isdigit(ch) && ch != '-')

  {

    ch = getchar();
  }

  if (ch == '-')

  {

    neg = -1;

    ch = getchar();
  }

  while (isdigit(ch))

  {

    num = (num << 3) + (num << 1) + (ch - '0');

    ch = getchar();
  }

  return num * neg;
}

inline void setup(ll cnt)

{

  for (register int i = 0; i < cnt; i++)

  {

    boss[i] = i;
  }
}

inline void update()

{

  for (register int i = 0; i < nc; i++)

  {

    dist[i] = min(dist[i], dist[(i + nc - 1) % nc] + 2);
  }
}

inline ll findb(ll node)

{

  if (node == boss[node])

  {

    return node;
  }

  boss[node] = findb(boss[node]);

  return boss[node];
}

inline void Union(ll x, ll y)

{

  ll bx = findb(x), by = findb(y);

  if (bx != by)

  {

    boss[by] = bx;
  }
}

