    (x += a.x) %= mod;

    return *this;
  }

  mint &operator-=(const mint a) {

    (x += mod - a.x) %= mod;

    return *this;
  }

  mint &operator*=(const mint a) {

    (x *= a.x) %= mod;

    return *this;
  }

