{

  node c;

  c.c1 = min(lc.c1, rc.c1);

  c.k1 = lc.c1 < rc.c1 ? lc.k1 : rc.k1;

  c.k2 = lc.c2 < rc.c2 ? lc.k2 : rc.k2;

  c.c2 = min(lc.c2, rc.c2);

  return c;
}

void change(LL x, LL l, LL r, LL k, node c)

{

  if (l == r) {
    tr[x].c = c;
