{

  if (dp[d][b] != -1)

    return dp[d][b];

  if (d == 0)

    return 1;

  ll res = 0;

  if (b == 10)

  {

    for (int i = 1; i <= 9; i++)

    {

      res += f(d - 1, i);
    }

  }

  else

  {

    for (int i = max(0, b - 1); i <= min(9, b + 1); i++)

    {

      res += f(d - 1, i);
    }
  }

  return dp[d][b] = res;
