  f[n] = true;

  ET.emplace_back(make_pair(dep, n));

  Ind[n] = ET.size() - 1;

  for (int next : T[n]) {

    if (f[next] == true)
      continue;

    dfs(next, dep + 1);

    ET.emplace_back(make_pair(dep, n));
  }
}

P RMQ(int a, int b, int k, int l, int r, vector<P> &node) {

  if (r <= a || b <= l) {
    return P(INF, INF);
  }

  if (a <= l && r <= b)
    return node[k];

  P vl = RMQ(a, b, 2 * k + 1, l, (l + r) / 2, node);

  P vr = RMQ(a, b, 2 * k + 2, (l + r) / 2, r, node);

  return min(vl, vr);
}

