  ios::sync_with_stdio(false);

  cin >> h >> w;

  for (int i = 0; i < h; ++i) {

    cin >> color[i];
  }

  for (int i = 0; i < w - 1; ++i) {

    for (int j = 0; j <= h; ++j)

      for (int k = 0; k <= h; ++k) {

        if (j == 0 || k == 0) {

          LL tmp = 0;

          for (int l = 0; l < h; ++l) {

            if (l - j >= 0 && l - k >= 0 &&
                color[l - j][i] == color[l - k][i + 1])

              tmp++;
          }

          cost[j][k] = tmp;

        } else {

          cost[j][k] = cost[j - 1][k - 1] -
                       (color[h - j][i] == color[h - k][i + 1] ? 1 : 0);
        }
