    dp[0][0] = 0;

    for (int j = 0; j <= h; ++j) {

      for (int k = 0; k <= h; ++k) {

        LL tmpA = j > 0 ? dp[j - 1][k] + cost[j - 1][k] : INF;

        LL tmpB = k > 0 ? dp[j][k - 1] + cost[j][k - 1] : INF;

        chmin(dp[j][k], min(tmpA, tmpB));
      }
    }

    sum += dp[h][h];
  }

