      if (st.query(now + 1, mi + 1) <= out - i - 1) {

        hi = mi;

      } else {

        lo = mi + 1;
      }
    }

    cout << lo - now << (i == out - 1 ? '\n' : ' ');

    now = lo;
  }
}

