{

  memset(c, 0, sizeof(c));

  for (int i = 0; i < n; ++i) {

    int x1 = (lower_bound(x, x + w, l[i]) - x) * 2 + 1;

    int x2 = (lower_bound(x, x + w, r[i]) - x) * 2 + 1;

    int y1 = (lower_bound(y, y + h, b[i]) - y) * 2 + 1;

    int y2 = (lower_bound(y, y + h, t[i]) - y) * 2 + 1;

    for (int x = x1; x <= x2; ++x)
      c[x][y1] = c[x][y2] = true;

    for (int y = y1; y <= y2; ++y)
      c[x1][y] = c[x2][y] = true;
  }
}

