  if (a[cnt] < a[t[o][pos]])
    t[o][pos] = cnt;

  if (l == r)
    return;

  int mid = (l + r) >> 1;

  if (cnt <= mid)
    add(o, pos << 1, l, mid, cnt);

  else
    add(o, pos << 1 | 1, mid + 1, r, cnt);
}

inline int ask(int o, int pos, int l, int r, int L, int R) {

  if (l > R || r < L)
    return 0;

  if (L <= l && r <= R)
    return t[o][pos];

  int mid = (l + r) >> 1;

  int lans = ask(o, pos << 1, l, mid, L, R);

  int rans = ask(o, pos << 1 | 1, mid + 1, r, L, R);

  return a[lans] < a[rans] ? lans : rans;
}

