template <typename T>

class fenwick {

public:
  vector<T> fenw;

  int n;

  fenwick(int _n) : n(_n) { fenw.resize(n); }

  void modify(int x, T v) {

    while (x < n) {

      fenw[x] += v;

      x |= (x + 1);
    }
  }

  T get(int x) {

    T v{};

    while (x >= 0) {

      v += fenw[x];

      x = (x & (x + 1)) - 1;
    }

    return v;
  }

  T get(int l, int r) { return get(r) - (l - 1 >= 0 ? get(l - 1) : 0); }
};

struct SegTree {

  ll n;

  ll passiveEl = 0LL;

  SegTree(ll sz) { n = sz; }

  void input() {

    rep(i, 0, n) { cin >> a[i]; }
  }

  Node getOp(Node left, Node right) { return Node(left.val + right.val); }

  void pull(ll v) { t[v] = getOp(t[v * 2 + 1], t[v * 2 + 2]); }

  ll find_kth(ll v, ll l, ll r, ll k) {

    if (k > t[v].val)

      return -1;

    if (l == r)

      return l;

    int tm = (l + r) / 2;

    if (t[v * 2 + 1].val >= k)

      return find_kth(v * 2 + 1, l, tm, k);

    else

      return find_kth(v * 2 + 2, tm + 1, r, k - t[v * 2 + 1].val);
  }

  ll findKth(ll pos) { return find_kth(0, 0, n - 1, pos + 1); }

  void build(ll v, ll l, ll r) {

    if (l == r) {

      t[v] = Node(a[l]);

      return;
    }

    ll m = (l + r) / 2;

    build(v * 2 + 1, l, m);

    build(v * 2 + 2, m + 1, r);

    pull(v);
  }

  void updateEl(ll v, ll tl, ll tr, ll pos, Node val) {

    if (tl == tr) {

      t[v].val += val.val;

      return;
    }

    ll tm = (tl + tr) / 2;

    if (pos <= tm) {

      updateEl(v * 2 + 1, tl, tm, pos, val);

    } else {

      updateEl(v * 2 + 2, tm + 1, tr, pos, val);
    }

    pull(v);
  }

  Node get(ll v, ll tl, ll tr, ll l, ll r) {

    if (l > r)
      return passiveEl;

    if (tl == l && r == tr)
      return t[v];

    ll tm = (tl + tr) / 2;

    return getOp(get(v * 2 + 1, tl, tm, l, min(tm, r)),

                 get(v * 2 + 2, tm + 1, tr, max(tm + 1, l), r));
  }

  void updateEl(ll pos, ll val) { updateEl(0, 0, n - 1, pos, val); }

  Node get(ll l, ll r) { return get(0, 0, n - 1, l, r); }

  void build() { build(0, 0, n - 1); }
};

