#include <cstdio>

#include <algorithm>

using namespace std;

const int MAXN = 5000;

const int MOD = int(1E9) + 7;

const int INV2 = (MOD + 1) >> 1;

struct edge {

  edge *nxt;
  int to;

} edges[2 * MAXN + 5], *adj[MAXN + 5], *ecnt = edges;

void addedge(int u, int v) {

  edge *p = (++ecnt);

  p->to = v, p->nxt = adj[u], adj[u] = p;

  p = (++ecnt);

  p->to = u, p->nxt = adj[v], adj[v] = p;
}

int fct[MAXN + 5], ifct[MAXN + 5], coef[MAXN + 5];

void init() {

  fct[0] = 1;

  for (int i = 1; i <= MAXN; i++)

    fct[i] = 1LL * fct[i - 1] * i % MOD;

  ifct[1] = 1;

  for (int i = 2; i <= MAXN; i++)

    ifct[i] = (MOD - 1LL * (MOD / i) * ifct[MOD % i] % MOD);

  ifct[0] = 1;

  for (int i = 1; i <= MAXN; i++)

    ifct[i] = 1LL * ifct[i - 1] * ifct[i] % MOD;

  int t = INV2;

  for (int i = 2; i <= MAXN; i += 2, t = 1LL * t * INV2 % MOD)

    coef[i] = 1LL * fct[i] * ifct[i / 2] % MOD * t % MOD;
}

int dp[MAXN + 5][MAXN + 5], siz[MAXN + 5];

void dfs(int x, int f) {

  dp[x][siz[x] = 1] = 1;

  for (edge *p = adj[x]; p; p = p->nxt) {

    if (p->to == f)
      continue;

    dfs(p->to, x);

    int t1 = siz[x], t2 = siz[p->to], del = 0;

    for (int i = 2; i <= t2; i += 2)

      del = (del + 1LL * dp[p->to][i] * coef[i] % MOD) % MOD;

    del = (MOD - del) % MOD;

    for (int i = t1; i >= 1; i--) {

      for (int j = t2; j >= 1; j--)

        dp[x][i + j] =
            (dp[x][i + j] + 1LL * dp[x][i] * dp[p->to][j] % MOD) % MOD;

      dp[x][i] = 1LL * del * dp[x][i] % MOD;
    }

    siz[x] += siz[p->to];
  }
}

int main() {

  int N;
  init();

  scanf("%d", &N);

  for (int i = 1; i < N; i++) {

    int x, y;
    scanf("%d%d", &x, &y);

    addedge(x, y);
  }

  dfs(1, 0);

  int ans = 0;

  for (int i = 1; i <= N; i++)

    ans = (ans + 1LL * dp[1][i] * coef[i] % MOD) % MOD;

  printf("%d\n", ans);
}
