int gcd(int a, int b) {

  int c = a % b;

  while (c != 0) {

    a = b;

    b = c;

    c = a % b;
  }

  return b;
}

struct UnionFind {

  vector<int> par;

  UnionFind(int N) : par(N) {

    for (int i = 0; i < N; i++)
      par[i] = i;
  }

  int root(int x) {

    if (par[x] == x)
      return x;

    return par[x] = root(par[x]);
  }

  void unite(int x, int y) {

    int rx = root(x);

    int ry = root(y);

    if (rx == ry)
      return;

    par[rx] = ry;
  }

  bool same(int x, int y) {

    int rx = root(x);

    int ry = root(y);

    return rx == ry;
  }
};

typedef long long ll;

const ll M = 1000000007;

vector<ll> fac(300001);

vector<ll> ifac(300001);

ll mpow(ll x, ll n) {

  ll ans = 1;

  while (n != 0) {

    if (n & 1)
      ans = ans * x % M;

    x = x * x % M;

    n = n >> 1;
  }

  return ans;
}

ll comb(ll a, ll b) {

  if (a == 0 && b == 0)
    return 1;

  if (a < b || a < 0)
    return 0;

  ll tmp = ifac[a - b] * ifac[b] % M;

  return tmp * fac[a] % M;
}

long long modinv(long long a) {

  long long b = M, u = 1, v = 0;

  while (b) {

    long long t = a / b;

    a -= t * b;
    swap(a, b);

    u -= t * v;
    swap(u, v);
  }

  u %= M;

  if (u < 0)
    u += M;

  return u;
}

