  std::map<int, int> indexmap;

  std::set<std::pair<int, int>> square;

  for (int i = 0; i < N; i++) {

    std::cin >> a[i] >> b[i];

    a[i]--;

    b[i]--;

    row.insert(a[i]);
  }

  int counter = 0;

  for (int s : row) {

    indexmap[s] = counter;

    counter++;
  }

