      for (int rr = std::max(1, r - 1); rr <= std::min(H - 2, r + 1); rr++) {

        for (int cc = std::max(1, c - 1); cc <= std::min(W - 2, c + 1); cc++) {

          square.insert(std::make_pair(rr, cc));
        }
      }
    }
