    int c = entry.second;

    int num = 0;

    for (int rr = r - 1; rr <= r + 1; rr++) {

      for (int cc = c - 1; cc <= c + 1; cc++) {

        if (row.find(rr) != row.end()) {

          if (point[indexmap[rr]].find(cc) != point[indexmap[rr]].end()) {

            num++;
          }
        }
      }
    }

    cnt[num]++;
  }

