struct process {

  string name;

  int time;
};

process Q[MAXN];

int head, tail;

int n, q, total_time = 0;

void enqueue(process x) {

  Q[tail] = x;

  tail++;

  tail %= MAXN;
}

process dequeue() {

  process x = Q[head];

  head++;

  head %= MAXN;

  return x;
}

bool isEmpty() { return head == tail; }

