  int V = 0, E = 0;

  typedef std::pair<std::pair<int, int>, long long> P;

  std::vector<int> UF, rank;

  std::vector<std::pair<std::pair<int, int>, long long>> es;

  bool comp(P F, P G) { return F.second < G.second; }

  int root(int k) {

    if (UF[k] == k) {

      return k;

    } else {

      UF[k] = root(UF[k]);

      return UF[k];
    }
  }

  bool same(int p, int q) { return root(p) == root(q); }

  void unite(int P, int Q) {

    int p = root(P);

    int q = root(Q);

    if (p == q)
      return;

    if (rank[p] < rank[q])
      std::swap(p, q);

    UF[q] = p;

    if (rank[p] == rank[q])
      rank[p]++;
  }

public:
  std::vector<P> solve(std::vector<P> edge) {

    V = 0;

    for (int i = 0; i < edge.size(); i++) {

      V = std::max(V, edge[i].first.first + 1);

      V = std::max(V, edge[i].first.second + 1);
    }

    E = edge.size();

    UF.clear();

    rank.clear();

    for (int i = 0; i < V; i++) {

      UF.push_back(i);

      rank.push_back(0);
    }

    std::sort(edge.begin(), edge.end(), [&](P x, P y) { return comp(x, y); });

    es = edge;

    std::vector<P> R;

    for (int i = 0; i < E; i++) {

      if (!same(es[i].first.first, es[i].first.second)) {

        unite(es[i].first.first, es[i].first.second);

        R.push_back(es[i]);
