#include <bits/stdc++.h>

namespace FastIn {

static constexpr size_t BUF_SIZE = 1 << 17, INT_LEN = 24, FLT_LEN = 400;

static char buf[BUF_SIZE | 1] = {}, *pos = buf, *endbuf = nullptr;

FILE *fin;

inline bool rebuffer() {

  size_t rest = endbuf - pos;

  if (buf + rest > pos) {

    return true;
  }

  std::memcpy(buf, pos, rest);

  pos = buf;

  size_t len = std::fread(pos + rest, 1, BUF_SIZE - rest, fin);

  *(endbuf = buf + (rest + len)) = 0;

  return *pos;
}

inline bool scan(char &in) {

  if ((in = *pos)) {

    ++pos;

    return true;
  }

  return rebuffer() && (in = *pos++);
}

inline bool scan(char *in) {

  if ((*in = *pos) == 0) {

    if (rebuffer() && (*in = *pos) == 0) {

      return false;
    }
  }

  ++in;

  while (true) {

    if ((*in = *pos++) == 0) {

      if (rebuffer() && (*in = *pos++) == 0) {

        return true;
      }
    }

    ++in;
  }
}

inline bool scan(double &in) {

  if (pos + FLT_LEN >= endbuf && !rebuffer()) {

    in = 0.0;

    return false;
  }

  char *tmp;

  in = std::strtod(pos, &tmp);

  pos = tmp;

  return true;
}

template <class Int>

inline bool scan(Int &in) {

  in = 0;

  if (pos + INT_LEN >= endbuf && !rebuffer()) {

    return false;
  }

  if (std::is_signed<Int>::value) {

    if (*pos == '-') {

      in = ~*++pos + '1';

      while (*++pos >= '0') {

        in = in * 10 + ~*pos + '1';
      }

      ++pos;

      return true;
    }
  }

  do {

    in = in * 10 + *pos - '0';

  } while (*++pos >= '0');

  ++pos;

  return true;
}

inline bool eat() {

  if (*pos > ' ') {

    return true;
  }

  do {

    if (*pos == 0 && !rebuffer()) {

      return false;
    }

  } while (*++pos <= ' ');

  return true;
}

inline bool eat(char ch) {

  if (*pos == ch) {

    return true;
  }

  do {

    if (*pos == 0 && !rebuffer()) {

      return false;
    }

  } while (*++pos != ch);

  return true;
}

