  for (int i = 0; i < max_exp; ++i) {

    size_t num[256] = {};

    for (RandomIt it = first; it < last; ++it)

      ++num[((it->first) >> cur_shift) & 255];

    {

      size_t tmp = 0;

      for (int j = 0; j < 256; ++j)

        std::swap(tmp, num[j] += tmp);
