      size_t j = 0;

      for (RandomIt it = first; it < last; ++it)

        *it = work[j++];
    }

    cur_shift += 8;
  }

  if (!std::is_signed<KeyType>::value)
    return;

  RandomIt mid = last;

  for (RandomIt it = last; --it >= first;)

    if ((it->first) >= 0) {

      mid = ++it;

      break;
    }

  if (mid == last)

    return;

  std::copy(first, mid, work.begin() + (last - mid));

  std::copy(mid, last, work.begin());

  std::copy(work.begin(), work.end(), first);
}

