int binarysearch(int *S, int size, int key)

{

  int left = 0, right = size;

  int mid;

  while (left < right) {

    mid = (left + right) / 2;

    if (S[mid] == key) {

      return mid;

    } else if (key < S[mid]) {

      right = mid;

    } else if (key < S[mid + 1]) {

      return size;

    } else {

      left = mid + 1;
    }
  };

  return size;
}

