  {

    dis[i] = maps[i][x];

    vis[i] = 0;
  }

  for (i = 0; i <= n; i++)

  {

    Min = Max;

    for (j = 0; j <= n; j++)

    {

      if (vis[j] == 0 && dis[j] < Min)

