using namespace std;

const int MAXN = 100010;

const int MOD = 1e9 + 7;

int n;

struct edge {

  int next, to;

  edge(int N = 0, int T = 0) : next(N), to(T) {}

} e[MAXN << 1];

int fir[MAXN], num = 0;

inline void join(int a, int b) {
  e[++num] = edge(fir[a], b);
  fir[a] = num;
}

int f[MAXN][2];

void dfs(int u, int fa)

{

  f[u][0] = 1ll;
  f[u][1] = 1ll;

  for (int i = fir[u]; i; i = e[i].next)

  {

    int v = e[i].to;

    if (v == fa)
      continue;

    dfs(v, u);

    f[u][1] = 1ll * f[u][1] * f[v][0] % MOD;

    f[u][0] = 1ll * f[u][0] * (1ll * f[v][0] + f[v][1]) % MOD;
  }
}

int main()

{

  scanf("%d", &n);

  for (int i = 1, a, b; i < n; i++)

    scanf("%d%d", &a, &b), join(a, b), join(b, a);

  dfs(1, 0);

  printf("%d\n", (1ll * f[1][0] + f[1][1]) % MOD);

  return 0;
}
