double dp2[N];

double ans[N];

void dfs(int i, int p = -1) {

  int sz = (g[i].size() - (p != -1));

  for (int j : g[i])
    if (j != p) {

      dfs(j, i);

      dp[i] += (1 + dp1[j]);

      dp1[i] += (1 + dp1[j]) / sz;
    }
}

void dfs2(int i, int p = -1) {

  ans[i] = dp[i] + (p != -1 ? dp2[i] : 0);

  for (int j : g[i])
    if (j != p) {

      dp2[j] = 1 + (ans[i] - (1 + dp1[j])) / (g[i].size() - 1);

      dfs2(j, i);
    }

  ans[i] /= g[i].size();
}

int main() {

  ios::sync_with_stdio(false), cin.tie(0);

  int n;

  cin >> n;

  if (n == 1) {

    cout << 0.0 << endl;

    return 0;
  }

  if (n == 2) {

    cout << 1.0 << endl;

    cout << 1.0 << endl;

    return 0;
