  std::vector<std::vector<T>> R;

  dig_f_type dig;

  after_f_type after;

  static T default_dig(const T &a, ...) { return a; }

  static T default_after(const T &a, ...) { return a; }

  bool built;

  ReRooting() {}

  ReRooting(size_type n, dig_f_type dig = default_dig,
            after_f_type after = default_after)

