    dp.resize(n);

    dp.assign(n, std::vector<T>());

    did.resize(n);

    did.assign(n, vector_bool_type());

    L.resize(n);

    L.assign(n, std::vector<T>());

    R.resize(n);

    R.assign(n, std::vector<T>());

    built = 0;
  }

  size_type added = 0;

  void add_edge(size_type a, size_type b,
                size_type id = static_cast<size_type>(-1)) {

    assert(!built);

    assert(a < n && b < n && a != b);

    if (id == static_cast<size_type>(-1))
      id = added;

    graph[a].emplace_back(b, graph[b].size(), id);

    graph[b].emplace_back(a, graph[a].size() - 1, id);

    added++;
  }

  void set_dig(dig_f_type dig = default_dig) { this->dig = dig; }

  void set_after(after_f_type after = default_after) { this->after = after; }

