    assert(built);

    assert(j < n);
  }

private:
  T proceed_root(size_type i) {

    for (auto to : graph[i]) {

      size_type j, rev, edge_id;

      std::tie(j, rev, edge_id) = to;

      L[i].push_back(dig(dp[j][rev], edge_id, i, j));
    }

    R[i] = L[i];

