        did[i][p] = 1;

        T res = Monoid::identity();

        if (p == graph[i].size()) {

          res = proceed_root(i);

        } else {

          res = Monoid::op(p >= 1 ? L[i][p - 1] : Monoid::identity(),

                           p + 1 < R[i].size() ? R[i][p + 1]
                                               : Monoid::identity());
        }

        dp[i][p] = after(res, i, deg);

      } else {

        stk.emplace_back(i, p, 1);

        if (p == graph[i].size()) {

          for (size_type x = 0; x < graph[i].size(); x++) {

            size_type j, rev, edge_id;

            std::tie(j, rev, edge_id) = graph[i][x];

            if (!did[j][rev])
              stk.emplace_back(j, rev, 0);
          }

        } else {

          if (!did[i][graph[i].size()]) {

            stk.emplace_back(i, graph[i].size(), 0);
          }
        }
