    if (SetFind(u) != SetFind(v))

      fa[SetFind(u)] = SetFind(v), blkcnt--;
  }

  for (int i = 1; i <= n; i++)

    blk[SetFind(i)].push_back(val[i]);

  if (blkcnt <= 1)

  {

