    scanf("%d%d", &x, &y);

    F[find(x)] = find(y);
  }

  for (int i = 0; i < n; i++)

    M[i] = std::make_pair(A[i], i);

  for (int i = 0; i < n; i++)

    checkmin(M[find(i)], M[i]);

  long long ans = 0;

  int cnt = 0;

  for (int i = 0; i < n; i++)

    if (find(i) == i)

    {

      ans += M[i].first, cnt++;

      used[M[i].second] = true;
    }

