{

  return fa1[u] == u ? u : fa1[u] = findroot1(fa1[u]);
}

int findroot2(int u)

{

  return fa2[u] == u ? u : fa2[u] = findroot2(fa2[u]);
}

set<int> s2[N];

int ans[N];

int main()

{

  int n, k, l;

  int u, v;

  scanf("%d%d%d", &n, &k, &l);

  for (int i = 1; i <= n; i++)
    fa1[i] = fa2[i] = i;

  for (int i = 1; i <= k; i++)

  {

    scanf("%d%d", &u, &v);

    int uu = findroot1(u);

    int vv = findroot1(v);

    if (uu == vv)
