#include <cstdio>

#include <cstdlib>

#include <vector>

#include <algorithm>

using namespace std;

const int MAXN = 100005;

void NoSolution()

{

  puts("NO");

  fclose(stdin);

  fclose(stdout);

  exit(0);
}

int n, A[MAXN];

vector<int> adj[MAXN];

int dfs(int u, int fa = 0)

{

  if (adj[u].size() == 1U)

    return A[u];

  long long sum = 0;

  int tmp = 0, mx = 0;

  for (int i = 0; i < (int)adj[u].size(); i++)

  {

    int v = adj[u][i];

    if (v == fa)

      continue;

    tmp = dfs(v, u);

    mx = max(mx, tmp);

    sum += tmp;
  }

  if (fa == 0)

  {

    if (sum % 2 == 1 || mx > sum / 2 || A[u] != sum / 2)

      NoSolution();

    return 0;
  }

  long long delta = sum - A[u];

  if (A[u] < delta || sum < A[u] || sum - mx < delta)

    NoSolution();

  return A[u] - delta;
}

int main()

{

  scanf("%d", &n);

