  int n, u, v;

  cin >> n >> u >> v;
  u--;
  v--;

  if (n % 2)
    return false;

  static int A[MN], B[MN];

  for (int i = 1; i < n; i++) {

    int a, b;

    cin >> a >> b;
    a--;
    b--;

    A[i] = a;
    B[i] = b;

    g[a].push_back(b);

