template <class reroot_structure_type>

class ReRooting {

private:
  const unsigned int n;

  const unsigned int theRoot;

  using element_t = typename reroot_structure_type::element_t;

  using weight_t = typename reroot_structure_type::weight_t;

  struct edge_t {

    unsigned int to;

    weight_t weight;

    edge_t(const unsigned int to = 0,

           const weight_t &weight = reroot_structure_type::id_weight())

        : to(to), weight(weight) {}
  };

  std::vector<element_t> dp;

  std::vector<std::vector<edge_t>> edge;

  std::vector<unsigned int> order;

  std::vector<unsigned int> parent;

  std::vector<std::vector<element_t>> SL;

  std::vector<std::vector<element_t>> SR;

  void make_order(void) {

    std::vector<bool> yet(n, true);

    order.resize(n);
    parent.resize(n);

    std::vector<unsigned int> stk;
    stk.reserve(n);

    unsigned int idx = 0;

    yet[theRoot] = false;

    stk.emplace_back(theRoot);
    order[idx++] = theRoot;

    while (not stk.empty()) {

      unsigned int v = stk.back();
      stk.pop_back();

      for (const edge_t &x : edge[v])
        if (yet[x.to]) {

          yet[x.to] = false;

          parent[x.to] = v;
          order[idx++] = x.to;

          stk.emplace_back(x.to);
        }
    }
  }

  void dfs(void) {

    dp.assign(n, reroot_structure_type::id_merge());

    SL.assign(n, std::vector<element_t>(0));
    SR.assign(n, std::vector<element_t>(0));

    for (unsigned int i = 0; i < n; ++i) {

      SL[i].reserve(edge[i].size());
      SR[i].reserve(edge[i].size());
    }

    for (unsigned int i = n - 1; i > 0; --i) {

      const unsigned int v = order[i];
      const unsigned int nv = parent[v];

      dp[v] = reroot_structure_type::update(dp[v]);

      SL[nv].push_back(dp[v]);
      SR[nv].push_back(dp[v]);

      dp[nv] = reroot_structure_type::merge(dp[v], dp[nv]);
    }

    {

      const unsigned int v = order[0];

      const unsigned int sz = SL[v].size();

      dp[v] = reroot_structure_type::update(dp[v]);

      element_t vl = reroot_structure_type::id_merge(),
                vr = reroot_structure_type::id_merge();

      for (unsigned int j1 = 0, j2 = sz - 1; j1 < sz; ++j1, --j2) {

        SR[v][j1] = reroot_structure_type::merge(SR[v][j1], vr);
        std::swap(SR[v][j1], vr);

        SL[v][j2] = reroot_structure_type::merge(vl, SL[v][j2]);
        std::swap(SL[v][j2], vl);
      }

      unsigned int idx = sz - 1;

      for (const edge_t &x : edge[v]) {

        const element_t tmp = reroot_structure_type::update(
            reroot_structure_type::merge(SL[v][idx], SR[v][idx]));

        dp[x.to] = reroot_structure_type::merge(tmp, dp[x.to]);

        SL[x.to].push_back(tmp);
        SR[x.to].push_back(tmp);

        --idx;
      }
    }

    for (unsigned int i = 1; i < n; ++i) {

      const unsigned int v = order[i];

      const unsigned int sz = SL[v].size();

      element_t vl = reroot_structure_type::id_merge(),
                vr = reroot_structure_type::id_merge();

      for (unsigned int j1 = 0, j2 = sz - 1; j1 < sz; ++j1, --j2) {

        SR[v][j1] = reroot_structure_type::merge(SR[v][j1], vr);
        std::swap(SR[v][j1], vr);

        SL[v][j2] = reroot_structure_type::merge(vl, SL[v][j2]);
        std::swap(SL[v][j2], vl);
      }

      dp[v] = reroot_structure_type::update(vl);

      unsigned int idx = sz - 2;

      for (const edge_t &x : edge[v])
        if (x.to != parent[v]) {

          const element_t tmp = reroot_structure_type::update(
              reroot_structure_type::merge(SL[v][idx], SR[v][idx]));

          dp[x.to] = reroot_structure_type::merge(tmp, dp[x.to]);

          SL[x.to].push_back(tmp);
          SR[x.to].push_back(tmp);

          --idx;
        }
    }
  }

public:
  ReRooting(const unsigned int n, const unsigned int theRoot = 0)
      : n(n), theRoot(theRoot) {
    edge.assign(n, std::vector<edge_t>(0));
  }

  inline void add(const unsigned int u, const unsigned int v,
                  const weight_t &weight = reroot_structure_type::id_weight()) {

    edge[u].emplace_back(v, weight);
  }

  inline void build(void) {
    make_order();
    dfs();
  }

  inline const element_t &operator[](const unsigned int idx) const {
    return dp[idx];
  }
};

template <unsigned int modulus> struct modint {

  static_assert(modulus > 0, "modulus must be a positive integer.");

  int val;

  constexpr modint() : val(0) {}

  template <class T> constexpr modint(T v) : val() {

    val = v % (int)(modulus);

    if (val < 0)
      val += modulus;
  }

  constexpr modint &operator+=(const modint<modulus> other) noexcept {

    val += other.val;
    if (val >= modulus)
      val -= modulus;

    return *this;
  }

  constexpr modint &operator-=(const modint<modulus> other) noexcept {

    val -= other.val;
    if (val < 0)
      val += modulus;

    return *this;
  }

  constexpr modint &operator*=(const modint<modulus> other) noexcept {

    val = (unsigned long long int)(val)*other.val % modulus;

    return *this;
  }

  constexpr modint &operator/=(const modint<modulus> other) noexcept {

    val = (unsigned long long int)(val)*other.inverse() % modulus;

    return *this;
  }

  constexpr modint operator+(const modint<modulus> v) const noexcept {

    return modint<modulus>(*this) += v;
  }

  constexpr modint operator-(const modint<modulus> v) const noexcept {

    return modint<modulus>(*this) -= v;
  }

  constexpr modint operator*(const modint<modulus> v) const noexcept {

    return modint<modulus>(*this) *= v;
  }

  constexpr modint operator/(const modint<modulus> v) const noexcept {

    return modint<modulus>(*this) /= v;
  }

  constexpr modint &operator++(void) noexcept {

    if (++val == modulus)
      val = 0;

    return *this;
  }

  constexpr modint &operator--(void) noexcept {

    if (val-- == 0)
      val = modulus - 1;

    return *this;
  }

  constexpr modint operator-() const noexcept {

    return modint<modulus>((val == 0 ? 0 : modulus - val));
  }

  constexpr unsigned int inverse(unsigned int a) const noexcept {

    unsigned int b = modulus;

    int u = 1, v = 0;

    while (b != 0) {

      unsigned int t = a / b;

      a -= t * b;
      std::swap(a, b);

      u -= t * v;
      std::swap(u, v);
    }

    if (u < 0)
      u += modulus;

    return u;
  }

  constexpr unsigned int inverse(void) const noexcept { return inverse(val); }

  constexpr unsigned int power(unsigned long long int a,
                               long long int n) const noexcept {

    if (n == 0)
      return 1;

    unsigned long long res = 1, waiting = a;

    if (n < 0)
      waiting = inverse(), n = -n;

    while (n != 0) {

      if ((n & 1UL) != 0) {
        res *= waiting;
        res %= modulus;
      }

      waiting *= waiting;
      waiting %= modulus;

      n /= 2;
    }

    return res;
  }

  constexpr unsigned int power(long long int n) const noexcept {
    return power(val, n);
  }
};

template <std::size_t N, unsigned int modulus>

struct combinationMod {

public:
  modint<modulus> Power[N + 1];

  modint<modulus> powInverse[N + 1];

  modint<modulus> inverse[N + 1];

  constexpr combinationMod(void) : Power(), powInverse(), inverse() {

    Power[0] = 1;

    int x = 0;
    modint<modulus> mx;

    for (x = 1, mx = 1; x <= N; ++x, ++mx)
      Power[x] = Power[x - 1] * mx;

    powInverse[N] = Power[N].inverse();

    for (x = N, mx = N; x > 0; --x, --mx) {

      powInverse[x - 1] = powInverse[x] * mx;

      inverse[x] = powInverse[x] * Power[x - 1];
    }

    inverse[0] = 1;
  }

  constexpr modint<modulus> combination(int n, int k) const {

    if (k < 0 or n < k)
      return modint<modulus>();

    return Power[n] * powInverse[k] * powInverse[n - k];
  }
};

