template <const unsigned int M> struct shuumai {

public:
  unsigned long long int P[M + 1];

  unsigned long long int Inv[M + 1];

  unsigned long long int inv[M + 1];

  constexpr shuumai(void) : P(), Inv(), inv() {

    P[0] = 1;
    P[1] = 1;

    for (unsigned int x = 1, y = 2; x < M; ++x, ++y)
      P[y] = (P[x] * y) % mod;

    Inv[M] = inverse(P[M]);

    for (unsigned int x = M, y = M - 1; x; --x, --y) {

      Inv[y] = (Inv[x] * x) % mod;

      inv[x] = (P[y] * Inv[x]) % mod;
    }

    inv[0] = 1;
  }

  constexpr unsigned int inverse(unsigned int a) const noexcept {

    unsigned int b = mod;

    int u = 1, v = 0;

    while (b) {

      unsigned int t = a / b;

      a -= t * b;
      {
        const unsigned int tmp = a;
        a = b;
        b = tmp;
      }

      u -= t * v;
      {
        const unsigned int tmp = u;
        u = v;
        v = tmp;
      }
    }

    if (u < 0)
      u += mod;

    return u;
  }
};

