template <class T> std::vector<unsigned int> z_algorithm(const T &str) {

  const size_t n = str.size();

  std::vector<unsigned int> resOfCP(n);
  resOfCP[0] = n;

  int i = 1, j = 0;

  while (i < n) {

    while (i + j < n and str[j] == str[i + j])
      ++j;

    resOfCP[i] = j;

    if (j == 0) {
      ++i;
      continue;
    }

    int k = 1;

    while (i + k < n and k + resOfCP[k] < j)
      resOfCP[i + k] = resOfCP[k], ++k;

    i += k;
    j -= k;
  }

  return resOfCP;
}

