    cin >> u >> v;
    --u;
    --v;

    RRT.add(u, v);
    RRT.add(v, u);
  }

  RRT.build();

  for (unsigned int i = 0; i < n; ++i)
    cout << RRT[i].first.val << eol;

  return 0;
}
